insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (288, 29, 46, 55, 'سورة العنكبوت ٤٦ – ٥٥', '«ولا تجادلوا أهل الكتاب إلا بالتي هي أحسن»، و«وما كنت تتلو من قبله من كتاب ولا تخطّه بيمينك»، و«أوَلم يكفهم أنا أنزلنا عليك الكتاب»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 288) = $j$[{"lbl": "الآيات ٤٦ – ٤٩", "q": "۞وَلَا تُجَٰدِلُوٓاْ أَهۡلَ ٱلۡكِتَٰبِ إِلَّا بِٱلَّتِي هِيَ أَحۡسَنُ إِلَّا ٱلَّذِينَ ظَلَمُواْ مِنۡهُمۡۖ وَقُولُوٓاْ ءَامَنَّا بِٱلَّذِيٓ أُنزِلَ إِلَيۡنَا وَأُنزِلَ إِلَيۡكُمۡ وَإِلَٰهُنَا وَإِلَٰهُكُمۡ وَٰحِدٞ وَنَحۡنُ لَهُۥ مُسۡلِمُونَ ﴿٤٦﴾ وَكَذَٰلِكَ أَنزَلۡنَآ إِلَيۡكَ ٱلۡكِتَٰبَۚ فَٱلَّذِينَ ءَاتَيۡنَٰهُمُ ٱلۡكِتَٰبَ يُؤۡمِنُونَ بِهِۦۖ وَمِنۡ هَـٰٓؤُلَآءِ مَن يُؤۡمِنُ بِهِۦۚ وَمَا يَجۡحَدُ بِـَٔايَٰتِنَآ إِلَّا ٱلۡكَٰفِرُونَ ﴿٤٧﴾ وَمَا كُنتَ تَتۡلُواْ مِن قَبۡلِهِۦ مِن كِتَٰبٖ وَلَا تَخُطُّهُۥ بِيَمِينِكَۖ إِذٗا لَّٱرۡتَابَ ٱلۡمُبۡطِلُونَ ﴿٤٨﴾ بَلۡ هُوَ ءَايَٰتُۢ بَيِّنَٰتٞ فِي صُدُورِ ٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَۚ وَمَا يَجۡحَدُ بِـَٔايَٰتِنَآ إِلَّا ٱلظَّـٰلِمُونَ ﴿٤٩﴾", "w": [["ولا تجادلوا أهل الكتاب", "لا تحاجّوا ولا تناظروا اليهود ولا النصارى."], ["إلا بالتي هي أحسن", "إلا بالمجادلة التي هي أحسن، وهي الدعوة إلى الله بآياته والتنبيه على حججه."], ["إلا الذين ظلموا منهم", "الذين لم يدخلوا في ذمة المسلمين وبقوا حرباً عليهم."], ["وكذلك أنزلنا إليك الكتاب", "كإنزالنا الكتاب على من قبلك من الرسل."], ["فالذين آتيناهم الكتاب يؤمنون به", "كعبد الله بن سلام وإخوانه."], ["ومن هؤلاء من يؤمن به", "من المشركين، وقد آمن كثير منهم."], ["ولا تخطّه بيمينك", "لا تكتب بيدك، لأنك أميّ لا تقرأ ولا تكتب."], ["لارتاب المبطلون", "لشكّ اليهود في نبوّتك."], ["بل هو آيات بيّنات", "محمد ﷺ، نعوته وصفاته آيات بيّنات في التوراة والإنجيل محفوظة في صدور العلماء."]], "m": "هذا تعليم للرسول ﷺ والمؤمنين يأخذون به عندما يتّصلون بأهل الكتاب: ولا تجادلوا اليهود والنصارى إلا بالمجادلة التي هي أحسن، بدعوتهم إلى الإيمان والتنبيه على حجج الله، إلا الذين ظلموا منهم فلم يدخلوا في ذمة المسلمين وناصبوهم الحرب، فهؤلاء لا يُجادَلون بل يُقاتَلون حتى يعطوا الجزية. وإن أخبروكم بشيء لا يثبته الإسلام ولا ينفيه فقولوا: آمنا بالذي أُنزل إلينا وأُنزل إليكم، وإلهنا وإلهكم واحد ونحن له مسلمون، حتى لا نكذّب بحق ولا نؤمن بباطل، وفي البخاري: «لا تصدّقوا أهل الكتاب ولا تكذّبوهم». وكما أنزلنا الكتب على من قبلك أنزلنا إليك القرآن، فالراسخون من أهل الكتاب يؤمنون به، ومن المشركين من يؤمن به، فكان الأمر كما أخبر، وما يجحد بآياتنا إلا الكافرون. وما كنت تقرأ قبل القرآن كتاباً ولا تخطّه بيمينك، لأنك أميّ، ولو كنت تقرأ وتكتب لكان للمبطلين مجال للشك، بل أنت ونعوتك، ومنها الأمية، آيات بيّنات في التوراة والإنجيل محفوظة في صدور علمائهم، وما يجحد بها إلا الظالمون أنفسهم بكتمان الحق.", "h": ["مشروعية مجادلة أهل الكتاب من أهل الذمة بالتي هي أحسن.", "حرمة سؤال أهل الكتاب، لقوله ﷺ: «لا تسألوا أهل الكتاب عن شيء، فإنهم لن يهدوكم وقد ضلّوا».", "منع تصديق أهل الكتاب أو تكذيبهم إذا أخبروا بشيء، ووجوب قول: «آمنا بالذي أُنزل إلينا وأُنزل إليكم، وإلهنا وإلهكم واحد ونحن له مسلمون».", "إخبار القرآن بالغيب قبل وقوعه فيقع كما أخبر، فيكون ذلك آية على أنه وحي الله.", "تقرير صفة الأمية في النبي ﷺ كما هي في الكتب السابقة."], "k": "«ولا تجادلوا… إلا بالتي هي أحسن»… في آخر نقاش لي مع مخالف، هل كان أسلوبي أحسن أم أشدّ؟"}, {"lbl": "الآيات ٥٠ – ٥٢", "q": "وَقَالُواْ لَوۡلَآ أُنزِلَ عَلَيۡهِ ءَايَٰتٞ مِّن رَّبِّهِۦۚ قُلۡ إِنَّمَا ٱلۡأٓيَٰتُ عِندَ ٱللَّهِ وَإِنَّمَآ أَنَا۠ نَذِيرٞ مُّبِينٌ ﴿٥٠﴾ أَوَلَمۡ يَكۡفِهِمۡ أَنَّآ أَنزَلۡنَا عَلَيۡكَ ٱلۡكِتَٰبَ يُتۡلَىٰ عَلَيۡهِمۡۚ إِنَّ فِي ذَٰلِكَ لَرَحۡمَةٗ وَذِكۡرَىٰ لِقَوۡمٖ يُؤۡمِنُونَ ﴿٥١﴾ قُلۡ كَفَىٰ بِٱللَّهِ بَيۡنِي وَبَيۡنَكُمۡ شَهِيدٗاۖ يَعۡلَمُ مَا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۗ وَٱلَّذِينَ ءَامَنُواْ بِٱلۡبَٰطِلِ وَكَفَرُواْ بِٱللَّهِ أُوْلَـٰٓئِكَ هُمُ ٱلۡخَٰسِرُونَ ﴿٥٢﴾", "w": [["لولا أُنزل عليه آيات", "هلّا أُنزل على محمد آيات من ربه كناقة صالح وعصا موسى."], ["قل إنما الآيات عند الله", "ينزلها متى شاء."], ["أوَلم يكفهم أنا أنزلنا عليك الكتاب", "فيما طلبوا من الآيات."], ["إن في ذلك لرحمة وذكرى", "في القرآن رحمة وموعظة للمؤمنين، فهو خير من الناقة والعصا."], ["والذين آمنوا بالباطل", "وهو ما يُعبد من دون الله."], ["وكفروا بالله", "وهو الإله الحق."], ["أولئك هم الخاسرون", "حيث استبدلوا الكفر بالإيمان."]], "m": "ما زال السياق في تقرير النبوة: وقال أهل مكة: هلّا أُنزل على محمد معجزات خارقة كناقة صالح وعصا موسى ومائدة عيسى. قل لهم: أولاً، الآيات عند الله ينزلها متى شاء، وثانياً، إنما أنا نذير مبين، وظيفتي الإنذار. وثالثاً، أوَلم يكفهم آية أنا أنزلنا عليك الكتاب يُتلى عليهم صباح مساء؟ أيّ آية أعظم من كتاب يتلوه أمّي لا يقرأ ولا يكتب، يحمل الهدى والنور، وهو رحمة وموعظة لقوم يؤمنون، معجزة باقية، لا كمعجزة تبقى ساعة ثم تذهب. ورابعاً، كفى بالله بيني وبينكم شهيداً، يعلم ما في السماوات والأرض، فشهد لي بالرسالة بإنزاله عليّ هذا الكتاب. والذين آمنوا بالباطل، تأليه المخلوقات، وكفروا بالله، أولئك هم الخاسرون، إذ اشتروا الكفر بالإيمان.", "h": ["تقرير النبوة المحمدية بالأدلة القاطعة التي لا تُرد.", "بيان أكبر معجزة لإثبات النبوة، وهي نزول القرآن، وفي البخاري: «ما من نبي إلا أُعطي ما على مثله آمن البشر، وكان الذي أوتيته وحياً أوحاه الله إليّ».", "القرآن الكريم رحمة وذكرى، أي عبرة وعظة للمؤمنين به.", "تقرير خسران المشركين في الدارين لاستبدالهم الباطل بالحق."], "k": "«أوَلم يكفهم أنا أنزلنا عليك الكتاب»… المعجزة بين يديّ كل يوم؛ فهل تكفيني فأقرؤها؟"}, {"lbl": "الآيات ٥٣ – ٥٥", "q": "وَيَسۡتَعۡجِلُونَكَ بِٱلۡعَذَابِ وَلَوۡلَآ أَجَلٞ مُّسَمّٗى لَّجَآءَهُمُ ٱلۡعَذَابُۚ وَلَيَأۡتِيَنَّهُم بَغۡتَةٗ وَهُمۡ لَا يَشۡعُرُونَ ﴿٥٣﴾ يَسۡتَعۡجِلُونَكَ بِٱلۡعَذَابِ وَإِنَّ جَهَنَّمَ لَمُحِيطَةُۢ بِٱلۡكَٰفِرِينَ ﴿٥٤﴾ يَوۡمَ يَغۡشَىٰهُمُ ٱلۡعَذَابُ مِن فَوۡقِهِمۡ وَمِن تَحۡتِ أَرۡجُلِهِمۡ وَيَقُولُ ذُوقُواْ مَا كُنتُمۡ تَعۡمَلُونَ ﴿٥٥﴾", "w": [["ويستعجلونك بالعذاب", "يطلبون منك تعجيل العذاب لهم."], ["ولولا أجل مسمّى", "وقت محدد للعذاب لا يتقدّمه ولا يتأخر عنه، لجاءهم."], ["وليأتينّهم بغتة", "فجأة من حيث لا يخطر لهم على بال."], ["وإن جهنم لمحيطة بالكافرين", "من كل جانب."], ["يوم يغشاهم العذاب", "من فوقهم ومن تحت أرجلهم."], ["ذوقوا ما كنتم تعملون", "يقول لهم الجبار ذلك توبيخاً."]], "m": "طالب المكذّبون بالعذاب تحدّياً للرسول ﷺ، فقال تعالى يحمل رسوله على التعجّب من حمقهم: ويستعجلونك بالعذاب، ولولا وقت محدد له لا يتقدّم ولا يتأخر لجاءهم العذاب، وليأتينّهم فجأة وهم لا يشعرون بوقت مجيئه. ثم كرّر التعجّب من سخف المشركين الذين لا يطيقون لسعة عقرب ويطالبون بالعذاب: يستعجلونك بالعذاب وإن جهنم لمحيطة بالكافرين لا محالة، يوم يغطّيهم العذاب من فوقهم ومن تحت أرجلهم، ويقول الجبار موبّخاً: ذوقوا ما كنتم تعملون من الشرك والمعاصي.", "h": ["مشروعية التعجّب إذا وُجدت أسبابه الحاملة عليه.", "بيان مدى حمق وجهل وسفه الكافرين، والمشركين بخاصة.", "بيان أن تأخير العذاب لم يكن عن عجز، وإنما هو لنظام دقيق، إذ كل شيء له أجل محدد لا يتقدّم ولا يتأخر."], "k": "«ولولا أجل مسمّى»… كل تأخير للعقوبة مهلة؛ فهل أستعمل مهلتي أم أستعجل ما لا أطيق؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 288;
insert into public.tdb_cards(topic, i, body) select 288, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٤٦ – ٤٩", "q": "۞وَلَا تُجَٰدِلُوٓاْ أَهۡلَ ٱلۡكِتَٰبِ إِلَّا بِٱلَّتِي هِيَ أَحۡسَنُ إِلَّا ٱلَّذِينَ ظَلَمُواْ مِنۡهُمۡۖ وَقُولُوٓاْ ءَامَنَّا بِٱلَّذِيٓ أُنزِلَ إِلَيۡنَا وَأُنزِلَ إِلَيۡكُمۡ وَإِلَٰهُنَا وَإِلَٰهُكُمۡ وَٰحِدٞ وَنَحۡنُ لَهُۥ مُسۡلِمُونَ ﴿٤٦﴾ وَكَذَٰلِكَ أَنزَلۡنَآ إِلَيۡكَ ٱلۡكِتَٰبَۚ فَٱلَّذِينَ ءَاتَيۡنَٰهُمُ ٱلۡكِتَٰبَ يُؤۡمِنُونَ بِهِۦۖ وَمِنۡ هَـٰٓؤُلَآءِ مَن يُؤۡمِنُ بِهِۦۚ وَمَا يَجۡحَدُ بِـَٔايَٰتِنَآ إِلَّا ٱلۡكَٰفِرُونَ ﴿٤٧﴾ وَمَا كُنتَ تَتۡلُواْ مِن قَبۡلِهِۦ مِن كِتَٰبٖ وَلَا تَخُطُّهُۥ بِيَمِينِكَۖ إِذٗا لَّٱرۡتَابَ ٱلۡمُبۡطِلُونَ ﴿٤٨﴾ بَلۡ هُوَ ءَايَٰتُۢ بَيِّنَٰتٞ فِي صُدُورِ ٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَۚ وَمَا يَجۡحَدُ بِـَٔايَٰتِنَآ إِلَّا ٱلظَّـٰلِمُونَ ﴿٤٩﴾", "w": [["ولا تجادلوا أهل الكتاب", "لا تحاجّوا ولا تناظروا اليهود ولا النصارى."], ["إلا بالتي هي أحسن", "إلا بالمجادلة التي هي أحسن، وهي الدعوة إلى الله بآياته والتنبيه على حججه."], ["إلا الذين ظلموا منهم", "الذين لم يدخلوا في ذمة المسلمين وبقوا حرباً عليهم."], ["وكذلك أنزلنا إليك الكتاب", "كإنزالنا الكتاب على من قبلك من الرسل."], ["فالذين آتيناهم الكتاب يؤمنون به", "كعبد الله بن سلام وإخوانه."], ["ومن هؤلاء من يؤمن به", "من المشركين، وقد آمن كثير منهم."], ["ولا تخطّه بيمينك", "لا تكتب بيدك، لأنك أميّ لا تقرأ ولا تكتب."], ["لارتاب المبطلون", "لشكّ اليهود في نبوّتك."], ["بل هو آيات بيّنات", "محمد ﷺ، نعوته وصفاته آيات بيّنات في التوراة والإنجيل محفوظة في صدور العلماء."]], "m": "هذا تعليم للرسول ﷺ والمؤمنين يأخذون به عندما يتّصلون بأهل الكتاب: ولا تجادلوا اليهود والنصارى إلا بالمجادلة التي هي أحسن، بدعوتهم إلى الإيمان والتنبيه على حجج الله، إلا الذين ظلموا منهم فلم يدخلوا في ذمة المسلمين وناصبوهم الحرب، فهؤلاء لا يُجادَلون بل يُقاتَلون حتى يعطوا الجزية. وإن أخبروكم بشيء لا يثبته الإسلام ولا ينفيه فقولوا: آمنا بالذي أُنزل إلينا وأُنزل إليكم، وإلهنا وإلهكم واحد ونحن له مسلمون، حتى لا نكذّب بحق ولا نؤمن بباطل، وفي البخاري: «لا تصدّقوا أهل الكتاب ولا تكذّبوهم». وكما أنزلنا الكتب على من قبلك أنزلنا إليك القرآن، فالراسخون من أهل الكتاب يؤمنون به، ومن المشركين من يؤمن به، فكان الأمر كما أخبر، وما يجحد بآياتنا إلا الكافرون. وما كنت تقرأ قبل القرآن كتاباً ولا تخطّه بيمينك، لأنك أميّ، ولو كنت تقرأ وتكتب لكان للمبطلين مجال للشك، بل أنت ونعوتك، ومنها الأمية، آيات بيّنات في التوراة والإنجيل محفوظة في صدور علمائهم، وما يجحد بها إلا الظالمون أنفسهم بكتمان الحق.", "h": ["مشروعية مجادلة أهل الكتاب من أهل الذمة بالتي هي أحسن.", "حرمة سؤال أهل الكتاب، لقوله ﷺ: «لا تسألوا أهل الكتاب عن شيء، فإنهم لن يهدوكم وقد ضلّوا».", "منع تصديق أهل الكتاب أو تكذيبهم إذا أخبروا بشيء، ووجوب قول: «آمنا بالذي أُنزل إلينا وأُنزل إليكم، وإلهنا وإلهكم واحد ونحن له مسلمون».", "إخبار القرآن بالغيب قبل وقوعه فيقع كما أخبر، فيكون ذلك آية على أنه وحي الله.", "تقرير صفة الأمية في النبي ﷺ كما هي في الكتب السابقة."], "k": "«ولا تجادلوا… إلا بالتي هي أحسن»… في آخر نقاش لي مع مخالف، هل كان أسلوبي أحسن أم أشدّ؟"}, {"lbl": "الآيات ٥٠ – ٥٢", "q": "وَقَالُواْ لَوۡلَآ أُنزِلَ عَلَيۡهِ ءَايَٰتٞ مِّن رَّبِّهِۦۚ قُلۡ إِنَّمَا ٱلۡأٓيَٰتُ عِندَ ٱللَّهِ وَإِنَّمَآ أَنَا۠ نَذِيرٞ مُّبِينٌ ﴿٥٠﴾ أَوَلَمۡ يَكۡفِهِمۡ أَنَّآ أَنزَلۡنَا عَلَيۡكَ ٱلۡكِتَٰبَ يُتۡلَىٰ عَلَيۡهِمۡۚ إِنَّ فِي ذَٰلِكَ لَرَحۡمَةٗ وَذِكۡرَىٰ لِقَوۡمٖ يُؤۡمِنُونَ ﴿٥١﴾ قُلۡ كَفَىٰ بِٱللَّهِ بَيۡنِي وَبَيۡنَكُمۡ شَهِيدٗاۖ يَعۡلَمُ مَا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۗ وَٱلَّذِينَ ءَامَنُواْ بِٱلۡبَٰطِلِ وَكَفَرُواْ بِٱللَّهِ أُوْلَـٰٓئِكَ هُمُ ٱلۡخَٰسِرُونَ ﴿٥٢﴾", "w": [["لولا أُنزل عليه آيات", "هلّا أُنزل على محمد آيات من ربه كناقة صالح وعصا موسى."], ["قل إنما الآيات عند الله", "ينزلها متى شاء."], ["أوَلم يكفهم أنا أنزلنا عليك الكتاب", "فيما طلبوا من الآيات."], ["إن في ذلك لرحمة وذكرى", "في القرآن رحمة وموعظة للمؤمنين، فهو خير من الناقة والعصا."], ["والذين آمنوا بالباطل", "وهو ما يُعبد من دون الله."], ["وكفروا بالله", "وهو الإله الحق."], ["أولئك هم الخاسرون", "حيث استبدلوا الكفر بالإيمان."]], "m": "ما زال السياق في تقرير النبوة: وقال أهل مكة: هلّا أُنزل على محمد معجزات خارقة كناقة صالح وعصا موسى ومائدة عيسى. قل لهم: أولاً، الآيات عند الله ينزلها متى شاء، وثانياً، إنما أنا نذير مبين، وظيفتي الإنذار. وثالثاً، أوَلم يكفهم آية أنا أنزلنا عليك الكتاب يُتلى عليهم صباح مساء؟ أيّ آية أعظم من كتاب يتلوه أمّي لا يقرأ ولا يكتب، يحمل الهدى والنور، وهو رحمة وموعظة لقوم يؤمنون، معجزة باقية، لا كمعجزة تبقى ساعة ثم تذهب. ورابعاً، كفى بالله بيني وبينكم شهيداً، يعلم ما في السماوات والأرض، فشهد لي بالرسالة بإنزاله عليّ هذا الكتاب. والذين آمنوا بالباطل، تأليه المخلوقات، وكفروا بالله، أولئك هم الخاسرون، إذ اشتروا الكفر بالإيمان.", "h": ["تقرير النبوة المحمدية بالأدلة القاطعة التي لا تُرد.", "بيان أكبر معجزة لإثبات النبوة، وهي نزول القرآن، وفي البخاري: «ما من نبي إلا أُعطي ما على مثله آمن البشر، وكان الذي أوتيته وحياً أوحاه الله إليّ».", "القرآن الكريم رحمة وذكرى، أي عبرة وعظة للمؤمنين به.", "تقرير خسران المشركين في الدارين لاستبدالهم الباطل بالحق."], "k": "«أوَلم يكفهم أنا أنزلنا عليك الكتاب»… المعجزة بين يديّ كل يوم؛ فهل تكفيني فأقرؤها؟"}, {"lbl": "الآيات ٥٣ – ٥٥", "q": "وَيَسۡتَعۡجِلُونَكَ بِٱلۡعَذَابِ وَلَوۡلَآ أَجَلٞ مُّسَمّٗى لَّجَآءَهُمُ ٱلۡعَذَابُۚ وَلَيَأۡتِيَنَّهُم بَغۡتَةٗ وَهُمۡ لَا يَشۡعُرُونَ ﴿٥٣﴾ يَسۡتَعۡجِلُونَكَ بِٱلۡعَذَابِ وَإِنَّ جَهَنَّمَ لَمُحِيطَةُۢ بِٱلۡكَٰفِرِينَ ﴿٥٤﴾ يَوۡمَ يَغۡشَىٰهُمُ ٱلۡعَذَابُ مِن فَوۡقِهِمۡ وَمِن تَحۡتِ أَرۡجُلِهِمۡ وَيَقُولُ ذُوقُواْ مَا كُنتُمۡ تَعۡمَلُونَ ﴿٥٥﴾", "w": [["ويستعجلونك بالعذاب", "يطلبون منك تعجيل العذاب لهم."], ["ولولا أجل مسمّى", "وقت محدد للعذاب لا يتقدّمه ولا يتأخر عنه، لجاءهم."], ["وليأتينّهم بغتة", "فجأة من حيث لا يخطر لهم على بال."], ["وإن جهنم لمحيطة بالكافرين", "من كل جانب."], ["يوم يغشاهم العذاب", "من فوقهم ومن تحت أرجلهم."], ["ذوقوا ما كنتم تعملون", "يقول لهم الجبار ذلك توبيخاً."]], "m": "طالب المكذّبون بالعذاب تحدّياً للرسول ﷺ، فقال تعالى يحمل رسوله على التعجّب من حمقهم: ويستعجلونك بالعذاب، ولولا وقت محدد له لا يتقدّم ولا يتأخر لجاءهم العذاب، وليأتينّهم فجأة وهم لا يشعرون بوقت مجيئه. ثم كرّر التعجّب من سخف المشركين الذين لا يطيقون لسعة عقرب ويطالبون بالعذاب: يستعجلونك بالعذاب وإن جهنم لمحيطة بالكافرين لا محالة، يوم يغطّيهم العذاب من فوقهم ومن تحت أرجلهم، ويقول الجبار موبّخاً: ذوقوا ما كنتم تعملون من الشرك والمعاصي.", "h": ["مشروعية التعجّب إذا وُجدت أسبابه الحاملة عليه.", "بيان مدى حمق وجهل وسفه الكافرين، والمشركين بخاصة.", "بيان أن تأخير العذاب لم يكن عن عجز، وإنما هو لنظام دقيق، إذ كل شيء له أجل محدد لا يتقدّم ولا يتأخر."], "k": "«ولولا أجل مسمّى»… كل تأخير للعقوبة مهلة؛ فهل أستعمل مهلتي أم أستعجل ما لا أطيق؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (289, 29, 56, 69, 'سورة العنكبوت ٥٦ – ٦٩', '«يا عبادي الذين آمنوا إن أرضي واسعة»، و«وإن الدار الآخرة لهي الحيوان»، و«والذين جاهدوا فينا لنهدينّهم سبلنا»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 289) = $j$[{"lbl": "الآيات ٥٦ – ٦٠", "q": "يَٰعِبَادِيَ ٱلَّذِينَ ءَامَنُوٓاْ إِنَّ أَرۡضِي وَٰسِعَةٞ فَإِيَّـٰيَ فَٱعۡبُدُونِ ﴿٥٦﴾ كُلُّ نَفۡسٖ ذَآئِقَةُ ٱلۡمَوۡتِۖ ثُمَّ إِلَيۡنَا تُرۡجَعُونَ ﴿٥٧﴾ وَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ لَنُبَوِّئَنَّهُم مِّنَ ٱلۡجَنَّةِ غُرَفٗا تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَاۚ نِعۡمَ أَجۡرُ ٱلۡعَٰمِلِينَ ﴿٥٨﴾ ٱلَّذِينَ صَبَرُواْ وَعَلَىٰ رَبِّهِمۡ يَتَوَكَّلُونَ ﴿٥٩﴾ وَكَأَيِّن مِّن دَآبَّةٖ لَّا تَحۡمِلُ رِزۡقَهَا ٱللَّهُ يَرۡزُقُهَا وَإِيَّاكُمۡۚ وَهُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ ﴿٦٠﴾", "w": [["إن أرضي واسعة", "هاجروا من بلاد لم تتمكّنوا من العبادة فيها، فإن أرضي واسعة."], ["فإياي فاعبدون", "اعبدوني وحدي ولا تعبدوا معي غيري."], ["كل نفس ذائقة الموت", "لا يمنعنّكم الخوف من الموت من الهجرة، فالموت لا بد منه للمهاجر وغيره."], ["ثم إلينا تُرجعون", "فمن مات في سبيل مرضاته أكرمه، ومن مات في معصيته عذّبه."], ["لنبوّئنّهم", "لننزلنّهم من الجنة غرفاً تجري من تحتها الأنهار."], ["الذين صبروا", "على الإيمان والهجرة، متوكّلين على الله."], ["وكأيّن من دابة لا تحمل رزقها", "لا تطيق جمعه ولا حمله لضعفها، والله يرزقها، فلا عذر لمن ترك الهجرة خوف الفقر."]], "m": "بعد ذلك التأنيب للمشركين كان ردّ فعلهم الضغط على المستضعفين بمكة، فأرشدهم الله إلى الهجرة: يا عبادي الذين آمنوا إن أرضي واسعة فهاجروا فيها، ولا ترضوا بالبقاء مع الكفر تُلزمون بعبادة غيري، فإياي فاعبدون. ولا تخشوا موتاً ولا فقراً، فكل نفس ذائقة الموت هاجر صاحبها أو لم يهاجر، ثم إلينا ترجعون، فمن رجع مؤمناً مطيعاً أسعدناه، ومن رجع كافراً عاصياً أشقيناه. والذين آمنوا وعملوا الصالحات، ومنها الهجرة، لننزلنّهم من الجنة غرفاً تجري من تحتها الأنهار خالدين فيها، نعم أجر العاملين، الذين صبروا على الإيمان والهجرة والطاعة، وعلى ربهم يتوكّلون، فخرجوا من ديارهم تاركين أموالهم بلا زاد. وكم من دابة من إنسان وحيوان تعجز عن حمل طعامها لضعفها، الله يرزقها وإياكم بما يسخّر من أسباب، فلا يمنعنّكم من الهجرة خوف الفاقة، وهو السميع لأقوالكم العليم ببواطنكم.", "h": ["لا عذر لأحد في ترك عبادة الله وتوحيده فيها، لأنه إن مُنع منها في بلد وجب عليه أن يهاجر.", "لا معنى للخوف من الموت إذا وجب العمل كالهجرة والجهاد، لأن الموت حق ولا بد منه.", "بيان جزاء أهل الصبر والتوكّل من أهل الإيمان والهجرة والتقوى.", "لا يمنعنّ المؤمنَ من الهجرة خوفُه من الجوع في دار هجرته، إذ تكفّل الله برزقه."], "k": "«وكأيّن من دابة لا تحمل رزقها الله يرزقها وإياكم»… كم مرة قدّمت خوف الرزق على أمر الله؟"}, {"lbl": "الآيات ٦١ – ٦٤", "q": "وَلَئِن سَأَلۡتَهُم مَّنۡ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ وَسَخَّرَ ٱلشَّمۡسَ وَٱلۡقَمَرَ لَيَقُولُنَّ ٱللَّهُۖ فَأَنَّىٰ يُؤۡفَكُونَ ﴿٦١﴾ ٱللَّهُ يَبۡسُطُ ٱلرِّزۡقَ لِمَن يَشَآءُ مِنۡ عِبَادِهِۦ وَيَقۡدِرُ لَهُۥٓۚ إِنَّ ٱللَّهَ بِكُلِّ شَيۡءٍ عَلِيمٞ ﴿٦٢﴾ وَلَئِن سَأَلۡتَهُم مَّن نَّزَّلَ مِنَ ٱلسَّمَآءِ مَآءٗ فَأَحۡيَا بِهِ ٱلۡأَرۡضَ مِنۢ بَعۡدِ مَوۡتِهَا لَيَقُولُنَّ ٱللَّهُۚ قُلِ ٱلۡحَمۡدُ لِلَّهِۚ بَلۡ أَكۡثَرُهُمۡ لَا يَعۡقِلُونَ ﴿٦٣﴾ وَمَا هَٰذِهِ ٱلۡحَيَوٰةُ ٱلدُّنۡيَآ إِلَّا لَهۡوٞ وَلَعِبٞۚ وَإِنَّ ٱلدَّارَ ٱلۡأٓخِرَةَ لَهِيَ ٱلۡحَيَوَانُۚ لَوۡ كَانُواْ يَعۡلَمُونَ ﴿٦٤﴾", "w": [["ولئن سألتهم", "المشركين."], ["وسخّر الشمس والقمر", "ذلّلهما يسيران الدهر كله لا يملّان ولا يفتران."], ["فأنّى يؤفكون", "كيف يُصرفون عن الحق بعد ظهور أدلته؟"], ["الله يبسط الرزق لمن يشاء", "يوسّع على من يشاء امتحاناً: هل يشكر أم يكفر؟"], ["ويقدر له", "يضيّق عليه ابتلاءً: هل يصبر أم يسخط؟"], ["قل الحمد لله", "على ثبوت الحجة عليكم."], ["بل أكثرهم لا يعقلون", "إنهم متناقضون في فهمهم وجوابهم."], ["إلا لهو ولعب", "بالنظر إلى العمل لها والعيش فيها، يخرج منها الإنسان بلا طائل."], ["لهي الحيوان", "الحياة الكاملة الخالدة، ولذا العمل لها أفضل."]], "m": "ما زال السياق في تقرير التوحيد: ولئن سألت هؤلاء المشركين الذين يضطهدون المؤمنين: من خلق السماوات والأرض وسخّر الشمس والقمر؟ ليقولنّ: الله، فكيف يُصرفون عن الحق بعد ظهور أدلته؟ الله يبسط الرزق لمن يشاء من عباده امتحاناً، ويضيّقه على من يشاء ابتلاءً، فلا يدل غنى المشركين ولا فقر المؤمنين على رضا ولا سخط، إن الله بكل شيء عليم، يعلم من يصلحه الغنى ومن يصلحه الفقر. ولئن سألتهم: من نزّل من السماء ماءً فأحيا به الأرض بعد موتها؟ ليقولنّ: الله، قل: الحمد لله على اعترافكم، فلمَ تعبدون غيره؟ بل أكثرهم لا يعقلون، يعترفون بربٍّ خالق رازق ثم يعكفون على الأصنام. وما هذه الحياة الدنيا التي أعمت الناس عن الآخرة إلا لهو ولعب، يتشاغل بها الكافر ويخرج منها صفر اليدين كالأطفال يلعبون النهار كله ثم يعودون بلا شيء، وإن الدار الآخرة لهي الحياة الكاملة الخالدة، فلها يعمل العاملون، لو كانوا يعلمون، فدواؤهم العلم.", "h": ["التعجّب من تناقض المشركين الذين يؤمنون بربوبية الله ويجحدون ألوهيته.", "بيان حقيقة أن الغنى والفقر لا يدلّان على رضا الرب ولا على سخطه، وإنما يدلّان على علم الله وحكمته وحسن تدبيره.", "بيان حقارة الدنيا وتفاهتها وعظمة الآخرة وعلوّ قيمتها، فلذا أحمق الناس من يعمى عن الآخرة ويبصر الدنيا."], "k": "«وإن الدار الآخرة لهي الحيوان»… كم من يومي ذهب في لعب أطفال كبار؟"}, {"lbl": "الآيات ٦٥ – ٦٩", "q": "فَإِذَا رَكِبُواْ فِي ٱلۡفُلۡكِ دَعَوُاْ ٱللَّهَ مُخۡلِصِينَ لَهُ ٱلدِّينَ فَلَمَّا نَجَّىٰهُمۡ إِلَى ٱلۡبَرِّ إِذَا هُمۡ يُشۡرِكُونَ ﴿٦٥﴾ لِيَكۡفُرُواْ بِمَآ ءَاتَيۡنَٰهُمۡ وَلِيَتَمَتَّعُواْۚ فَسَوۡفَ يَعۡلَمُونَ ﴿٦٦﴾ أَوَلَمۡ يَرَوۡاْ أَنَّا جَعَلۡنَا حَرَمًا ءَامِنٗا وَيُتَخَطَّفُ ٱلنَّاسُ مِنۡ حَوۡلِهِمۡۚ أَفَبِٱلۡبَٰطِلِ يُؤۡمِنُونَ وَبِنِعۡمَةِ ٱللَّهِ يَكۡفُرُونَ ﴿٦٧﴾ وَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوۡ كَذَّبَ بِٱلۡحَقِّ لَمَّا جَآءَهُۥٓۚ أَلَيۡسَ فِي جَهَنَّمَ مَثۡوٗى لِّلۡكَٰفِرِينَ ﴿٦٨﴾ وَٱلَّذِينَ جَٰهَدُواْ فِينَا لَنَهۡدِيَنَّهُمۡ سُبُلَنَاۚ وَإِنَّ ٱللَّهَ لَمَعَ ٱلۡمُحۡسِنِينَ ﴿٦٩﴾", "w": [["في الفلك", "في السفينة."], ["دعوا الله مخلصين له الدين", "دعوه وحده فلم يذكروا معه غيره."], ["إذا هم يشركون", "يفاجئونك بالشرك، وهو دعاء غير الله."], ["ليكفروا بما آتيناهم", "بنعمة الإنجاء من الغرق وغيرها."], ["ويُتخطّف الناس من حولهم", "يُسبون ويُقتلون في ديار جزيرتهم."], ["أفبالباطل يؤمنون", "بالأصنام، وهي الباطل."], ["والذين جاهدوا فينا", "بذلوا جهدهم في تصحيح عقائدهم وتزكية نفوسهم، ثم بقتال المحاربين للإسلام."], ["لنهدينّهم سبلنا", "لنوفّقنّهم إلى معرفة ما يوصل إلى محبّتنا ورضانا."]], "m": "ما زال السياق في التنديد بتناقض المشركين: فإذا ركبوا في سفينة واضطربت بهم وخافوا الغرق دعوا الله وحده مخلصين له الدعاء، فلما نجّاهم إلى البر إذا هم يشركون، ومردّ ذلك إلى الجهل والتقليد والعناد، فكأن عودتهم إلى الشرك ليكفروا بنعمة الإنجاء، وليتمتّعوا في دنياهم، فسوف يعلمون عاقبة ذلك. أوَلم يروا أنا جعلنا لهم حرماً آمناً لا يُعتدى عليهم فيه، والناس من حولهم في أطراف الجزيرة يُسبون ويُقتلون؟ أفبالشرك يصدّقون وبنعمة الله يكفرون؟ ومن أظلم ممن افترى على الله كذباً بتحريم ما أحلّ وتحليل ما حرّم وعبادة الأصنام، أو كذّب بالحق لما جاءه؟ أليس في جهنم مثوى للكافرين؟ والذين جاهدوا في سبيلنا طلباً لمرضاتنا، بإعلاء كلمتنا، وجاهدوا في ذات الله نفوسهم وأهواءهم والشيطان، لنهدينّهم سبل النجاة والفوز، وإن الله لمع المحسنين نياتهم وأعمالهم بعونه ونصره.", "h": ["بيان أن مشركي العرب لم يكونوا ملاحدة لا يؤمنون بالله، بل كانوا موحّدين في الربوبية مشركين في الألوهية.", "دعوة المشركين بتنبيههم بنعم الله عليهم لعلهم يشكرون.", "لا ظلم أعظم من ظلم من افترى على الله الكذب، وكذّب بالحق لما جاءه وعرفه فانصرف عنه مؤثراً دنياه.", "بشرى الله لمن جاهد المشركين وجاهد نفسه والهوى والشياطين بالهداية إلى سبل الفوز والنجاة في الدنيا والآخرة.", "فضل الإحسان، وهو إخلاص العبادة لله وأداؤها متقنة كما شرعها، وكون الله مع المحسنين بنصرهم وتأييدهم."], "k": "«والذين جاهدوا فينا لنهدينّهم سبلنا»… الهداية تأتي بعد المجاهدة؛ فما الذي أجاهد فيه نفسي اليوم؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 289;
insert into public.tdb_cards(topic, i, body) select 289, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٥٦ – ٦٠", "q": "يَٰعِبَادِيَ ٱلَّذِينَ ءَامَنُوٓاْ إِنَّ أَرۡضِي وَٰسِعَةٞ فَإِيَّـٰيَ فَٱعۡبُدُونِ ﴿٥٦﴾ كُلُّ نَفۡسٖ ذَآئِقَةُ ٱلۡمَوۡتِۖ ثُمَّ إِلَيۡنَا تُرۡجَعُونَ ﴿٥٧﴾ وَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ لَنُبَوِّئَنَّهُم مِّنَ ٱلۡجَنَّةِ غُرَفٗا تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَاۚ نِعۡمَ أَجۡرُ ٱلۡعَٰمِلِينَ ﴿٥٨﴾ ٱلَّذِينَ صَبَرُواْ وَعَلَىٰ رَبِّهِمۡ يَتَوَكَّلُونَ ﴿٥٩﴾ وَكَأَيِّن مِّن دَآبَّةٖ لَّا تَحۡمِلُ رِزۡقَهَا ٱللَّهُ يَرۡزُقُهَا وَإِيَّاكُمۡۚ وَهُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ ﴿٦٠﴾", "w": [["إن أرضي واسعة", "هاجروا من بلاد لم تتمكّنوا من العبادة فيها، فإن أرضي واسعة."], ["فإياي فاعبدون", "اعبدوني وحدي ولا تعبدوا معي غيري."], ["كل نفس ذائقة الموت", "لا يمنعنّكم الخوف من الموت من الهجرة، فالموت لا بد منه للمهاجر وغيره."], ["ثم إلينا تُرجعون", "فمن مات في سبيل مرضاته أكرمه، ومن مات في معصيته عذّبه."], ["لنبوّئنّهم", "لننزلنّهم من الجنة غرفاً تجري من تحتها الأنهار."], ["الذين صبروا", "على الإيمان والهجرة، متوكّلين على الله."], ["وكأيّن من دابة لا تحمل رزقها", "لا تطيق جمعه ولا حمله لضعفها، والله يرزقها، فلا عذر لمن ترك الهجرة خوف الفقر."]], "m": "بعد ذلك التأنيب للمشركين كان ردّ فعلهم الضغط على المستضعفين بمكة، فأرشدهم الله إلى الهجرة: يا عبادي الذين آمنوا إن أرضي واسعة فهاجروا فيها، ولا ترضوا بالبقاء مع الكفر تُلزمون بعبادة غيري، فإياي فاعبدون. ولا تخشوا موتاً ولا فقراً، فكل نفس ذائقة الموت هاجر صاحبها أو لم يهاجر، ثم إلينا ترجعون، فمن رجع مؤمناً مطيعاً أسعدناه، ومن رجع كافراً عاصياً أشقيناه. والذين آمنوا وعملوا الصالحات، ومنها الهجرة، لننزلنّهم من الجنة غرفاً تجري من تحتها الأنهار خالدين فيها، نعم أجر العاملين، الذين صبروا على الإيمان والهجرة والطاعة، وعلى ربهم يتوكّلون، فخرجوا من ديارهم تاركين أموالهم بلا زاد. وكم من دابة من إنسان وحيوان تعجز عن حمل طعامها لضعفها، الله يرزقها وإياكم بما يسخّر من أسباب، فلا يمنعنّكم من الهجرة خوف الفاقة، وهو السميع لأقوالكم العليم ببواطنكم.", "h": ["لا عذر لأحد في ترك عبادة الله وتوحيده فيها، لأنه إن مُنع منها في بلد وجب عليه أن يهاجر.", "لا معنى للخوف من الموت إذا وجب العمل كالهجرة والجهاد، لأن الموت حق ولا بد منه.", "بيان جزاء أهل الصبر والتوكّل من أهل الإيمان والهجرة والتقوى.", "لا يمنعنّ المؤمنَ من الهجرة خوفُه من الجوع في دار هجرته، إذ تكفّل الله برزقه."], "k": "«وكأيّن من دابة لا تحمل رزقها الله يرزقها وإياكم»… كم مرة قدّمت خوف الرزق على أمر الله؟"}, {"lbl": "الآيات ٦١ – ٦٤", "q": "وَلَئِن سَأَلۡتَهُم مَّنۡ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ وَسَخَّرَ ٱلشَّمۡسَ وَٱلۡقَمَرَ لَيَقُولُنَّ ٱللَّهُۖ فَأَنَّىٰ يُؤۡفَكُونَ ﴿٦١﴾ ٱللَّهُ يَبۡسُطُ ٱلرِّزۡقَ لِمَن يَشَآءُ مِنۡ عِبَادِهِۦ وَيَقۡدِرُ لَهُۥٓۚ إِنَّ ٱللَّهَ بِكُلِّ شَيۡءٍ عَلِيمٞ ﴿٦٢﴾ وَلَئِن سَأَلۡتَهُم مَّن نَّزَّلَ مِنَ ٱلسَّمَآءِ مَآءٗ فَأَحۡيَا بِهِ ٱلۡأَرۡضَ مِنۢ بَعۡدِ مَوۡتِهَا لَيَقُولُنَّ ٱللَّهُۚ قُلِ ٱلۡحَمۡدُ لِلَّهِۚ بَلۡ أَكۡثَرُهُمۡ لَا يَعۡقِلُونَ ﴿٦٣﴾ وَمَا هَٰذِهِ ٱلۡحَيَوٰةُ ٱلدُّنۡيَآ إِلَّا لَهۡوٞ وَلَعِبٞۚ وَإِنَّ ٱلدَّارَ ٱلۡأٓخِرَةَ لَهِيَ ٱلۡحَيَوَانُۚ لَوۡ كَانُواْ يَعۡلَمُونَ ﴿٦٤﴾", "w": [["ولئن سألتهم", "المشركين."], ["وسخّر الشمس والقمر", "ذلّلهما يسيران الدهر كله لا يملّان ولا يفتران."], ["فأنّى يؤفكون", "كيف يُصرفون عن الحق بعد ظهور أدلته؟"], ["الله يبسط الرزق لمن يشاء", "يوسّع على من يشاء امتحاناً: هل يشكر أم يكفر؟"], ["ويقدر له", "يضيّق عليه ابتلاءً: هل يصبر أم يسخط؟"], ["قل الحمد لله", "على ثبوت الحجة عليكم."], ["بل أكثرهم لا يعقلون", "إنهم متناقضون في فهمهم وجوابهم."], ["إلا لهو ولعب", "بالنظر إلى العمل لها والعيش فيها، يخرج منها الإنسان بلا طائل."], ["لهي الحيوان", "الحياة الكاملة الخالدة، ولذا العمل لها أفضل."]], "m": "ما زال السياق في تقرير التوحيد: ولئن سألت هؤلاء المشركين الذين يضطهدون المؤمنين: من خلق السماوات والأرض وسخّر الشمس والقمر؟ ليقولنّ: الله، فكيف يُصرفون عن الحق بعد ظهور أدلته؟ الله يبسط الرزق لمن يشاء من عباده امتحاناً، ويضيّقه على من يشاء ابتلاءً، فلا يدل غنى المشركين ولا فقر المؤمنين على رضا ولا سخط، إن الله بكل شيء عليم، يعلم من يصلحه الغنى ومن يصلحه الفقر. ولئن سألتهم: من نزّل من السماء ماءً فأحيا به الأرض بعد موتها؟ ليقولنّ: الله، قل: الحمد لله على اعترافكم، فلمَ تعبدون غيره؟ بل أكثرهم لا يعقلون، يعترفون بربٍّ خالق رازق ثم يعكفون على الأصنام. وما هذه الحياة الدنيا التي أعمت الناس عن الآخرة إلا لهو ولعب، يتشاغل بها الكافر ويخرج منها صفر اليدين كالأطفال يلعبون النهار كله ثم يعودون بلا شيء، وإن الدار الآخرة لهي الحياة الكاملة الخالدة، فلها يعمل العاملون، لو كانوا يعلمون، فدواؤهم العلم.", "h": ["التعجّب من تناقض المشركين الذين يؤمنون بربوبية الله ويجحدون ألوهيته.", "بيان حقيقة أن الغنى والفقر لا يدلّان على رضا الرب ولا على سخطه، وإنما يدلّان على علم الله وحكمته وحسن تدبيره.", "بيان حقارة الدنيا وتفاهتها وعظمة الآخرة وعلوّ قيمتها، فلذا أحمق الناس من يعمى عن الآخرة ويبصر الدنيا."], "k": "«وإن الدار الآخرة لهي الحيوان»… كم من يومي ذهب في لعب أطفال كبار؟"}, {"lbl": "الآيات ٦٥ – ٦٩", "q": "فَإِذَا رَكِبُواْ فِي ٱلۡفُلۡكِ دَعَوُاْ ٱللَّهَ مُخۡلِصِينَ لَهُ ٱلدِّينَ فَلَمَّا نَجَّىٰهُمۡ إِلَى ٱلۡبَرِّ إِذَا هُمۡ يُشۡرِكُونَ ﴿٦٥﴾ لِيَكۡفُرُواْ بِمَآ ءَاتَيۡنَٰهُمۡ وَلِيَتَمَتَّعُواْۚ فَسَوۡفَ يَعۡلَمُونَ ﴿٦٦﴾ أَوَلَمۡ يَرَوۡاْ أَنَّا جَعَلۡنَا حَرَمًا ءَامِنٗا وَيُتَخَطَّفُ ٱلنَّاسُ مِنۡ حَوۡلِهِمۡۚ أَفَبِٱلۡبَٰطِلِ يُؤۡمِنُونَ وَبِنِعۡمَةِ ٱللَّهِ يَكۡفُرُونَ ﴿٦٧﴾ وَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوۡ كَذَّبَ بِٱلۡحَقِّ لَمَّا جَآءَهُۥٓۚ أَلَيۡسَ فِي جَهَنَّمَ مَثۡوٗى لِّلۡكَٰفِرِينَ ﴿٦٨﴾ وَٱلَّذِينَ جَٰهَدُواْ فِينَا لَنَهۡدِيَنَّهُمۡ سُبُلَنَاۚ وَإِنَّ ٱللَّهَ لَمَعَ ٱلۡمُحۡسِنِينَ ﴿٦٩﴾", "w": [["في الفلك", "في السفينة."], ["دعوا الله مخلصين له الدين", "دعوه وحده فلم يذكروا معه غيره."], ["إذا هم يشركون", "يفاجئونك بالشرك، وهو دعاء غير الله."], ["ليكفروا بما آتيناهم", "بنعمة الإنجاء من الغرق وغيرها."], ["ويُتخطّف الناس من حولهم", "يُسبون ويُقتلون في ديار جزيرتهم."], ["أفبالباطل يؤمنون", "بالأصنام، وهي الباطل."], ["والذين جاهدوا فينا", "بذلوا جهدهم في تصحيح عقائدهم وتزكية نفوسهم، ثم بقتال المحاربين للإسلام."], ["لنهدينّهم سبلنا", "لنوفّقنّهم إلى معرفة ما يوصل إلى محبّتنا ورضانا."]], "m": "ما زال السياق في التنديد بتناقض المشركين: فإذا ركبوا في سفينة واضطربت بهم وخافوا الغرق دعوا الله وحده مخلصين له الدعاء، فلما نجّاهم إلى البر إذا هم يشركون، ومردّ ذلك إلى الجهل والتقليد والعناد، فكأن عودتهم إلى الشرك ليكفروا بنعمة الإنجاء، وليتمتّعوا في دنياهم، فسوف يعلمون عاقبة ذلك. أوَلم يروا أنا جعلنا لهم حرماً آمناً لا يُعتدى عليهم فيه، والناس من حولهم في أطراف الجزيرة يُسبون ويُقتلون؟ أفبالشرك يصدّقون وبنعمة الله يكفرون؟ ومن أظلم ممن افترى على الله كذباً بتحريم ما أحلّ وتحليل ما حرّم وعبادة الأصنام، أو كذّب بالحق لما جاءه؟ أليس في جهنم مثوى للكافرين؟ والذين جاهدوا في سبيلنا طلباً لمرضاتنا، بإعلاء كلمتنا، وجاهدوا في ذات الله نفوسهم وأهواءهم والشيطان، لنهدينّهم سبل النجاة والفوز، وإن الله لمع المحسنين نياتهم وأعمالهم بعونه ونصره.", "h": ["بيان أن مشركي العرب لم يكونوا ملاحدة لا يؤمنون بالله، بل كانوا موحّدين في الربوبية مشركين في الألوهية.", "دعوة المشركين بتنبيههم بنعم الله عليهم لعلهم يشكرون.", "لا ظلم أعظم من ظلم من افترى على الله الكذب، وكذّب بالحق لما جاءه وعرفه فانصرف عنه مؤثراً دنياه.", "بشرى الله لمن جاهد المشركين وجاهد نفسه والهوى والشياطين بالهداية إلى سبل الفوز والنجاة في الدنيا والآخرة.", "فضل الإحسان، وهو إخلاص العبادة لله وأداؤها متقنة كما شرعها، وكون الله مع المحسنين بنصرهم وتأييدهم."], "k": "«والذين جاهدوا فينا لنهدينّهم سبلنا»… الهداية تأتي بعد المجاهدة؛ فما الذي أجاهد فيه نفسي اليوم؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (290, 30, 1, 16, 'سورة الروم ١ – ١٦', '«غُلبت الروم… وهم من بعد غلبهم سيغلبون»، و«يعلمون ظاهراً من الحياة الدنيا»، و«ويوم تقوم الساعة يومئذ يتفرّقون»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 290) = $j$[{"lbl": "الآيات ١ – ٧", "q": "الٓمٓ ﴿١﴾ غُلِبَتِ ٱلرُّومُ ﴿٢﴾ فِيٓ أَدۡنَى ٱلۡأَرۡضِ وَهُم مِّنۢ بَعۡدِ غَلَبِهِمۡ سَيَغۡلِبُونَ ﴿٣﴾ فِي بِضۡعِ سِنِينَۗ لِلَّهِ ٱلۡأَمۡرُ مِن قَبۡلُ وَمِنۢ بَعۡدُۚ وَيَوۡمَئِذٖ يَفۡرَحُ ٱلۡمُؤۡمِنُونَ ﴿٤﴾ بِنَصۡرِ ٱللَّهِۚ يَنصُرُ مَن يَشَآءُۖ وَهُوَ ٱلۡعَزِيزُ ٱلرَّحِيمُ ﴿٥﴾ وَعۡدَ ٱللَّهِۖ لَا يُخۡلِفُ ٱللَّهُ وَعۡدَهُۥ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَعۡلَمُونَ ﴿٦﴾ يَعۡلَمُونَ ظَٰهِرٗا مِّنَ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَهُمۡ عَنِ ٱلۡأٓخِرَةِ هُمۡ غَٰفِلُونَ ﴿٧﴾", "w": [["الم", "تُكتب ألم وتُقرأ: ألف لام ميم."], ["غُلبت الروم", "غلبت فارسُ الروم."], ["في أدنى الأرض", "أقرب أرض الروم إلى فارس، وهي أرض الجزيرة بين دجلة والفرات."], ["وهم من بعد غلبهم سيغلبون", "الروم من بعد غلب فارس لهم سيغلبونها."], ["في بضع سنين", "ما بين ثلاث سنوات إلى تسع."], ["لله الأمر من قبل ومن بعد", "الأمر في الغلبتين لله وحده."], ["ويومئذ يفرح المؤمنون", "بنصر أهل الكتاب على عبدة النار، وبنصرهم هم على المشركين في بدر."], ["وعد الله", "وعدهم الله وعداً وأنجزه."], ["يعلمون ظاهراً من الحياة الدنيا", "كطلب المعاش من تجارة وزراعة وصناعة، ولا يعلمون حقائق الإيمان."], ["وهم عن الآخرة هم غافلون", "عن الحياة الآخرة وما فيها، وما يؤدي إليها من عقائد وأعمال."]], "m": "الم، الله أعلم بمراده، وفيها فائدتان: إعجاز القرآن المؤلّف من مثلها، واضطرار المشركين إلى السماع لغرابتها. غلبت فارسُ الروم في أدنى أرضهم إلى فارس، بين دجلة والفرات، وهم من بعد غلب فارس لهم سيغلبون في بضع سنين، لله الأمر من قبل الغلب ومن بعده، ويوم تغلب الروم فارساً يفرح المؤمنون بنصر الله، لأن الروم أهل كتاب وفارس يعبدون النار، وكان ذلك وقت انتصار المؤمنين في بدر، وهذا من الغيب الذي أخبر به القرآن قبل وقوعه فوقع كما أخبر. ينصر من يشاء، وهو العزيز الرحيم، وعد الله لا يخلف الله وعده، ولكن أكثر الناس لا يعلمون كمال قدرته وعلمه، يعلمون ظاهراً من الحياة الدنيا من زراعة وصناعة وتجارة، وهم عن الآخرة وما يُسعد فيها غافلون.", "h": ["تقرير صحة الإسلام، وأنه الدين الحق بصدق ما يخبر به كتابه من الغيوب.", "بيان أن أهل الكتاب من يهود ونصارى أقرب إلى المسلمين من المشركين والملاحدة من بلاشفة شيوعيين لا يؤمنون بالله واليوم الآخر.", "بيان أن أكثر الناس لا يعلمون ما يسعدهم في الآخرة من العقائد الصحيحة والشرائع الحكيمة، ويعلمون ظاهراً من الحياة الدنيا كتدبير المعاش، وهم عن الآخرة غافلون بالمرة."], "k": "«يعلمون ظاهراً من الحياة الدنيا»… خبرتي في دنياي كبيرة؛ فكم خبرتي بما ينفعني في آخرتي؟"}, {"lbl": "الآيات ٨ – ١٠", "q": "أَوَلَمۡ يَتَفَكَّرُواْ فِيٓ أَنفُسِهِمۗ مَّا خَلَقَ ٱللَّهُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ وَمَا بَيۡنَهُمَآ إِلَّا بِٱلۡحَقِّ وَأَجَلٖ مُّسَمّٗىۗ وَإِنَّ كَثِيرٗا مِّنَ ٱلنَّاسِ بِلِقَآيِٕ رَبِّهِمۡ لَكَٰفِرُونَ ﴿٨﴾ أَوَلَمۡ يَسِيرُواْ فِي ٱلۡأَرۡضِ فَيَنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن قَبۡلِهِمۡۚ كَانُوٓاْ أَشَدَّ مِنۡهُمۡ قُوَّةٗ وَأَثَارُواْ ٱلۡأَرۡضَ وَعَمَرُوهَآ أَكۡثَرَ مِمَّا عَمَرُوهَا وَجَآءَتۡهُمۡ رُسُلُهُم بِٱلۡبَيِّنَٰتِۖ فَمَا كَانَ ٱللَّهُ لِيَظۡلِمَهُمۡ وَلَٰكِن كَانُوٓاْ أَنفُسَهُمۡ يَظۡلِمُونَ ﴿٩﴾ ثُمَّ كَانَ عَٰقِبَةَ ٱلَّذِينَ أَسَـٰٓـُٔواْ ٱلسُّوٓأَىٰٓ أَن كَذَّبُواْ بِـَٔايَٰتِ ٱللَّهِ وَكَانُواْ بِهَا يَسۡتَهۡزِءُونَ ﴿١٠﴾", "w": [["في أنفسهم", "كيف خُلقوا ولم يكونوا شيئاً، ثم كيف أصبحوا."], ["إلا بالحق", "لم يخلقهما عبثاً، بل ليُذكر ويُشكر."], ["وأجل مسمّى", "نهاية هذه الحياة، لتكون الحياة الثانية حياة الجزاء."], ["بلقاء ربهم لكافرون", "بالبعث والوقوف بين يدي الله."], ["وأثاروا الأرض", "قلبوها للحرث والغرس والإنشاء والتعمير."], ["وعمروها أكثر مما عمروها", "عمارة أكثر مما عمرها هؤلاء."], ["أساؤوا السُّوأى", "العاقبة السوأى، وهي خسرانهم وهلاكهم."], ["أن كذّبوا بآيات الله", "بسبب تكذيبهم بآياته واستهزائهم بها."]], "m": "أيُنكرون البعث ولم يتفكّروا في أنفسهم، كيف كانوا عدماً ثم وُجدوا أطفالاً ثم شبّاناً ثم كهولاً وشيوخاً ثم يموتون؟ أليس القادر على ذلك قادراً على بعثهم؟ ما خلق الله السماوات والأرض وما بينهما إلا بالحق، ليُذكر ويُشكر، وأجل مسمّى إذا تمّ أفناهما ثم بعث عباده ليجزيهم، وإن كثيراً من الناس بلقاء ربهم لكافرون مع ظهور الأدلة. أوَلم يسيروا في الأرض فينظروا كيف كان عاقبة الذين من قبلهم؟ كانوا أشد منهم قوة، وقلبوا الأرض بالزراعة والإنشاء وعمروها أكثر مما عمرها هؤلاء، وجاءتهم رسلهم بالبيّنات، فما كان الله ليظلمهم، ولكن كانوا أنفسهم يظلمون. ثم كان عاقبة الذين أساؤوا الأعمال العاقبة السوأى، من أجل أنهم كذّبوا بآيات الله وكانوا بها يستهزئون.", "h": ["تقرير عقيدة البعث والجزاء بذكر الأدلة العقلية المثبتة لها.", "كفر أكثر الناس بالبعث مع كثرة الأدلة وقوّتها.", "مشروعية السير في الأرض للاعتبار، مع اشتراط عدم حصول إثم في ذلك بترك واجب أو فعل محرّم.", "بيان جزاء الله العادل في أن عاقبة الإساءة السوأى.", "كفر الاستهزاء بالشرع وأحكامه والقرآن وآياته."], "k": "«أوَلم يتفكّروا في أنفسهم»… رحلتي من العدم إلى الآن آية؛ فمتى آخر مرة تفكّرت فيها؟"}, {"lbl": "الآيات ١١ – ١٦", "q": "ٱللَّهُ يَبۡدَؤُاْ ٱلۡخَلۡقَ ثُمَّ يُعِيدُهُۥ ثُمَّ إِلَيۡهِ تُرۡجَعُونَ ﴿١١﴾ وَيَوۡمَ تَقُومُ ٱلسَّاعَةُ يُبۡلِسُ ٱلۡمُجۡرِمُونَ ﴿١٢﴾ وَلَمۡ يَكُن لَّهُم مِّن شُرَكَآئِهِمۡ شُفَعَـٰٓؤُاْ وَكَانُواْ بِشُرَكَآئِهِمۡ كَٰفِرِينَ ﴿١٣﴾ وَيَوۡمَ تَقُومُ ٱلسَّاعَةُ يَوۡمَئِذٖ يَتَفَرَّقُونَ ﴿١٤﴾ فَأَمَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ فَهُمۡ فِي رَوۡضَةٖ يُحۡبَرُونَ ﴿١٥﴾ وَأَمَّا ٱلَّذِينَ كَفَرُواْ وَكَذَّبُواْ بِـَٔايَٰتِنَا وَلِقَآيِٕ ٱلۡأٓخِرَةِ فَأُوْلَـٰٓئِكَ فِي ٱلۡعَذَابِ مُحۡضَرُونَ ﴿١٦﴾", "w": [["ثم إليه تُرجعون", "بعد إعادة الخلق وبعث الناس."], ["يُبلس المجرمون", "ييأسون من النجاة وتنقطع حجتهم."], ["وكانوا بشركائهم كافرين", "يتبرّؤون منهم ولا يعترفون بهم."], ["يتفرّقون", "ينقسمون إلى سعداء أصحاب الجنة وأشقياء أصحاب النار."], ["في روضة يُحبرون", "في روضة من رياض الجنة يُسرّون ويفرحون."], ["في العذاب محضرون", "مُدخلون فيه لا يخرجون منه."]], "m": "ما زال السياق في تقرير البعث: الله يبدأ الخلق ثم يميته ثم يعيده، ثم إليه لا إلى غيره ترجع الخليقة كلها راضية أو ساخطة. ويوم تقوم الساعة ويُبعث الناس ييأس المجرمون من الرحمة وتنقطع حجتهم، ولم يكن لهم من شركائهم الذين عبدوهم شفعاء، وكفروا بهم وأنكروا عبادتهم خوفاً من زيادة العذاب. ويوم تقوم الساعة يومئذ يتفرّق الناس فريقين: فأما الذين آمنوا بالله رباً وإلهاً وبمحمد رسولاً وبالإسلام ديناً وبالبعث حقاً، وعملوا الصالحات المشروعة، فهم في روضة من رياض الجنة يُسرّون ويفرحون بفضل الله، وأما الذين كفروا وكذّبوا بآياتنا ولقاء الآخرة فأولئك في العذاب محضرون دائماً لا يغيبون عنه.", "h": ["تقرير عقيدة البعث والجزاء بذكر الأدلة وعرض مشاهد القيامة.", "تقرير أن لا شفاعة لمشرك ولا كافر يوم القيامة، وبطلان ما يعتقده المشركون من وجود من يشفع لهم.", "تقرير مبدأ السعادة والشقاء يوم القيامة: أهل الإيمان والتقوى في روضة يُحبرون، وأهل الشرك والمعاصي في العذاب محضرون."], "k": "«يومئذ يتفرّقون»… سيفترق الناس فريقين لا ثالث لهما؛ فإلى أيهما يسوقني يومي هذا؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 290;
insert into public.tdb_cards(topic, i, body) select 290, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ٧", "q": "الٓمٓ ﴿١﴾ غُلِبَتِ ٱلرُّومُ ﴿٢﴾ فِيٓ أَدۡنَى ٱلۡأَرۡضِ وَهُم مِّنۢ بَعۡدِ غَلَبِهِمۡ سَيَغۡلِبُونَ ﴿٣﴾ فِي بِضۡعِ سِنِينَۗ لِلَّهِ ٱلۡأَمۡرُ مِن قَبۡلُ وَمِنۢ بَعۡدُۚ وَيَوۡمَئِذٖ يَفۡرَحُ ٱلۡمُؤۡمِنُونَ ﴿٤﴾ بِنَصۡرِ ٱللَّهِۚ يَنصُرُ مَن يَشَآءُۖ وَهُوَ ٱلۡعَزِيزُ ٱلرَّحِيمُ ﴿٥﴾ وَعۡدَ ٱللَّهِۖ لَا يُخۡلِفُ ٱللَّهُ وَعۡدَهُۥ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَعۡلَمُونَ ﴿٦﴾ يَعۡلَمُونَ ظَٰهِرٗا مِّنَ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَهُمۡ عَنِ ٱلۡأٓخِرَةِ هُمۡ غَٰفِلُونَ ﴿٧﴾", "w": [["الم", "تُكتب ألم وتُقرأ: ألف لام ميم."], ["غُلبت الروم", "غلبت فارسُ الروم."], ["في أدنى الأرض", "أقرب أرض الروم إلى فارس، وهي أرض الجزيرة بين دجلة والفرات."], ["وهم من بعد غلبهم سيغلبون", "الروم من بعد غلب فارس لهم سيغلبونها."], ["في بضع سنين", "ما بين ثلاث سنوات إلى تسع."], ["لله الأمر من قبل ومن بعد", "الأمر في الغلبتين لله وحده."], ["ويومئذ يفرح المؤمنون", "بنصر أهل الكتاب على عبدة النار، وبنصرهم هم على المشركين في بدر."], ["وعد الله", "وعدهم الله وعداً وأنجزه."], ["يعلمون ظاهراً من الحياة الدنيا", "كطلب المعاش من تجارة وزراعة وصناعة، ولا يعلمون حقائق الإيمان."], ["وهم عن الآخرة هم غافلون", "عن الحياة الآخرة وما فيها، وما يؤدي إليها من عقائد وأعمال."]], "m": "الم، الله أعلم بمراده، وفيها فائدتان: إعجاز القرآن المؤلّف من مثلها، واضطرار المشركين إلى السماع لغرابتها. غلبت فارسُ الروم في أدنى أرضهم إلى فارس، بين دجلة والفرات، وهم من بعد غلب فارس لهم سيغلبون في بضع سنين، لله الأمر من قبل الغلب ومن بعده، ويوم تغلب الروم فارساً يفرح المؤمنون بنصر الله، لأن الروم أهل كتاب وفارس يعبدون النار، وكان ذلك وقت انتصار المؤمنين في بدر، وهذا من الغيب الذي أخبر به القرآن قبل وقوعه فوقع كما أخبر. ينصر من يشاء، وهو العزيز الرحيم، وعد الله لا يخلف الله وعده، ولكن أكثر الناس لا يعلمون كمال قدرته وعلمه، يعلمون ظاهراً من الحياة الدنيا من زراعة وصناعة وتجارة، وهم عن الآخرة وما يُسعد فيها غافلون.", "h": ["تقرير صحة الإسلام، وأنه الدين الحق بصدق ما يخبر به كتابه من الغيوب.", "بيان أن أهل الكتاب من يهود ونصارى أقرب إلى المسلمين من المشركين والملاحدة من بلاشفة شيوعيين لا يؤمنون بالله واليوم الآخر.", "بيان أن أكثر الناس لا يعلمون ما يسعدهم في الآخرة من العقائد الصحيحة والشرائع الحكيمة، ويعلمون ظاهراً من الحياة الدنيا كتدبير المعاش، وهم عن الآخرة غافلون بالمرة."], "k": "«يعلمون ظاهراً من الحياة الدنيا»… خبرتي في دنياي كبيرة؛ فكم خبرتي بما ينفعني في آخرتي؟"}, {"lbl": "الآيات ٨ – ١٠", "q": "أَوَلَمۡ يَتَفَكَّرُواْ فِيٓ أَنفُسِهِمۗ مَّا خَلَقَ ٱللَّهُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ وَمَا بَيۡنَهُمَآ إِلَّا بِٱلۡحَقِّ وَأَجَلٖ مُّسَمّٗىۗ وَإِنَّ كَثِيرٗا مِّنَ ٱلنَّاسِ بِلِقَآيِٕ رَبِّهِمۡ لَكَٰفِرُونَ ﴿٨﴾ أَوَلَمۡ يَسِيرُواْ فِي ٱلۡأَرۡضِ فَيَنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن قَبۡلِهِمۡۚ كَانُوٓاْ أَشَدَّ مِنۡهُمۡ قُوَّةٗ وَأَثَارُواْ ٱلۡأَرۡضَ وَعَمَرُوهَآ أَكۡثَرَ مِمَّا عَمَرُوهَا وَجَآءَتۡهُمۡ رُسُلُهُم بِٱلۡبَيِّنَٰتِۖ فَمَا كَانَ ٱللَّهُ لِيَظۡلِمَهُمۡ وَلَٰكِن كَانُوٓاْ أَنفُسَهُمۡ يَظۡلِمُونَ ﴿٩﴾ ثُمَّ كَانَ عَٰقِبَةَ ٱلَّذِينَ أَسَـٰٓـُٔواْ ٱلسُّوٓأَىٰٓ أَن كَذَّبُواْ بِـَٔايَٰتِ ٱللَّهِ وَكَانُواْ بِهَا يَسۡتَهۡزِءُونَ ﴿١٠﴾", "w": [["في أنفسهم", "كيف خُلقوا ولم يكونوا شيئاً، ثم كيف أصبحوا."], ["إلا بالحق", "لم يخلقهما عبثاً، بل ليُذكر ويُشكر."], ["وأجل مسمّى", "نهاية هذه الحياة، لتكون الحياة الثانية حياة الجزاء."], ["بلقاء ربهم لكافرون", "بالبعث والوقوف بين يدي الله."], ["وأثاروا الأرض", "قلبوها للحرث والغرس والإنشاء والتعمير."], ["وعمروها أكثر مما عمروها", "عمارة أكثر مما عمرها هؤلاء."], ["أساؤوا السُّوأى", "العاقبة السوأى، وهي خسرانهم وهلاكهم."], ["أن كذّبوا بآيات الله", "بسبب تكذيبهم بآياته واستهزائهم بها."]], "m": "أيُنكرون البعث ولم يتفكّروا في أنفسهم، كيف كانوا عدماً ثم وُجدوا أطفالاً ثم شبّاناً ثم كهولاً وشيوخاً ثم يموتون؟ أليس القادر على ذلك قادراً على بعثهم؟ ما خلق الله السماوات والأرض وما بينهما إلا بالحق، ليُذكر ويُشكر، وأجل مسمّى إذا تمّ أفناهما ثم بعث عباده ليجزيهم، وإن كثيراً من الناس بلقاء ربهم لكافرون مع ظهور الأدلة. أوَلم يسيروا في الأرض فينظروا كيف كان عاقبة الذين من قبلهم؟ كانوا أشد منهم قوة، وقلبوا الأرض بالزراعة والإنشاء وعمروها أكثر مما عمرها هؤلاء، وجاءتهم رسلهم بالبيّنات، فما كان الله ليظلمهم، ولكن كانوا أنفسهم يظلمون. ثم كان عاقبة الذين أساؤوا الأعمال العاقبة السوأى، من أجل أنهم كذّبوا بآيات الله وكانوا بها يستهزئون.", "h": ["تقرير عقيدة البعث والجزاء بذكر الأدلة العقلية المثبتة لها.", "كفر أكثر الناس بالبعث مع كثرة الأدلة وقوّتها.", "مشروعية السير في الأرض للاعتبار، مع اشتراط عدم حصول إثم في ذلك بترك واجب أو فعل محرّم.", "بيان جزاء الله العادل في أن عاقبة الإساءة السوأى.", "كفر الاستهزاء بالشرع وأحكامه والقرآن وآياته."], "k": "«أوَلم يتفكّروا في أنفسهم»… رحلتي من العدم إلى الآن آية؛ فمتى آخر مرة تفكّرت فيها؟"}, {"lbl": "الآيات ١١ – ١٦", "q": "ٱللَّهُ يَبۡدَؤُاْ ٱلۡخَلۡقَ ثُمَّ يُعِيدُهُۥ ثُمَّ إِلَيۡهِ تُرۡجَعُونَ ﴿١١﴾ وَيَوۡمَ تَقُومُ ٱلسَّاعَةُ يُبۡلِسُ ٱلۡمُجۡرِمُونَ ﴿١٢﴾ وَلَمۡ يَكُن لَّهُم مِّن شُرَكَآئِهِمۡ شُفَعَـٰٓؤُاْ وَكَانُواْ بِشُرَكَآئِهِمۡ كَٰفِرِينَ ﴿١٣﴾ وَيَوۡمَ تَقُومُ ٱلسَّاعَةُ يَوۡمَئِذٖ يَتَفَرَّقُونَ ﴿١٤﴾ فَأَمَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ فَهُمۡ فِي رَوۡضَةٖ يُحۡبَرُونَ ﴿١٥﴾ وَأَمَّا ٱلَّذِينَ كَفَرُواْ وَكَذَّبُواْ بِـَٔايَٰتِنَا وَلِقَآيِٕ ٱلۡأٓخِرَةِ فَأُوْلَـٰٓئِكَ فِي ٱلۡعَذَابِ مُحۡضَرُونَ ﴿١٦﴾", "w": [["ثم إليه تُرجعون", "بعد إعادة الخلق وبعث الناس."], ["يُبلس المجرمون", "ييأسون من النجاة وتنقطع حجتهم."], ["وكانوا بشركائهم كافرين", "يتبرّؤون منهم ولا يعترفون بهم."], ["يتفرّقون", "ينقسمون إلى سعداء أصحاب الجنة وأشقياء أصحاب النار."], ["في روضة يُحبرون", "في روضة من رياض الجنة يُسرّون ويفرحون."], ["في العذاب محضرون", "مُدخلون فيه لا يخرجون منه."]], "m": "ما زال السياق في تقرير البعث: الله يبدأ الخلق ثم يميته ثم يعيده، ثم إليه لا إلى غيره ترجع الخليقة كلها راضية أو ساخطة. ويوم تقوم الساعة ويُبعث الناس ييأس المجرمون من الرحمة وتنقطع حجتهم، ولم يكن لهم من شركائهم الذين عبدوهم شفعاء، وكفروا بهم وأنكروا عبادتهم خوفاً من زيادة العذاب. ويوم تقوم الساعة يومئذ يتفرّق الناس فريقين: فأما الذين آمنوا بالله رباً وإلهاً وبمحمد رسولاً وبالإسلام ديناً وبالبعث حقاً، وعملوا الصالحات المشروعة، فهم في روضة من رياض الجنة يُسرّون ويفرحون بفضل الله، وأما الذين كفروا وكذّبوا بآياتنا ولقاء الآخرة فأولئك في العذاب محضرون دائماً لا يغيبون عنه.", "h": ["تقرير عقيدة البعث والجزاء بذكر الأدلة وعرض مشاهد القيامة.", "تقرير أن لا شفاعة لمشرك ولا كافر يوم القيامة، وبطلان ما يعتقده المشركون من وجود من يشفع لهم.", "تقرير مبدأ السعادة والشقاء يوم القيامة: أهل الإيمان والتقوى في روضة يُحبرون، وأهل الشرك والمعاصي في العذاب محضرون."], "k": "«يومئذ يتفرّقون»… سيفترق الناس فريقين لا ثالث لهما؛ فإلى أيهما يسوقني يومي هذا؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (291, 30, 17, 29, 'سورة الروم ١٧ – ٢٩', '«فسبحان الله حين تمسون وحين تصبحون»، و«ومن آياته أن خلق لكم من أنفسكم أزواجاً لتسكنوا إليها»، و«ضرب لكم مثلاً من أنفسكم»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 291) = $j$[{"lbl": "الآيات ١٧ – ٢١", "q": "فَسُبۡحَٰنَ ٱللَّهِ حِينَ تُمۡسُونَ وَحِينَ تُصۡبِحُونَ ﴿١٧﴾ وَلَهُ ٱلۡحَمۡدُ فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَعَشِيّٗا وَحِينَ تُظۡهِرُونَ ﴿١٨﴾ يُخۡرِجُ ٱلۡحَيَّ مِنَ ٱلۡمَيِّتِ وَيُخۡرِجُ ٱلۡمَيِّتَ مِنَ ٱلۡحَيِّ وَيُحۡيِ ٱلۡأَرۡضَ بَعۡدَ مَوۡتِهَاۚ وَكَذَٰلِكَ تُخۡرَجُونَ ﴿١٩﴾ وَمِنۡ ءَايَٰتِهِۦٓ أَنۡ خَلَقَكُم مِّن تُرَابٖ ثُمَّ إِذَآ أَنتُم بَشَرٞ تَنتَشِرُونَ ﴿٢٠﴾ وَمِنۡ ءَايَٰتِهِۦٓ أَنۡ خَلَقَ لَكُم مِّنۡ أَنفُسِكُمۡ أَزۡوَٰجٗا لِّتَسۡكُنُوٓاْ إِلَيۡهَا وَجَعَلَ بَيۡنَكُم مَّوَدَّةٗ وَرَحۡمَةًۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يَتَفَكَّرُونَ ﴿٢١﴾", "w": [["فسبحان الله", "سبّحوا الله، أي صلّوا."], ["حين تمسون", "حين تدخلون في المساء، وفيه صلاة المغرب والعشاء."], ["وحين تصبحون", "حين تدخلون في الصباح، وفيه صلاة الصبح."], ["وعشيّاً وحين تُظهرون", "العصر والظهر."], ["يُخرج الحيّ من الميت", "كالإنسان من النطفة، والطير من البيضة، والمؤمن من الكافر."], ["ويُخرج الميت من الحي", "كالنطفة من الإنسان، والبيضة من الطائر."], ["أن خلقكم من تراب", "بخلق آدم الأب الأول من تراب."], ["من أنفسكم أزواجاً", "من جنسكم الآدمي زوجات."], ["لتسكنوا إليها", "بعامل التجانس، إذ كل جنس يطمئن إلى جنسه."], ["مودّة ورحمة", "محبة ورحمة بين الزوجين."]], "m": "لما ذكر بدء الخلق ونهايته باستقرار أهل الجنة في الجنة وأهل النار في النار، وهذا يستوجب تنزيهه وحمده، أمر بالصلوات الخمس المشتملة على ذلك: فسبّحوا الله حين تمسون، المغرب والعشاء، وحين تصبحون، الصبح، وله الحمد في السماوات والأرض، وعشيّاً، العصر، وحين تُظهرون، الظهر. يُخرج الحيّ من الميت كالإنسان من النطفة والمؤمن من الكافر، ويُخرج الميت من الحي، ويحيي الأرض بالمطر بعد موتها، وكذلك تُخرجون من قبوركم، إذ القادر على الأول قادر على الثاني. ومن آياته أن خلقكم من تراب بخلق أبيكم آدم، ثم إذا أنتم بشر تنتشرون في أقطار الأرض. ومن آياته أن خلق لكم من جنسكم زوجات لتسكنوا إليها، وجعل بين الزوجين محبة ورحمة، إلا إذا ظلم أحدهما الآخر فقد ترتفع حتى يرتفع الظلم، إن في ذلك لآيات لقوم يتفكّرون.", "h": ["وجوب تنزيه الله عن كل ما لا يليق بجلاله وكماله.", "وجوب حمد الله على آلائه وإنعامه.", "وجوب إقام الصلاة.", "بيان أوقات الصلوات الخمس.", "بيان مظاهر قدرة الله تعالى وعلمه ورحمته المقتضية لتوحيده والمقرّرة لعقيدة البعث."], "k": "«وجعل بينكم مودّة ورحمة»… هل أحفظ في بيتي المودة والرحمة، أم يذهب بهما ظلم صغير متكرر؟"}, {"lbl": "الآيات ٢٢ – ٢٥", "q": "وَمِنۡ ءَايَٰتِهِۦ خَلۡقُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَٱخۡتِلَٰفُ أَلۡسِنَتِكُمۡ وَأَلۡوَٰنِكُمۡۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّلۡعَٰلِمِينَ ﴿٢٢﴾ وَمِنۡ ءَايَٰتِهِۦ مَنَامُكُم بِٱلَّيۡلِ وَٱلنَّهَارِ وَٱبۡتِغَآؤُكُم مِّن فَضۡلِهِۦٓۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يَسۡمَعُونَ ﴿٢٣﴾ وَمِنۡ ءَايَٰتِهِۦ يُرِيكُمُ ٱلۡبَرۡقَ خَوۡفٗا وَطَمَعٗا وَيُنَزِّلُ مِنَ ٱلسَّمَآءِ مَآءٗ فَيُحۡيِۦ بِهِ ٱلۡأَرۡضَ بَعۡدَ مَوۡتِهَآۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يَعۡقِلُونَ ﴿٢٤﴾ وَمِنۡ ءَايَٰتِهِۦٓ أَن تَقُومَ ٱلسَّمَآءُ وَٱلۡأَرۡضُ بِأَمۡرِهِۦۚ ثُمَّ إِذَا دَعَاكُمۡ دَعۡوَةٗ مِّنَ ٱلۡأَرۡضِ إِذَآ أَنتُمۡ تَخۡرُجُونَ ﴿٢٥﴾", "w": [["ومن آياته", "حججه وبراهينه الدالة على قدرته على البعث."], ["واختلاف ألسنتكم", "لغاتكم من عربية وعجمية، ولهجاتكم التي يتميز بها كل ناطق."], ["وألوانكم", "من أبيض وأصفر وأحمر وأسود، والكل أبناء رجل واحد."], ["للعالمين", "للعقلاء، وعلى قراءة الكسر: لأولي العلم."], ["وابتغاؤكم من فضله", "طلبكم الرزق بإحضار أسبابه من زراعة وتجارة."], ["لقوم يسمعون", "سماع تدبّر وفهم، لا مجرد سماع الأصوات."], ["يريكم البرق خوفاً وطمعاً", "خوفاً من الصواعق والأمطار الشديدة، وطمعاً في المطر."], ["أن تقوم السماء والأرض بأمره", "قيامهما على ما هما عليه بقدرته وتدبيره."], ["دعوة من الأرض", "دعوة واحدة، وهي نفخة إسرافيل."]], "m": "ما زال السياق في تقرير التوحيد والبعث بالأدلة: ومن آياته خلق السماوات والأرض، واختلاف لغاتكم ولهجاتكم حتى يُعرف كل ناطق بصوته، واختلاف ألوانكم وملامحكم حتى لا يوجد اثنان لا يتميّز أحدهما عن الآخر، إن في ذلك لآيات للعالمين. ومن آياته منامكم بالليل كالموت، وانتشاركم بالنهار في طلب الرزق كالبعث، عملية تتكرّر كل يوم، إن في ذلك لآيات لقوم يسمعون سماع تدبّر. ومن آياته يريكم البرق خوفاً من الصواعق وطمعاً في المطر، وينزّل من السماء ماءً فيحيي به الأرض بعد موتها، إن في ذلك لآيات لقوم يعقلون. ومن آياته أن تقوم السماء والأرض بأمره منذ خلقهما، فلا السماء تسقط ولا الأرض تغور، ثم إذا دعاكم دعوة واحدة بنفخ إسرافيل في الصور إذا أنتم تخرجون من قبوركم أحياء للحساب.", "h": ["بيان مظاهر قدرة الله تعالى وعلمه وحكمته ورحمته الموجبة لعبادته وحده.", "مشروعية طلب الرزق بالمشي في الأرض واستعمال الوسائل المشروعة لذلك.", "تقرير أن الذين ينتفعون بأسماعهم وعقولهم هم أهل حياة الإيمان، إذ الإيمان إذا دخل جسماً حيي وأصبح صاحبه يسمع ويبصر ويعقل.", "تقرير عقيدة البعث والجزاء التي عليها مدار الإصلاح البشري بعد عقيدة التوحيد."], "k": "«واختلاف ألسنتكم وألوانكم»… الاختلاف بين الناس آية؛ فهل أنظر إليه بعين التدبّر أم بعين التعالي؟"}, {"lbl": "الآيات ٢٦ – ٢٩", "q": "وَلَهُۥ مَن فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ كُلّٞ لَّهُۥ قَٰنِتُونَ ﴿٢٦﴾ وَهُوَ ٱلَّذِي يَبۡدَؤُاْ ٱلۡخَلۡقَ ثُمَّ يُعِيدُهُۥ وَهُوَ أَهۡوَنُ عَلَيۡهِۚ وَلَهُ ٱلۡمَثَلُ ٱلۡأَعۡلَىٰ فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ وَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ ﴿٢٧﴾ ضَرَبَ لَكُم مَّثَلٗا مِّنۡ أَنفُسِكُمۡۖ هَل لَّكُم مِّن مَّا مَلَكَتۡ أَيۡمَٰنُكُم مِّن شُرَكَآءَ فِي مَا رَزَقۡنَٰكُمۡ فَأَنتُمۡ فِيهِ سَوَآءٞ تَخَافُونَهُمۡ كَخِيفَتِكُمۡ أَنفُسَكُمۡۚ كَذَٰلِكَ نُفَصِّلُ ٱلۡأٓيَٰتِ لِقَوۡمٖ يَعۡقِلُونَ ﴿٢٨﴾ بَلِ ٱتَّبَعَ ٱلَّذِينَ ظَلَمُوٓاْ أَهۡوَآءَهُم بِغَيۡرِ عِلۡمٖۖ فَمَن يَهۡدِي مَنۡ أَضَلَّ ٱللَّهُۖ وَمَا لَهُم مِّن نَّـٰصِرِينَ ﴿٢٩﴾", "w": [["وله من في السماوات والأرض", "خلقاً وملكاً وتصرّفاً وعبيداً."], ["كلٌّ له قانتون", "منقادون له تجري عليهم أحكامه كما أرادها."], ["وهو أهون عليه", "أيسر وأسهل، نظراً إلى أن الإعادة أسهل من البداية."], ["وله المثل الأعلى", "الوصف الأعلى في كل كمال."], ["ضرب لكم مثلاً", "جعل لكم مثلاً."], ["من أنفسكم", "منتزعاً مما تعرفونه من أنفسكم وأموالكم."], ["كخيفتكم أنفسكم", "كتخوّف بعضكم من بعض أيها الأحرار."], ["نفصّل الآيات", "نبيّنها بتنويع الأسلوب وإيراد الحجج."], ["بل اتّبع الذين ظلموا أهواءهم", "ليس الأمر قصوراً في البيان، وإنما العلّة اتّباعهم أهواءهم."], ["فمن يهدي من أضلّ الله", "لا أحد."]], "m": "وله من في السماوات والأرض من ملائكة وجن وإنس، خلقاً وملكاً، كلٌّ له منقادون لما أراده منهم من حياة وموت ونشور. وهو الذي يبدأ الخلق ثم يعيده يوم القيامة، وهو أهون عليه، خاطبهم بما يتعارفون عليه من أن الإعادة أسهل من البداءة ليقتنعوا، وإلا فلا شيء صعب على الله، وله الوصف الأعلى في السماوات والأرض، وهو الألوهية والوحدانية، وهو العزيز الحكيم. ضرب لكم مثلاً من أنفسكم: هل لكم من عبيدكم شركاء فيما رزقناكم فأنتم فيه سواء، تخافونهم كما يخاف بعضكم بعضاً؟ لا ترضون بذلك أبداً، فكذلك الله لا يرضى أن يكون من عبيده شريك له في عبادته. كذلك نفصّل الآيات لقوم يعقلون. بل اتّبع الذين ظلموا أهواءهم بغير علم، فمن يهدي من أضلّ الله حسب سنّته؟ وما لهم من ناصرين.", "h": ["تقرير عقيدة البعث والتوحيد بذكر الأدلة وضرب الأمثال وتفصيل الآيات.", "تفرّد الرب تعالى بالمثل الأعلى في كل جلال وكمال.", "استحسان ضرب الأمثال لتقريب المعاني إلى الأفهام.", "عظم فائدة هذا المثل، حتى قال بعضهم: تعلّم هذا المثل أفضل من حفظ كذا مسألة فقهية.", "علّة ضلال الناس اتّباعهم أهواءهم بغير علم، وانصرافهم عن الهدى بالاسترسال في اتّباع الهوى."], "k": "«تخافونهم كخيفتكم أنفسكم»… ما لا أرضاه لنفسي من شريك، كيف أرضاه لربي في قلبي؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 291;
insert into public.tdb_cards(topic, i, body) select 291, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١٧ – ٢١", "q": "فَسُبۡحَٰنَ ٱللَّهِ حِينَ تُمۡسُونَ وَحِينَ تُصۡبِحُونَ ﴿١٧﴾ وَلَهُ ٱلۡحَمۡدُ فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَعَشِيّٗا وَحِينَ تُظۡهِرُونَ ﴿١٨﴾ يُخۡرِجُ ٱلۡحَيَّ مِنَ ٱلۡمَيِّتِ وَيُخۡرِجُ ٱلۡمَيِّتَ مِنَ ٱلۡحَيِّ وَيُحۡيِ ٱلۡأَرۡضَ بَعۡدَ مَوۡتِهَاۚ وَكَذَٰلِكَ تُخۡرَجُونَ ﴿١٩﴾ وَمِنۡ ءَايَٰتِهِۦٓ أَنۡ خَلَقَكُم مِّن تُرَابٖ ثُمَّ إِذَآ أَنتُم بَشَرٞ تَنتَشِرُونَ ﴿٢٠﴾ وَمِنۡ ءَايَٰتِهِۦٓ أَنۡ خَلَقَ لَكُم مِّنۡ أَنفُسِكُمۡ أَزۡوَٰجٗا لِّتَسۡكُنُوٓاْ إِلَيۡهَا وَجَعَلَ بَيۡنَكُم مَّوَدَّةٗ وَرَحۡمَةًۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يَتَفَكَّرُونَ ﴿٢١﴾", "w": [["فسبحان الله", "سبّحوا الله، أي صلّوا."], ["حين تمسون", "حين تدخلون في المساء، وفيه صلاة المغرب والعشاء."], ["وحين تصبحون", "حين تدخلون في الصباح، وفيه صلاة الصبح."], ["وعشيّاً وحين تُظهرون", "العصر والظهر."], ["يُخرج الحيّ من الميت", "كالإنسان من النطفة، والطير من البيضة، والمؤمن من الكافر."], ["ويُخرج الميت من الحي", "كالنطفة من الإنسان، والبيضة من الطائر."], ["أن خلقكم من تراب", "بخلق آدم الأب الأول من تراب."], ["من أنفسكم أزواجاً", "من جنسكم الآدمي زوجات."], ["لتسكنوا إليها", "بعامل التجانس، إذ كل جنس يطمئن إلى جنسه."], ["مودّة ورحمة", "محبة ورحمة بين الزوجين."]], "m": "لما ذكر بدء الخلق ونهايته باستقرار أهل الجنة في الجنة وأهل النار في النار، وهذا يستوجب تنزيهه وحمده، أمر بالصلوات الخمس المشتملة على ذلك: فسبّحوا الله حين تمسون، المغرب والعشاء، وحين تصبحون، الصبح، وله الحمد في السماوات والأرض، وعشيّاً، العصر، وحين تُظهرون، الظهر. يُخرج الحيّ من الميت كالإنسان من النطفة والمؤمن من الكافر، ويُخرج الميت من الحي، ويحيي الأرض بالمطر بعد موتها، وكذلك تُخرجون من قبوركم، إذ القادر على الأول قادر على الثاني. ومن آياته أن خلقكم من تراب بخلق أبيكم آدم، ثم إذا أنتم بشر تنتشرون في أقطار الأرض. ومن آياته أن خلق لكم من جنسكم زوجات لتسكنوا إليها، وجعل بين الزوجين محبة ورحمة، إلا إذا ظلم أحدهما الآخر فقد ترتفع حتى يرتفع الظلم، إن في ذلك لآيات لقوم يتفكّرون.", "h": ["وجوب تنزيه الله عن كل ما لا يليق بجلاله وكماله.", "وجوب حمد الله على آلائه وإنعامه.", "وجوب إقام الصلاة.", "بيان أوقات الصلوات الخمس.", "بيان مظاهر قدرة الله تعالى وعلمه ورحمته المقتضية لتوحيده والمقرّرة لعقيدة البعث."], "k": "«وجعل بينكم مودّة ورحمة»… هل أحفظ في بيتي المودة والرحمة، أم يذهب بهما ظلم صغير متكرر؟"}, {"lbl": "الآيات ٢٢ – ٢٥", "q": "وَمِنۡ ءَايَٰتِهِۦ خَلۡقُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَٱخۡتِلَٰفُ أَلۡسِنَتِكُمۡ وَأَلۡوَٰنِكُمۡۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّلۡعَٰلِمِينَ ﴿٢٢﴾ وَمِنۡ ءَايَٰتِهِۦ مَنَامُكُم بِٱلَّيۡلِ وَٱلنَّهَارِ وَٱبۡتِغَآؤُكُم مِّن فَضۡلِهِۦٓۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يَسۡمَعُونَ ﴿٢٣﴾ وَمِنۡ ءَايَٰتِهِۦ يُرِيكُمُ ٱلۡبَرۡقَ خَوۡفٗا وَطَمَعٗا وَيُنَزِّلُ مِنَ ٱلسَّمَآءِ مَآءٗ فَيُحۡيِۦ بِهِ ٱلۡأَرۡضَ بَعۡدَ مَوۡتِهَآۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يَعۡقِلُونَ ﴿٢٤﴾ وَمِنۡ ءَايَٰتِهِۦٓ أَن تَقُومَ ٱلسَّمَآءُ وَٱلۡأَرۡضُ بِأَمۡرِهِۦۚ ثُمَّ إِذَا دَعَاكُمۡ دَعۡوَةٗ مِّنَ ٱلۡأَرۡضِ إِذَآ أَنتُمۡ تَخۡرُجُونَ ﴿٢٥﴾", "w": [["ومن آياته", "حججه وبراهينه الدالة على قدرته على البعث."], ["واختلاف ألسنتكم", "لغاتكم من عربية وعجمية، ولهجاتكم التي يتميز بها كل ناطق."], ["وألوانكم", "من أبيض وأصفر وأحمر وأسود، والكل أبناء رجل واحد."], ["للعالمين", "للعقلاء، وعلى قراءة الكسر: لأولي العلم."], ["وابتغاؤكم من فضله", "طلبكم الرزق بإحضار أسبابه من زراعة وتجارة."], ["لقوم يسمعون", "سماع تدبّر وفهم، لا مجرد سماع الأصوات."], ["يريكم البرق خوفاً وطمعاً", "خوفاً من الصواعق والأمطار الشديدة، وطمعاً في المطر."], ["أن تقوم السماء والأرض بأمره", "قيامهما على ما هما عليه بقدرته وتدبيره."], ["دعوة من الأرض", "دعوة واحدة، وهي نفخة إسرافيل."]], "m": "ما زال السياق في تقرير التوحيد والبعث بالأدلة: ومن آياته خلق السماوات والأرض، واختلاف لغاتكم ولهجاتكم حتى يُعرف كل ناطق بصوته، واختلاف ألوانكم وملامحكم حتى لا يوجد اثنان لا يتميّز أحدهما عن الآخر، إن في ذلك لآيات للعالمين. ومن آياته منامكم بالليل كالموت، وانتشاركم بالنهار في طلب الرزق كالبعث، عملية تتكرّر كل يوم، إن في ذلك لآيات لقوم يسمعون سماع تدبّر. ومن آياته يريكم البرق خوفاً من الصواعق وطمعاً في المطر، وينزّل من السماء ماءً فيحيي به الأرض بعد موتها، إن في ذلك لآيات لقوم يعقلون. ومن آياته أن تقوم السماء والأرض بأمره منذ خلقهما، فلا السماء تسقط ولا الأرض تغور، ثم إذا دعاكم دعوة واحدة بنفخ إسرافيل في الصور إذا أنتم تخرجون من قبوركم أحياء للحساب.", "h": ["بيان مظاهر قدرة الله تعالى وعلمه وحكمته ورحمته الموجبة لعبادته وحده.", "مشروعية طلب الرزق بالمشي في الأرض واستعمال الوسائل المشروعة لذلك.", "تقرير أن الذين ينتفعون بأسماعهم وعقولهم هم أهل حياة الإيمان، إذ الإيمان إذا دخل جسماً حيي وأصبح صاحبه يسمع ويبصر ويعقل.", "تقرير عقيدة البعث والجزاء التي عليها مدار الإصلاح البشري بعد عقيدة التوحيد."], "k": "«واختلاف ألسنتكم وألوانكم»… الاختلاف بين الناس آية؛ فهل أنظر إليه بعين التدبّر أم بعين التعالي؟"}, {"lbl": "الآيات ٢٦ – ٢٩", "q": "وَلَهُۥ مَن فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ كُلّٞ لَّهُۥ قَٰنِتُونَ ﴿٢٦﴾ وَهُوَ ٱلَّذِي يَبۡدَؤُاْ ٱلۡخَلۡقَ ثُمَّ يُعِيدُهُۥ وَهُوَ أَهۡوَنُ عَلَيۡهِۚ وَلَهُ ٱلۡمَثَلُ ٱلۡأَعۡلَىٰ فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ وَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ ﴿٢٧﴾ ضَرَبَ لَكُم مَّثَلٗا مِّنۡ أَنفُسِكُمۡۖ هَل لَّكُم مِّن مَّا مَلَكَتۡ أَيۡمَٰنُكُم مِّن شُرَكَآءَ فِي مَا رَزَقۡنَٰكُمۡ فَأَنتُمۡ فِيهِ سَوَآءٞ تَخَافُونَهُمۡ كَخِيفَتِكُمۡ أَنفُسَكُمۡۚ كَذَٰلِكَ نُفَصِّلُ ٱلۡأٓيَٰتِ لِقَوۡمٖ يَعۡقِلُونَ ﴿٢٨﴾ بَلِ ٱتَّبَعَ ٱلَّذِينَ ظَلَمُوٓاْ أَهۡوَآءَهُم بِغَيۡرِ عِلۡمٖۖ فَمَن يَهۡدِي مَنۡ أَضَلَّ ٱللَّهُۖ وَمَا لَهُم مِّن نَّـٰصِرِينَ ﴿٢٩﴾", "w": [["وله من في السماوات والأرض", "خلقاً وملكاً وتصرّفاً وعبيداً."], ["كلٌّ له قانتون", "منقادون له تجري عليهم أحكامه كما أرادها."], ["وهو أهون عليه", "أيسر وأسهل، نظراً إلى أن الإعادة أسهل من البداية."], ["وله المثل الأعلى", "الوصف الأعلى في كل كمال."], ["ضرب لكم مثلاً", "جعل لكم مثلاً."], ["من أنفسكم", "منتزعاً مما تعرفونه من أنفسكم وأموالكم."], ["كخيفتكم أنفسكم", "كتخوّف بعضكم من بعض أيها الأحرار."], ["نفصّل الآيات", "نبيّنها بتنويع الأسلوب وإيراد الحجج."], ["بل اتّبع الذين ظلموا أهواءهم", "ليس الأمر قصوراً في البيان، وإنما العلّة اتّباعهم أهواءهم."], ["فمن يهدي من أضلّ الله", "لا أحد."]], "m": "وله من في السماوات والأرض من ملائكة وجن وإنس، خلقاً وملكاً، كلٌّ له منقادون لما أراده منهم من حياة وموت ونشور. وهو الذي يبدأ الخلق ثم يعيده يوم القيامة، وهو أهون عليه، خاطبهم بما يتعارفون عليه من أن الإعادة أسهل من البداءة ليقتنعوا، وإلا فلا شيء صعب على الله، وله الوصف الأعلى في السماوات والأرض، وهو الألوهية والوحدانية، وهو العزيز الحكيم. ضرب لكم مثلاً من أنفسكم: هل لكم من عبيدكم شركاء فيما رزقناكم فأنتم فيه سواء، تخافونهم كما يخاف بعضكم بعضاً؟ لا ترضون بذلك أبداً، فكذلك الله لا يرضى أن يكون من عبيده شريك له في عبادته. كذلك نفصّل الآيات لقوم يعقلون. بل اتّبع الذين ظلموا أهواءهم بغير علم، فمن يهدي من أضلّ الله حسب سنّته؟ وما لهم من ناصرين.", "h": ["تقرير عقيدة البعث والتوحيد بذكر الأدلة وضرب الأمثال وتفصيل الآيات.", "تفرّد الرب تعالى بالمثل الأعلى في كل جلال وكمال.", "استحسان ضرب الأمثال لتقريب المعاني إلى الأفهام.", "عظم فائدة هذا المثل، حتى قال بعضهم: تعلّم هذا المثل أفضل من حفظ كذا مسألة فقهية.", "علّة ضلال الناس اتّباعهم أهواءهم بغير علم، وانصرافهم عن الهدى بالاسترسال في اتّباع الهوى."], "k": "«تخافونهم كخيفتكم أنفسكم»… ما لا أرضاه لنفسي من شريك، كيف أرضاه لربي في قلبي؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (292, 30, 30, 40, 'سورة الروم ٣٠ – ٤٠', '«فأقم وجهك للدين حنيفاً فطرة الله التي فطر الناس عليها»، و«وإذا مسّ الناس ضرّ دعوا ربهم»، و«فآت ذا القربى حقه»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 292) = $j$[{"lbl": "الآيات ٣٠ – ٣٢", "q": "فَأَقِمۡ وَجۡهَكَ لِلدِّينِ حَنِيفٗاۚ فِطۡرَتَ ٱللَّهِ ٱلَّتِي فَطَرَ ٱلنَّاسَ عَلَيۡهَاۚ لَا تَبۡدِيلَ لِخَلۡقِ ٱللَّهِۚ ذَٰلِكَ ٱلدِّينُ ٱلۡقَيِّمُ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَعۡلَمُونَ ﴿٣٠﴾ ۞مُنِيبِينَ إِلَيۡهِ وَٱتَّقُوهُ وَأَقِيمُواْ ٱلصَّلَوٰةَ وَلَا تَكُونُواْ مِنَ ٱلۡمُشۡرِكِينَ ﴿٣١﴾ مِنَ ٱلَّذِينَ فَرَّقُواْ دِينَهُمۡ وَكَانُواْ شِيَعٗاۖ كُلُّ حِزۡبِۭ بِمَا لَدَيۡهِمۡ فَرِحُونَ ﴿٣٢﴾", "w": [["فأقم وجهك للدين حنيفاً", "سدّد وجهك للدين الإسلامي لا تنظر إلى غيره، مائلاً عن سائر الأديان إليه."], ["فطرة الله", "صنعة الله التي صنع عليها الإنسان، وهي قابليته للإيمان والتوحيد."], ["لا تبديل لخلق الله", "لا تعملوا على تغيير تلك القابلية؛ خبرية لفظاً إنشائية معنى."], ["الدين القيّم", "المستقيم الذي لا يضل الآخذ به."], ["منيبين إليه", "راجعين إليه بفعل محابّه وترك مكارهه."], ["وكانوا شيعاً", "طوائف وأحزاباً، كل فرقة فرحة بما هي عليه."]], "m": "لما قرّر تعالى التوحيد والبعث والنبوة أمر رسوله والمؤمنين: فأقم وجهك للدين الحق، دين الإسلام، مائلاً إليه عن الأديان المنحرفة، فطرة الله التي فطر الناس عليها، وهي خلق الإنسان قابلاً للإيمان والتوحيد، لا تبدّلوا تلك الخلقة بل نمّوها بالتربية حتى ينشأ الإنسان على الإيمان، ذلك الدين القيّم، ولكن أكثر الناس لا يعلمونه. أقيموا وجوهكم له راجعين إلى الله تائبين، واتّقوه، وأقيموا الصلاة في أوقاتها كما شرعها كمّاً وكيفاً فإنها سقيا الإيمان، ولا تكونوا من المشركين بأي ضرب من الشرك، من الذين فرّقوا دينهم الذي يجب أن يكونوا عليه، دين الفطرة، وكانوا فرقاً وأحزاباً، كل حزب بما لديهم فرحون، يظن أنه الحق وهو الباطل.", "h": ["وجوب الإقبال على الله تعالى بعبادته والإخلاص له فيها.", "الإسلام دين الله الذي خلق الإنسان متأهّلاً له، ولا يقبل منه ديناً غيره.", "وجوب الإنابة إلى الله تعالى والرجوع إليه في كل حال.", "وجوب تقوى الله عز وجل وإقام الصلاة.", "البراءة من الشرك والمشركين.", "حرمة الافتراق في الدين الإسلامي، ووجوب الاتحاد فيه عقيدة وعبادة وقضاءً."], "k": "«فطرة الله التي فطر الناس عليها»… ما الذي غطّى فطرتي من عادات؟ وكيف أعود إليها؟"}, {"lbl": "الآيات ٣٣ – ٣٧", "q": "وَإِذَا مَسَّ ٱلنَّاسَ ضُرّٞ دَعَوۡاْ رَبَّهُم مُّنِيبِينَ إِلَيۡهِ ثُمَّ إِذَآ أَذَاقَهُم مِّنۡهُ رَحۡمَةً إِذَا فَرِيقٞ مِّنۡهُم بِرَبِّهِمۡ يُشۡرِكُونَ ﴿٣٣﴾ لِيَكۡفُرُواْ بِمَآ ءَاتَيۡنَٰهُمۡۚ فَتَمَتَّعُواْ فَسَوۡفَ تَعۡلَمُونَ ﴿٣٤﴾ أَمۡ أَنزَلۡنَا عَلَيۡهِمۡ سُلۡطَٰنٗا فَهُوَ يَتَكَلَّمُ بِمَا كَانُواْ بِهِۦ يُشۡرِكُونَ ﴿٣٥﴾ وَإِذَآ أَذَقۡنَا ٱلنَّاسَ رَحۡمَةٗ فَرِحُواْ بِهَاۖ وَإِن تُصِبۡهُمۡ سَيِّئَةُۢ بِمَا قَدَّمَتۡ أَيۡدِيهِمۡ إِذَا هُمۡ يَقۡنَطُونَ ﴿٣٦﴾ أَوَلَمۡ يَرَوۡاْ أَنَّ ٱللَّهَ يَبۡسُطُ ٱلرِّزۡقَ لِمَن يَشَآءُ وَيَقۡدِرُۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يُؤۡمِنُونَ ﴿٣٧﴾", "w": [["وإذا مسّ الناس ضرّ", "إذا مسّ المشركين شدة من مرض أو فقر أو قحط."], ["منيبين إليه", "راجعين بالضراعة والدعاء إليه وحده."], ["رحمة", "كشف ضر، أو إنزال غيث وسعة رزق."], ["يشركون", "بربهم، فيعبدون معه غيره بالذبح والنذر."], ["ليكفروا بما آتيناهم", "ليكون مقابل النعمة كفراً بها."], ["أم أنزلنا عليهم سلطاناً", "حجة من كتاب ينطق بشركهم ويقرّه لهم؟"], ["بما قدّمت أيديهم", "بذنوبهم وخروجهم عن سنن الله."], ["إذا هم يقنطون", "ييأسون من الفرج."], ["يبسط الرزق لمن يشاء ويقدر", "يوسّعه امتحاناً، ويضيّقه ابتلاءً."]], "m": "لما أمر بإقامة الدين أخبر عن المشركين: إذا مسّهم ضرّ من مرض أو قحط دعوا ربهم وحده راجعين إليه، ثم إذا أذاقهم منه رحمة من صحة وخصب إذا فريق منهم بربهم يشركون، ليكفروا بما آتيناهم من كشف الضر، فتمتّعوا فسوف تعلمون عاقبة كفركم. أم أنزلنا عليهم حجة من كتاب تنطق بشركهم وتقرّه؟ لا، وإنما هو الجهل والتقليد والعناد. وإذا أذقنا الناس من أهل الشرك رحمة فرحوا بها فرح البطر، وإن تصبهم سيئة من جدب أو مرض بما قدّمت أيديهم من الذنوب إذا هم ييأسون من الفرج لجهلهم بربهم. أوَلم يروا أن الله يبسط الرزق لمن يشاء امتحاناً: أيشكر أم يكفر؟ ويضيّقه على من يشاء ابتلاءً: أيصبر أم يسخط؟ إن في ذلك لآيات لقوم يؤمنون.", "h": ["بيان جهل المشركين وضلال عقولهم بما ذكر تعالى من صفاتهم وأحوالهم.", "بيان تهديد الله تعالى للمصرّين على الشرك والكفر بعذاب يوم القيامة.", "بيان حال أهل الشرك والجهل في فرحهم بالنعمة فرح البطر، وقنوطهم عند نزول البلاء.", "مظهر حكمة الله وتدبيره في الرزق توسعةً وتقديراً، وإدراك ذلك خاص بالمؤمنين لأنهم أحياء يبصرون ويفهمون."], "k": "«إذا هم يقنطون»… حين تصيبني شدة، هل يغلبني اليأس أم أعرف أن الرزق بيده يبسطه ويقدره؟"}, {"lbl": "الآيات ٣٨ – ٤٠", "q": "فَـَٔاتِ ذَا ٱلۡقُرۡبَىٰ حَقَّهُۥ وَٱلۡمِسۡكِينَ وَٱبۡنَ ٱلسَّبِيلِۚ ذَٰلِكَ خَيۡرٞ لِّلَّذِينَ يُرِيدُونَ وَجۡهَ ٱللَّهِۖ وَأُوْلَـٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ ﴿٣٨﴾ وَمَآ ءَاتَيۡتُم مِّن رِّبٗا لِّيَرۡبُوَاْ فِيٓ أَمۡوَٰلِ ٱلنَّاسِ فَلَا يَرۡبُواْ عِندَ ٱللَّهِۖ وَمَآ ءَاتَيۡتُم مِّن زَكَوٰةٖ تُرِيدُونَ وَجۡهَ ٱللَّهِ فَأُوْلَـٰٓئِكَ هُمُ ٱلۡمُضۡعِفُونَ ﴿٣٩﴾ ٱللَّهُ ٱلَّذِي خَلَقَكُمۡ ثُمَّ رَزَقَكُمۡ ثُمَّ يُمِيتُكُمۡ ثُمَّ يُحۡيِيكُمۡۖ هَلۡ مِن شُرَكَآئِكُم مَّن يَفۡعَلُ مِن ذَٰلِكُم مِّن شَيۡءٖۚ سُبۡحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يُشۡرِكُونَ ﴿٤٠﴾", "w": [["فآت ذا القربى حقه", "أعطِ ذا القرابة حقه من البرّ والصلة."], ["والمسكين", "المعدم الذي لا مال له، حقه في الطعام والشراب."], ["وابن السبيل", "المسافر، حقه في الإيواء والإطعام."], ["ذلك خير", "ذلك الإنفاق خير للذين يريدون وجه الله."], ["وما آتيتم من رباً", "من هدية أو هبة يُقصد بها أن يُردّ أكثر منها."], ["فلا يربو عند الله", "لا يُضاعف أجره."], ["فأولئك هم المضعِفون", "الذين يُضاعف لهم الأجر أضعافاً."], ["هل من شركائكم", "من أصنامكم التي تعبدونها."], ["من يفعل من ذلكم من شيء", "والجواب: لا أحد، فبطلت ألوهيتها."]], "m": "لما بيّن أنه يبسط الرزق ويقدره أمر رسوله وأمته بإيتاء الحقوق، لأن أداءها لا يزيد في ضيق الرزق: فآت ذا القربى حقه من البرّ والصلة، والمسكين الذي لا يملك قوته، وابن السبيل المسافر الغريب، إيواءً وإطعاماً وكسوة، ذلك خير حالاً ومآلاً للذين يريدون وجه الله، وأولئك هم الفائزون. وما أعطيتم من هبات وهدايا تريدون أن يُردّ عليكم أكثر منها فلا يربو عند الله ولا يُضاعف أجره، وما آتيتم من صدقة تريدون بها وجه الله فأولئك هم الذين يُضاعف لهم الأجر. الله الذي خلقكم ولم تكونوا شيئاً، ثم رزقكم، ثم يميتكم عند آجالكم، ثم يحييكم يوم القيامة للحساب، هل من شركائكم من يفعل من ذلك شيئاً؟ لا، فلمَ تعبدونهم؟ سبحانه وتعالى عما يشركون.", "h": ["وجوب إعطاء ذوي القربى حقوقهم من البرّ والصلة.", "وجوب كفاية الفقراء وأبناء السبيل في المجتمع الإسلامي.", "جواز هدية الثواب الدنيوي، كأن يُهدي رجل شيئاً يريد أن يُردّ عليه أكثر منه، ولا ثواب فيه في الآخرة، وهي للرسول ﷺ محرّمة لقوله تعالى: «ولا تمنن تستكثر».", "بيان مضاعفة الصدقات التي يُراد بها وجه الله تعالى.", "إبطال الشرك والتنديد بالمشركين وبيان جهلهم."], "k": "«فآت ذا القربى حقه»… من أقاربي من له عندي حقّ صلة لم أؤدّه بعد؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 292;
insert into public.tdb_cards(topic, i, body) select 292, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٣٠ – ٣٢", "q": "فَأَقِمۡ وَجۡهَكَ لِلدِّينِ حَنِيفٗاۚ فِطۡرَتَ ٱللَّهِ ٱلَّتِي فَطَرَ ٱلنَّاسَ عَلَيۡهَاۚ لَا تَبۡدِيلَ لِخَلۡقِ ٱللَّهِۚ ذَٰلِكَ ٱلدِّينُ ٱلۡقَيِّمُ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَعۡلَمُونَ ﴿٣٠﴾ ۞مُنِيبِينَ إِلَيۡهِ وَٱتَّقُوهُ وَأَقِيمُواْ ٱلصَّلَوٰةَ وَلَا تَكُونُواْ مِنَ ٱلۡمُشۡرِكِينَ ﴿٣١﴾ مِنَ ٱلَّذِينَ فَرَّقُواْ دِينَهُمۡ وَكَانُواْ شِيَعٗاۖ كُلُّ حِزۡبِۭ بِمَا لَدَيۡهِمۡ فَرِحُونَ ﴿٣٢﴾", "w": [["فأقم وجهك للدين حنيفاً", "سدّد وجهك للدين الإسلامي لا تنظر إلى غيره، مائلاً عن سائر الأديان إليه."], ["فطرة الله", "صنعة الله التي صنع عليها الإنسان، وهي قابليته للإيمان والتوحيد."], ["لا تبديل لخلق الله", "لا تعملوا على تغيير تلك القابلية؛ خبرية لفظاً إنشائية معنى."], ["الدين القيّم", "المستقيم الذي لا يضل الآخذ به."], ["منيبين إليه", "راجعين إليه بفعل محابّه وترك مكارهه."], ["وكانوا شيعاً", "طوائف وأحزاباً، كل فرقة فرحة بما هي عليه."]], "m": "لما قرّر تعالى التوحيد والبعث والنبوة أمر رسوله والمؤمنين: فأقم وجهك للدين الحق، دين الإسلام، مائلاً إليه عن الأديان المنحرفة، فطرة الله التي فطر الناس عليها، وهي خلق الإنسان قابلاً للإيمان والتوحيد، لا تبدّلوا تلك الخلقة بل نمّوها بالتربية حتى ينشأ الإنسان على الإيمان، ذلك الدين القيّم، ولكن أكثر الناس لا يعلمونه. أقيموا وجوهكم له راجعين إلى الله تائبين، واتّقوه، وأقيموا الصلاة في أوقاتها كما شرعها كمّاً وكيفاً فإنها سقيا الإيمان، ولا تكونوا من المشركين بأي ضرب من الشرك، من الذين فرّقوا دينهم الذي يجب أن يكونوا عليه، دين الفطرة، وكانوا فرقاً وأحزاباً، كل حزب بما لديهم فرحون، يظن أنه الحق وهو الباطل.", "h": ["وجوب الإقبال على الله تعالى بعبادته والإخلاص له فيها.", "الإسلام دين الله الذي خلق الإنسان متأهّلاً له، ولا يقبل منه ديناً غيره.", "وجوب الإنابة إلى الله تعالى والرجوع إليه في كل حال.", "وجوب تقوى الله عز وجل وإقام الصلاة.", "البراءة من الشرك والمشركين.", "حرمة الافتراق في الدين الإسلامي، ووجوب الاتحاد فيه عقيدة وعبادة وقضاءً."], "k": "«فطرة الله التي فطر الناس عليها»… ما الذي غطّى فطرتي من عادات؟ وكيف أعود إليها؟"}, {"lbl": "الآيات ٣٣ – ٣٧", "q": "وَإِذَا مَسَّ ٱلنَّاسَ ضُرّٞ دَعَوۡاْ رَبَّهُم مُّنِيبِينَ إِلَيۡهِ ثُمَّ إِذَآ أَذَاقَهُم مِّنۡهُ رَحۡمَةً إِذَا فَرِيقٞ مِّنۡهُم بِرَبِّهِمۡ يُشۡرِكُونَ ﴿٣٣﴾ لِيَكۡفُرُواْ بِمَآ ءَاتَيۡنَٰهُمۡۚ فَتَمَتَّعُواْ فَسَوۡفَ تَعۡلَمُونَ ﴿٣٤﴾ أَمۡ أَنزَلۡنَا عَلَيۡهِمۡ سُلۡطَٰنٗا فَهُوَ يَتَكَلَّمُ بِمَا كَانُواْ بِهِۦ يُشۡرِكُونَ ﴿٣٥﴾ وَإِذَآ أَذَقۡنَا ٱلنَّاسَ رَحۡمَةٗ فَرِحُواْ بِهَاۖ وَإِن تُصِبۡهُمۡ سَيِّئَةُۢ بِمَا قَدَّمَتۡ أَيۡدِيهِمۡ إِذَا هُمۡ يَقۡنَطُونَ ﴿٣٦﴾ أَوَلَمۡ يَرَوۡاْ أَنَّ ٱللَّهَ يَبۡسُطُ ٱلرِّزۡقَ لِمَن يَشَآءُ وَيَقۡدِرُۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يُؤۡمِنُونَ ﴿٣٧﴾", "w": [["وإذا مسّ الناس ضرّ", "إذا مسّ المشركين شدة من مرض أو فقر أو قحط."], ["منيبين إليه", "راجعين بالضراعة والدعاء إليه وحده."], ["رحمة", "كشف ضر، أو إنزال غيث وسعة رزق."], ["يشركون", "بربهم، فيعبدون معه غيره بالذبح والنذر."], ["ليكفروا بما آتيناهم", "ليكون مقابل النعمة كفراً بها."], ["أم أنزلنا عليهم سلطاناً", "حجة من كتاب ينطق بشركهم ويقرّه لهم؟"], ["بما قدّمت أيديهم", "بذنوبهم وخروجهم عن سنن الله."], ["إذا هم يقنطون", "ييأسون من الفرج."], ["يبسط الرزق لمن يشاء ويقدر", "يوسّعه امتحاناً، ويضيّقه ابتلاءً."]], "m": "لما أمر بإقامة الدين أخبر عن المشركين: إذا مسّهم ضرّ من مرض أو قحط دعوا ربهم وحده راجعين إليه، ثم إذا أذاقهم منه رحمة من صحة وخصب إذا فريق منهم بربهم يشركون، ليكفروا بما آتيناهم من كشف الضر، فتمتّعوا فسوف تعلمون عاقبة كفركم. أم أنزلنا عليهم حجة من كتاب تنطق بشركهم وتقرّه؟ لا، وإنما هو الجهل والتقليد والعناد. وإذا أذقنا الناس من أهل الشرك رحمة فرحوا بها فرح البطر، وإن تصبهم سيئة من جدب أو مرض بما قدّمت أيديهم من الذنوب إذا هم ييأسون من الفرج لجهلهم بربهم. أوَلم يروا أن الله يبسط الرزق لمن يشاء امتحاناً: أيشكر أم يكفر؟ ويضيّقه على من يشاء ابتلاءً: أيصبر أم يسخط؟ إن في ذلك لآيات لقوم يؤمنون.", "h": ["بيان جهل المشركين وضلال عقولهم بما ذكر تعالى من صفاتهم وأحوالهم.", "بيان تهديد الله تعالى للمصرّين على الشرك والكفر بعذاب يوم القيامة.", "بيان حال أهل الشرك والجهل في فرحهم بالنعمة فرح البطر، وقنوطهم عند نزول البلاء.", "مظهر حكمة الله وتدبيره في الرزق توسعةً وتقديراً، وإدراك ذلك خاص بالمؤمنين لأنهم أحياء يبصرون ويفهمون."], "k": "«إذا هم يقنطون»… حين تصيبني شدة، هل يغلبني اليأس أم أعرف أن الرزق بيده يبسطه ويقدره؟"}, {"lbl": "الآيات ٣٨ – ٤٠", "q": "فَـَٔاتِ ذَا ٱلۡقُرۡبَىٰ حَقَّهُۥ وَٱلۡمِسۡكِينَ وَٱبۡنَ ٱلسَّبِيلِۚ ذَٰلِكَ خَيۡرٞ لِّلَّذِينَ يُرِيدُونَ وَجۡهَ ٱللَّهِۖ وَأُوْلَـٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ ﴿٣٨﴾ وَمَآ ءَاتَيۡتُم مِّن رِّبٗا لِّيَرۡبُوَاْ فِيٓ أَمۡوَٰلِ ٱلنَّاسِ فَلَا يَرۡبُواْ عِندَ ٱللَّهِۖ وَمَآ ءَاتَيۡتُم مِّن زَكَوٰةٖ تُرِيدُونَ وَجۡهَ ٱللَّهِ فَأُوْلَـٰٓئِكَ هُمُ ٱلۡمُضۡعِفُونَ ﴿٣٩﴾ ٱللَّهُ ٱلَّذِي خَلَقَكُمۡ ثُمَّ رَزَقَكُمۡ ثُمَّ يُمِيتُكُمۡ ثُمَّ يُحۡيِيكُمۡۖ هَلۡ مِن شُرَكَآئِكُم مَّن يَفۡعَلُ مِن ذَٰلِكُم مِّن شَيۡءٖۚ سُبۡحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يُشۡرِكُونَ ﴿٤٠﴾", "w": [["فآت ذا القربى حقه", "أعطِ ذا القرابة حقه من البرّ والصلة."], ["والمسكين", "المعدم الذي لا مال له، حقه في الطعام والشراب."], ["وابن السبيل", "المسافر، حقه في الإيواء والإطعام."], ["ذلك خير", "ذلك الإنفاق خير للذين يريدون وجه الله."], ["وما آتيتم من رباً", "من هدية أو هبة يُقصد بها أن يُردّ أكثر منها."], ["فلا يربو عند الله", "لا يُضاعف أجره."], ["فأولئك هم المضعِفون", "الذين يُضاعف لهم الأجر أضعافاً."], ["هل من شركائكم", "من أصنامكم التي تعبدونها."], ["من يفعل من ذلكم من شيء", "والجواب: لا أحد، فبطلت ألوهيتها."]], "m": "لما بيّن أنه يبسط الرزق ويقدره أمر رسوله وأمته بإيتاء الحقوق، لأن أداءها لا يزيد في ضيق الرزق: فآت ذا القربى حقه من البرّ والصلة، والمسكين الذي لا يملك قوته، وابن السبيل المسافر الغريب، إيواءً وإطعاماً وكسوة، ذلك خير حالاً ومآلاً للذين يريدون وجه الله، وأولئك هم الفائزون. وما أعطيتم من هبات وهدايا تريدون أن يُردّ عليكم أكثر منها فلا يربو عند الله ولا يُضاعف أجره، وما آتيتم من صدقة تريدون بها وجه الله فأولئك هم الذين يُضاعف لهم الأجر. الله الذي خلقكم ولم تكونوا شيئاً، ثم رزقكم، ثم يميتكم عند آجالكم، ثم يحييكم يوم القيامة للحساب، هل من شركائكم من يفعل من ذلك شيئاً؟ لا، فلمَ تعبدونهم؟ سبحانه وتعالى عما يشركون.", "h": ["وجوب إعطاء ذوي القربى حقوقهم من البرّ والصلة.", "وجوب كفاية الفقراء وأبناء السبيل في المجتمع الإسلامي.", "جواز هدية الثواب الدنيوي، كأن يُهدي رجل شيئاً يريد أن يُردّ عليه أكثر منه، ولا ثواب فيه في الآخرة، وهي للرسول ﷺ محرّمة لقوله تعالى: «ولا تمنن تستكثر».", "بيان مضاعفة الصدقات التي يُراد بها وجه الله تعالى.", "إبطال الشرك والتنديد بالمشركين وبيان جهلهم."], "k": "«فآت ذا القربى حقه»… من أقاربي من له عندي حقّ صلة لم أؤدّه بعد؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (293, 30, 41, 53, 'سورة الروم ٤١ – ٥٣', '«ظهر الفساد في البر والبحر بما كسبت أيدي الناس»، و«وكان حقاً علينا نصر المؤمنين»، و«فانظر إلى آثار رحمة الله»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 293) = $j$[{"lbl": "الآيات ٤١ – ٤٥", "q": "ظَهَرَ ٱلۡفَسَادُ فِي ٱلۡبَرِّ وَٱلۡبَحۡرِ بِمَا كَسَبَتۡ أَيۡدِي ٱلنَّاسِ لِيُذِيقَهُم بَعۡضَ ٱلَّذِي عَمِلُواْ لَعَلَّهُمۡ يَرۡجِعُونَ ﴿٤١﴾ قُلۡ سِيرُواْ فِي ٱلۡأَرۡضِ فَٱنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن قَبۡلُۚ كَانَ أَكۡثَرُهُم مُّشۡرِكِينَ ﴿٤٢﴾ فَأَقِمۡ وَجۡهَكَ لِلدِّينِ ٱلۡقَيِّمِ مِن قَبۡلِ أَن يَأۡتِيَ يَوۡمٞ لَّا مَرَدَّ لَهُۥ مِنَ ٱللَّهِۖ يَوۡمَئِذٖ يَصَّدَّعُونَ ﴿٤٣﴾ مَن كَفَرَ فَعَلَيۡهِ كُفۡرُهُۥۖ وَمَنۡ عَمِلَ صَٰلِحٗا فَلِأَنفُسِهِمۡ يَمۡهَدُونَ ﴿٤٤﴾ لِيَجۡزِيَ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ مِن فَضۡلِهِۦٓۚ إِنَّهُۥ لَا يُحِبُّ ٱلۡكَٰفِرِينَ ﴿٤٥﴾", "w": [["ظهر الفساد في البر والبحر", "ظهرت المعاصي وتبعها الشر."], ["بما كسبت أيدي الناس", "بسبب ما كسبته من ظلم واعتداء."], ["ليذيقهم بعض الذي عملوا", "ليذيقهم العذاب ببعض ذنوبهم."], ["لعلهم يرجعون", "كي يرجعوا عن المعاصي إلى الطاعة."], ["عاقبة الذين من قبل", "نهاية تكذيبهم، وهي هلاكهم."], ["فأقم وجهك للدين القيّم", "استقم على طاعة ربك عابداً له مبلّغاً عنه."], ["لا مردّ له من الله", "لا يردّه الله لأنه قضى بإتيانه، وهو يوم القيامة."], ["يصّدّعون", "يتفرّقون فرقتين."], ["يمهدون", "يوطّئون لأنفسهم منازل الجنة بإيمانهم وصالح أعمالهم."]], "m": "لإصرار المشركين على الشرك سيحصل فساد في الأرض لا محالة: ظهر الفساد في البر والبحر، وفي الجو اليوم، فعُبد غير الله واستُبيحت محارمه وأوذي الناس في أموالهم وأعراضهم، نتيجة الإعراض عن دين الله وإهمال شرائعه، بما كسبت أيدي الناس من ظلم وفجور، فما يصيبهم من جدب وغلاء وحروب وفتن ليذيقهم بعض الذي عملوا لا كله، إذ لو أصابهم بكل ذنوبهم لأنهى حياتهم، لعلهم يرجعون. قل سيروا في الأرض فانظروا كيف كان عاقبة الذين من قبل، كان أكثرهم مشركين. فاستقم أنت ومن معك على الدين القيّم، اعتقدوا عقائده وامتثلوا أوامره واجتنبوا نواهيه وأقيموا حدوده، من قبل أن يأتي يوم لا يردّه الله، يومئذ يتفرّق الناس فريقين، من كفر فعليه كفره، ومن عمل صالحاً فلأنفسهم يوطّئون منازل الجنة، ليجزي الذين آمنوا وعملوا الصالحات من فضله، إنه لا يحب الكافرين.", "h": ["ظهور الفساد بالجدب والغلاء أو بالحرب والأمراض يسبقه، حسب سنن الله، ظهور فساد في العقائد بالشرك، وفي الأعمال بالفسق والمعاصي.", "وجوب الاستقامة على الدين الإسلامي عقيدة وعبادة وقضاءً وحكماً.", "تقرير عقيدة البعث والجزاء بذكر أحداثه ووقائعه.", "بيان أن الله تعالى يحب المتقين ويكره الكافرين."], "k": "«ليذيقهم بعض الذي عملوا لعلهم يرجعون»… ما يصيبني من ضيق قد يكون رسالة؛ فهل أقرؤها وأرجع؟"}, {"lbl": "الآيتان ٤٦ – ٤٧", "q": "وَمِنۡ ءَايَٰتِهِۦٓ أَن يُرۡسِلَ ٱلرِّيَاحَ مُبَشِّرَٰتٖ وَلِيُذِيقَكُم مِّن رَّحۡمَتِهِۦ وَلِتَجۡرِيَ ٱلۡفُلۡكُ بِأَمۡرِهِۦ وَلِتَبۡتَغُواْ مِن فَضۡلِهِۦ وَلَعَلَّكُمۡ تَشۡكُرُونَ ﴿٤٦﴾ وَلَقَدۡ أَرۡسَلۡنَا مِن قَبۡلِكَ رُسُلًا إِلَىٰ قَوۡمِهِمۡ فَجَآءُوهُم بِٱلۡبَيِّنَٰتِ فَٱنتَقَمۡنَا مِنَ ٱلَّذِينَ أَجۡرَمُواْۖ وَكَانَ حَقًّا عَلَيۡنَا نَصۡرُ ٱلۡمُؤۡمِنِينَ ﴿٤٧﴾", "w": [["أن يرسل الرياح", "من حججه الدالة على قدرته على البعث والموجبة لعبادته."], ["مبشّرات", "تبشّر العباد بالمطر وقربه."], ["وليذيقكم من رحمته", "بالغيث والخصب والرخاء."], ["ولتبتغوا من فضله", "لتطلبوا الرزق بالتجارة في البحر."], ["ولعلكم تشكرون", "كي تشكروا هذه النعم."], ["رسلاً إلى قومهم", "كنوح وهود وصالح وإبراهيم ولوط وشعيب."], ["الذين أجرموا", "أفسدوا نفوسهم بآثار الشرك والمعاصي."], ["وكان حقاً علينا نصر المؤمنين", "أحققناه وأوجبناه على أنفسنا."]], "m": "ومن آياتنا الدالة على ألوهيتنا ورحمتنا إرسال الرياح مبشّرات بالمطر الذي به حياة البلاد والعباد، وليذيقكم من رحمته الخصب والرخاء، ولتجري السفن في البحر بأمره، وقد كانت الرياح قبل اكتشاف البخار هي المسيّرة للسفن، ولتبتغوا من فضله بالتجارة من إقليم إلى آخر، ولعلكم تشكرون ربكم بالإيمان والتوحيد. ولقد أرسلنا من قبلك رسلاً إلى قومهم فجاؤوهم بالبيّنات فكذّبوهم، فانتقمنا من الذين أجرموا فأهلكناهم، وكان حقاً علينا نصر المؤمنين، ألا فلتعتبر قريش، وإلا حلّت بها نقمة الله كما هي سنّته في الأولين.", "h": ["تقرير الربوبية لله المستلزمة لألوهيته بذكر مظاهر القدرة والعلم والرحمة.", "بيان أن الله تعالى ينعم على عباده من أجل أن يشكروه، فإن كفروا تلك النعم عذّبهم بما يشاء متى شاء.", "بيان أن الله منتقم من المجرمين وإن طال الزمن، وناصر المؤمنين كذلك."], "k": "«وكان حقاً علينا نصر المؤمنين»… وعد أوجبه الله على نفسه؛ فهل أحقق في نفسي وصف المؤمن لأناله؟"}, {"lbl": "الآيات ٤٨ – ٥٣", "q": "ٱللَّهُ ٱلَّذِي يُرۡسِلُ ٱلرِّيَٰحَ فَتُثِيرُ سَحَابٗا فَيَبۡسُطُهُۥ فِي ٱلسَّمَآءِ كَيۡفَ يَشَآءُ وَيَجۡعَلُهُۥ كِسَفٗا فَتَرَى ٱلۡوَدۡقَ يَخۡرُجُ مِنۡ خِلَٰلِهِۦۖ فَإِذَآ أَصَابَ بِهِۦ مَن يَشَآءُ مِنۡ عِبَادِهِۦٓ إِذَا هُمۡ يَسۡتَبۡشِرُونَ ﴿٤٨﴾ وَإِن كَانُواْ مِن قَبۡلِ أَن يُنَزَّلَ عَلَيۡهِم مِّن قَبۡلِهِۦ لَمُبۡلِسِينَ ﴿٤٩﴾ فَٱنظُرۡ إِلَىٰٓ ءَاثَٰرِ رَحۡمَتِ ٱللَّهِ كَيۡفَ يُحۡيِ ٱلۡأَرۡضَ بَعۡدَ مَوۡتِهَآۚ إِنَّ ذَٰلِكَ لَمُحۡيِ ٱلۡمَوۡتَىٰۖ وَهُوَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ ﴿٥٠﴾ وَلَئِنۡ أَرۡسَلۡنَا رِيحٗا فَرَأَوۡهُ مُصۡفَرّٗا لَّظَلُّواْ مِنۢ بَعۡدِهِۦ يَكۡفُرُونَ ﴿٥١﴾ فَإِنَّكَ لَا تُسۡمِعُ ٱلۡمَوۡتَىٰ وَلَا تُسۡمِعُ ٱلصُّمَّ ٱلدُّعَآءَ إِذَا وَلَّوۡاْ مُدۡبِرِينَ ﴿٥٢﴾ وَمَآ أَنتَ بِهَٰدِ ٱلۡعُمۡيِ عَن ضَلَٰلَتِهِمۡۖ إِن تُسۡمِعُ إِلَّا مَن يُؤۡمِنُ بِـَٔايَٰتِنَا فَهُم مُّسۡلِمُونَ ﴿٥٣﴾", "w": [["فتثير سحاباً", "تحرّكه وتهيّجه فيسير وينتشر."], ["ويجعله كسفاً", "قطعاً متفرقة في السماء."], ["فترى الودق", "المطر يخرج من خلال السحاب."], ["إذا هم يستبشرون", "فرحون بالمطر النازل لسقياهم."], ["لمبلسين", "قانطين آيسين من إنزاله."], ["إن ذلك لمحيي الموتى", "القادر على إحياء الأرض بعد موتها قادر على إحياء الموتى."], ["فرأوه مصفرّاً", "رأوا الزرع مصفرّاً للجائحة التي أصابته."], ["لظلّوا من بعده يكفرون", "أقاموا بعد هلاك زروعهم يكفرون نعم الله."], ["إن تُسمع إلا من يؤمن بآياتنا", "ما تُسمع إلا المؤمنين."]], "m": "ما زال السياق في تقرير البعث بمظاهر القدرة: الله الذي يرسل الرياح فتثير سحاباً فيبسطه في السماء كيف يشاء، ويجعله قطعاً، فترى المطر يخرج من خلاله، فإذا أصاب به من يشاء من عباده إذا هم يفرحون، وإن كانوا من قبل نزوله لمكتئبين قانطين. فانظر إلى آثار رحمة الله كيف يحيي الأرض بعد موتها فتخضرّ بعد يبس، إن ذلك لمحيي الموتى يوم القيامة، وهو على كل شيء قدير. ولئن أرسلنا ريحاً محرقة فرأوا زرعهم مصفرّاً لظلّوا من بعده يكفرون بألفاظ السخط لجهلهم. فإنك لا تُسمع الموتى، لما ران على قلوبهم من الذنوب، ولا تُسمع الصمّ الدعاء إذا ولّوا مدبرين، وما أنت بهادي العمي عن ضلالتهم، فهوّن على نفسك، إن تُسمع سماع قبول إلا من يؤمن بآياتنا فهم منقادون.", "h": ["تقرير عقيدة البعث والجزاء بذكر الأدلة والحجج العقلية.", "بيان حال الكافر في الرخاء والشدة، فهو في الشدة يقنط وفي الرخاء يكفر، لفساد قلبه بالجهل بالله.", "الاستدلال بالمحسوس الحاضر على المحسوس الغيبي.", "بيان أن الكفار أموات، ولذا لا يسمعون ولا يبصرون، وأن المؤمنين أحياء."], "k": "«فانظر إلى آثار رحمة الله»… أين أرى أثر رحمته في يومي هذا؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 293;
insert into public.tdb_cards(topic, i, body) select 293, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٤١ – ٤٥", "q": "ظَهَرَ ٱلۡفَسَادُ فِي ٱلۡبَرِّ وَٱلۡبَحۡرِ بِمَا كَسَبَتۡ أَيۡدِي ٱلنَّاسِ لِيُذِيقَهُم بَعۡضَ ٱلَّذِي عَمِلُواْ لَعَلَّهُمۡ يَرۡجِعُونَ ﴿٤١﴾ قُلۡ سِيرُواْ فِي ٱلۡأَرۡضِ فَٱنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن قَبۡلُۚ كَانَ أَكۡثَرُهُم مُّشۡرِكِينَ ﴿٤٢﴾ فَأَقِمۡ وَجۡهَكَ لِلدِّينِ ٱلۡقَيِّمِ مِن قَبۡلِ أَن يَأۡتِيَ يَوۡمٞ لَّا مَرَدَّ لَهُۥ مِنَ ٱللَّهِۖ يَوۡمَئِذٖ يَصَّدَّعُونَ ﴿٤٣﴾ مَن كَفَرَ فَعَلَيۡهِ كُفۡرُهُۥۖ وَمَنۡ عَمِلَ صَٰلِحٗا فَلِأَنفُسِهِمۡ يَمۡهَدُونَ ﴿٤٤﴾ لِيَجۡزِيَ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ مِن فَضۡلِهِۦٓۚ إِنَّهُۥ لَا يُحِبُّ ٱلۡكَٰفِرِينَ ﴿٤٥﴾", "w": [["ظهر الفساد في البر والبحر", "ظهرت المعاصي وتبعها الشر."], ["بما كسبت أيدي الناس", "بسبب ما كسبته من ظلم واعتداء."], ["ليذيقهم بعض الذي عملوا", "ليذيقهم العذاب ببعض ذنوبهم."], ["لعلهم يرجعون", "كي يرجعوا عن المعاصي إلى الطاعة."], ["عاقبة الذين من قبل", "نهاية تكذيبهم، وهي هلاكهم."], ["فأقم وجهك للدين القيّم", "استقم على طاعة ربك عابداً له مبلّغاً عنه."], ["لا مردّ له من الله", "لا يردّه الله لأنه قضى بإتيانه، وهو يوم القيامة."], ["يصّدّعون", "يتفرّقون فرقتين."], ["يمهدون", "يوطّئون لأنفسهم منازل الجنة بإيمانهم وصالح أعمالهم."]], "m": "لإصرار المشركين على الشرك سيحصل فساد في الأرض لا محالة: ظهر الفساد في البر والبحر، وفي الجو اليوم، فعُبد غير الله واستُبيحت محارمه وأوذي الناس في أموالهم وأعراضهم، نتيجة الإعراض عن دين الله وإهمال شرائعه، بما كسبت أيدي الناس من ظلم وفجور، فما يصيبهم من جدب وغلاء وحروب وفتن ليذيقهم بعض الذي عملوا لا كله، إذ لو أصابهم بكل ذنوبهم لأنهى حياتهم، لعلهم يرجعون. قل سيروا في الأرض فانظروا كيف كان عاقبة الذين من قبل، كان أكثرهم مشركين. فاستقم أنت ومن معك على الدين القيّم، اعتقدوا عقائده وامتثلوا أوامره واجتنبوا نواهيه وأقيموا حدوده، من قبل أن يأتي يوم لا يردّه الله، يومئذ يتفرّق الناس فريقين، من كفر فعليه كفره، ومن عمل صالحاً فلأنفسهم يوطّئون منازل الجنة، ليجزي الذين آمنوا وعملوا الصالحات من فضله، إنه لا يحب الكافرين.", "h": ["ظهور الفساد بالجدب والغلاء أو بالحرب والأمراض يسبقه، حسب سنن الله، ظهور فساد في العقائد بالشرك، وفي الأعمال بالفسق والمعاصي.", "وجوب الاستقامة على الدين الإسلامي عقيدة وعبادة وقضاءً وحكماً.", "تقرير عقيدة البعث والجزاء بذكر أحداثه ووقائعه.", "بيان أن الله تعالى يحب المتقين ويكره الكافرين."], "k": "«ليذيقهم بعض الذي عملوا لعلهم يرجعون»… ما يصيبني من ضيق قد يكون رسالة؛ فهل أقرؤها وأرجع؟"}, {"lbl": "الآيتان ٤٦ – ٤٧", "q": "وَمِنۡ ءَايَٰتِهِۦٓ أَن يُرۡسِلَ ٱلرِّيَاحَ مُبَشِّرَٰتٖ وَلِيُذِيقَكُم مِّن رَّحۡمَتِهِۦ وَلِتَجۡرِيَ ٱلۡفُلۡكُ بِأَمۡرِهِۦ وَلِتَبۡتَغُواْ مِن فَضۡلِهِۦ وَلَعَلَّكُمۡ تَشۡكُرُونَ ﴿٤٦﴾ وَلَقَدۡ أَرۡسَلۡنَا مِن قَبۡلِكَ رُسُلًا إِلَىٰ قَوۡمِهِمۡ فَجَآءُوهُم بِٱلۡبَيِّنَٰتِ فَٱنتَقَمۡنَا مِنَ ٱلَّذِينَ أَجۡرَمُواْۖ وَكَانَ حَقًّا عَلَيۡنَا نَصۡرُ ٱلۡمُؤۡمِنِينَ ﴿٤٧﴾", "w": [["أن يرسل الرياح", "من حججه الدالة على قدرته على البعث والموجبة لعبادته."], ["مبشّرات", "تبشّر العباد بالمطر وقربه."], ["وليذيقكم من رحمته", "بالغيث والخصب والرخاء."], ["ولتبتغوا من فضله", "لتطلبوا الرزق بالتجارة في البحر."], ["ولعلكم تشكرون", "كي تشكروا هذه النعم."], ["رسلاً إلى قومهم", "كنوح وهود وصالح وإبراهيم ولوط وشعيب."], ["الذين أجرموا", "أفسدوا نفوسهم بآثار الشرك والمعاصي."], ["وكان حقاً علينا نصر المؤمنين", "أحققناه وأوجبناه على أنفسنا."]], "m": "ومن آياتنا الدالة على ألوهيتنا ورحمتنا إرسال الرياح مبشّرات بالمطر الذي به حياة البلاد والعباد، وليذيقكم من رحمته الخصب والرخاء، ولتجري السفن في البحر بأمره، وقد كانت الرياح قبل اكتشاف البخار هي المسيّرة للسفن، ولتبتغوا من فضله بالتجارة من إقليم إلى آخر، ولعلكم تشكرون ربكم بالإيمان والتوحيد. ولقد أرسلنا من قبلك رسلاً إلى قومهم فجاؤوهم بالبيّنات فكذّبوهم، فانتقمنا من الذين أجرموا فأهلكناهم، وكان حقاً علينا نصر المؤمنين، ألا فلتعتبر قريش، وإلا حلّت بها نقمة الله كما هي سنّته في الأولين.", "h": ["تقرير الربوبية لله المستلزمة لألوهيته بذكر مظاهر القدرة والعلم والرحمة.", "بيان أن الله تعالى ينعم على عباده من أجل أن يشكروه، فإن كفروا تلك النعم عذّبهم بما يشاء متى شاء.", "بيان أن الله منتقم من المجرمين وإن طال الزمن، وناصر المؤمنين كذلك."], "k": "«وكان حقاً علينا نصر المؤمنين»… وعد أوجبه الله على نفسه؛ فهل أحقق في نفسي وصف المؤمن لأناله؟"}, {"lbl": "الآيات ٤٨ – ٥٣", "q": "ٱللَّهُ ٱلَّذِي يُرۡسِلُ ٱلرِّيَٰحَ فَتُثِيرُ سَحَابٗا فَيَبۡسُطُهُۥ فِي ٱلسَّمَآءِ كَيۡفَ يَشَآءُ وَيَجۡعَلُهُۥ كِسَفٗا فَتَرَى ٱلۡوَدۡقَ يَخۡرُجُ مِنۡ خِلَٰلِهِۦۖ فَإِذَآ أَصَابَ بِهِۦ مَن يَشَآءُ مِنۡ عِبَادِهِۦٓ إِذَا هُمۡ يَسۡتَبۡشِرُونَ ﴿٤٨﴾ وَإِن كَانُواْ مِن قَبۡلِ أَن يُنَزَّلَ عَلَيۡهِم مِّن قَبۡلِهِۦ لَمُبۡلِسِينَ ﴿٤٩﴾ فَٱنظُرۡ إِلَىٰٓ ءَاثَٰرِ رَحۡمَتِ ٱللَّهِ كَيۡفَ يُحۡيِ ٱلۡأَرۡضَ بَعۡدَ مَوۡتِهَآۚ إِنَّ ذَٰلِكَ لَمُحۡيِ ٱلۡمَوۡتَىٰۖ وَهُوَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ ﴿٥٠﴾ وَلَئِنۡ أَرۡسَلۡنَا رِيحٗا فَرَأَوۡهُ مُصۡفَرّٗا لَّظَلُّواْ مِنۢ بَعۡدِهِۦ يَكۡفُرُونَ ﴿٥١﴾ فَإِنَّكَ لَا تُسۡمِعُ ٱلۡمَوۡتَىٰ وَلَا تُسۡمِعُ ٱلصُّمَّ ٱلدُّعَآءَ إِذَا وَلَّوۡاْ مُدۡبِرِينَ ﴿٥٢﴾ وَمَآ أَنتَ بِهَٰدِ ٱلۡعُمۡيِ عَن ضَلَٰلَتِهِمۡۖ إِن تُسۡمِعُ إِلَّا مَن يُؤۡمِنُ بِـَٔايَٰتِنَا فَهُم مُّسۡلِمُونَ ﴿٥٣﴾", "w": [["فتثير سحاباً", "تحرّكه وتهيّجه فيسير وينتشر."], ["ويجعله كسفاً", "قطعاً متفرقة في السماء."], ["فترى الودق", "المطر يخرج من خلال السحاب."], ["إذا هم يستبشرون", "فرحون بالمطر النازل لسقياهم."], ["لمبلسين", "قانطين آيسين من إنزاله."], ["إن ذلك لمحيي الموتى", "القادر على إحياء الأرض بعد موتها قادر على إحياء الموتى."], ["فرأوه مصفرّاً", "رأوا الزرع مصفرّاً للجائحة التي أصابته."], ["لظلّوا من بعده يكفرون", "أقاموا بعد هلاك زروعهم يكفرون نعم الله."], ["إن تُسمع إلا من يؤمن بآياتنا", "ما تُسمع إلا المؤمنين."]], "m": "ما زال السياق في تقرير البعث بمظاهر القدرة: الله الذي يرسل الرياح فتثير سحاباً فيبسطه في السماء كيف يشاء، ويجعله قطعاً، فترى المطر يخرج من خلاله، فإذا أصاب به من يشاء من عباده إذا هم يفرحون، وإن كانوا من قبل نزوله لمكتئبين قانطين. فانظر إلى آثار رحمة الله كيف يحيي الأرض بعد موتها فتخضرّ بعد يبس، إن ذلك لمحيي الموتى يوم القيامة، وهو على كل شيء قدير. ولئن أرسلنا ريحاً محرقة فرأوا زرعهم مصفرّاً لظلّوا من بعده يكفرون بألفاظ السخط لجهلهم. فإنك لا تُسمع الموتى، لما ران على قلوبهم من الذنوب، ولا تُسمع الصمّ الدعاء إذا ولّوا مدبرين، وما أنت بهادي العمي عن ضلالتهم، فهوّن على نفسك، إن تُسمع سماع قبول إلا من يؤمن بآياتنا فهم منقادون.", "h": ["تقرير عقيدة البعث والجزاء بذكر الأدلة والحجج العقلية.", "بيان حال الكافر في الرخاء والشدة، فهو في الشدة يقنط وفي الرخاء يكفر، لفساد قلبه بالجهل بالله.", "الاستدلال بالمحسوس الحاضر على المحسوس الغيبي.", "بيان أن الكفار أموات، ولذا لا يسمعون ولا يبصرون، وأن المؤمنين أحياء."], "k": "«فانظر إلى آثار رحمة الله»… أين أرى أثر رحمته في يومي هذا؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (294, 30, 54, 60, 'سورة الروم ٥٤ – ٦٠', '«الله الذي خلقكم من ضعف ثم جعل من بعد ضعف قوة»، و«فاصبر إن وعد الله حق ولا يستخفّنّك الذين لا يوقنون»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 294) = $j$[{"lbl": "الآيات ٥٤ – ٥٧", "q": "۞ٱللَّهُ ٱلَّذِي خَلَقَكُم مِّن ضَعۡفٖ ثُمَّ جَعَلَ مِنۢ بَعۡدِ ضَعۡفٖ قُوَّةٗ ثُمَّ جَعَلَ مِنۢ بَعۡدِ قُوَّةٖ ضَعۡفٗا وَشَيۡبَةٗۚ يَخۡلُقُ مَا يَشَآءُۚ وَهُوَ ٱلۡعَلِيمُ ٱلۡقَدِيرُ ﴿٥٤﴾ وَيَوۡمَ تَقُومُ ٱلسَّاعَةُ يُقۡسِمُ ٱلۡمُجۡرِمُونَ مَا لَبِثُواْ غَيۡرَ سَاعَةٖۚ كَذَٰلِكَ كَانُواْ يُؤۡفَكُونَ ﴿٥٥﴾ وَقَالَ ٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ وَٱلۡإِيمَٰنَ لَقَدۡ لَبِثۡتُمۡ فِي كِتَٰبِ ٱللَّهِ إِلَىٰ يَوۡمِ ٱلۡبَعۡثِۖ فَهَٰذَا يَوۡمُ ٱلۡبَعۡثِ وَلَٰكِنَّكُمۡ كُنتُمۡ لَا تَعۡلَمُونَ ﴿٥٦﴾ فَيَوۡمَئِذٖ لَّا يَنفَعُ ٱلَّذِينَ ظَلَمُواْ مَعۡذِرَتُهُمۡ وَلَا هُمۡ يُسۡتَعۡتَبُونَ ﴿٥٧﴾", "w": [["خلقكم من ضعف", "من نطفة، وهي ماء مهين."], ["ثم جعل من بعد ضعف قوة", "من بعد ضعف الطفولة قوة الشباب."], ["ثم جعل من بعد قوة ضعفاً", "ضعف الكبر."], ["وشيبة", "الهرم."], ["كذلك كانوا يؤفكون", "كما صُرفوا عن معرفة مدة لبثهم صُرفوا في الدنيا عن الإيمان بالبعث."], ["لا ينفع الذين ظلموا معذرتهم", "في إنكارهم للبعث."], ["ولا هم يُستعتبون", "لا يُطلب منهم الرجوع إلى ما يرضي الله."]], "m": "ما زال السياق في تقرير البعث: الله وحده الذي خلقكم من نطفة ضعيفة، ثم جعل من بعد ضعف الطفولة قوة الشباب، ثم جعل من بعد قوة الشباب والكهولة ضعف الكبر والهرم، يخلق ما يشاء وهو العليم القدير، فالقادر على خلقهم من العدم قادر على بعثهم من الرمم. ويوم تقوم الساعة يحلف المجرمون ما لبثوا في قبورهم غير ساعة، كذلك كانوا يُصرفون في الدنيا عن الإيمان لظلمة نفوسهم. وقال الذين أوتوا العلم والإيمان: لقد لبثتم في كتاب المقادير إلى يوم البعث، فهذا يوم البعث ولكنكم كنتم لا تعلمون. فيومئذ لا ينفع الذين ظلموا معذرتهم، ولا يُطلب منهم الرجوع إلى ما يرضي الله.", "h": ["تقرير عقيدة البعث والجزاء بذكر الأدلة العقلية التي لا تُرد.", "بيان أطوار خلق الإنسان من نطفة إلى شيخوخة وهرم.", "فضل العلم والإيمان وأهلهما.", "بيان أن معذرة الظالمين لا تُقبل منهم يوم القيامة."], "k": "«ثم جعل من بعد قوة ضعفاً وشيبة»… قوّتي اليوم بين ضعفين؛ ففيم أنفقها؟"}, {"lbl": "الآيات ٥٨ – ٦٠", "q": "وَلَقَدۡ ضَرَبۡنَا لِلنَّاسِ فِي هَٰذَا ٱلۡقُرۡءَانِ مِن كُلِّ مَثَلٖۚ وَلَئِن جِئۡتَهُم بِـَٔايَةٖ لَّيَقُولَنَّ ٱلَّذِينَ كَفَرُوٓاْ إِنۡ أَنتُمۡ إِلَّا مُبۡطِلُونَ ﴿٥٨﴾ كَذَٰلِكَ يَطۡبَعُ ٱللَّهُ عَلَىٰ قُلُوبِ ٱلَّذِينَ لَا يَعۡلَمُونَ ﴿٥٩﴾ فَٱصۡبِرۡ إِنَّ وَعۡدَ ٱللَّهِ حَقّٞۖ وَلَا يَسۡتَخِفَّنَّكَ ٱلَّذِينَ لَا يُوقِنُونَ ﴿٦٠﴾", "w": [["ولقد ضربنا للناس", "جعلنا لهم."], ["من كل مثل", "من كل صفة مستغربة تلفت الانتباه وتحرك الضمير."], ["ولئن جئتهم بآية", "بكل حجة خارقة."], ["إن أنتم إلا مبطلون", "ما أنتم أيها الرسول والمؤمنون إلا من أهل الباطل في زعمهم."], ["الذين لا يعلمون", "ما أنزل الله على رسوله."], ["فاصبر إن وعد الله حق", "اصبر على أذاهم فإن العاقبة لك."], ["ولا يستخفّنّك الذين لا يوقنون", "لا يحملنّك المكذّبون على الخفة والطيش فتترك دعوتك."]], "m": "بعد إيراد الأدلة وعرض مشاهد القيامة قال تعالى: ولقد ضربنا للناس في هذا القرآن من كل أساليب الكلام وضروب التشبيه وعرض الأحداث بصور مثيرة موقظة للحس، لعلهم يتذكّرون فيؤمنوا، ولكنهم لم ينتفعوا، ولئن جئتهم بأية معجزة ليقولنّ الذين كفروا: ما أنتم إلا من أهل الباطل. كذلك يطبع الله على قلوب الذين لا يعلمون، إذ ظلمة الجهل كظلمة الشرك تحجب القلوب عن الفهم. فاصبر على دعوتك واثبت عليها حتى ينصرك الله، إن وعد الله حق لا يتخلّف، ولا يحملنّك عنادهم على الخفة والطيش وترك الحلم، فإن من لا يوقن بالله ولقائه يستفزّ الإنسان ويحمله على الخروج عن الأدب.", "h": ["إعذار الله تعالى إلى الناس بما ساقه في كتابه من أدلة الإيمان.", "أسوأ أحوال الإنسان عندما يُطبع على قلبه لكثرة ذنوبه فيصبح لا يفهم ولا يعقل.", "وجوب الصبر والتزام الحلم والأناة مهما جهل الجاهلون."], "k": "«ولا يستخفّنّك الذين لا يوقنون»… من يستفزّني فيُخرجني عن حلمي؟ وكيف أبقى ثابتاً؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 294;
insert into public.tdb_cards(topic, i, body) select 294, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٥٤ – ٥٧", "q": "۞ٱللَّهُ ٱلَّذِي خَلَقَكُم مِّن ضَعۡفٖ ثُمَّ جَعَلَ مِنۢ بَعۡدِ ضَعۡفٖ قُوَّةٗ ثُمَّ جَعَلَ مِنۢ بَعۡدِ قُوَّةٖ ضَعۡفٗا وَشَيۡبَةٗۚ يَخۡلُقُ مَا يَشَآءُۚ وَهُوَ ٱلۡعَلِيمُ ٱلۡقَدِيرُ ﴿٥٤﴾ وَيَوۡمَ تَقُومُ ٱلسَّاعَةُ يُقۡسِمُ ٱلۡمُجۡرِمُونَ مَا لَبِثُواْ غَيۡرَ سَاعَةٖۚ كَذَٰلِكَ كَانُواْ يُؤۡفَكُونَ ﴿٥٥﴾ وَقَالَ ٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ وَٱلۡإِيمَٰنَ لَقَدۡ لَبِثۡتُمۡ فِي كِتَٰبِ ٱللَّهِ إِلَىٰ يَوۡمِ ٱلۡبَعۡثِۖ فَهَٰذَا يَوۡمُ ٱلۡبَعۡثِ وَلَٰكِنَّكُمۡ كُنتُمۡ لَا تَعۡلَمُونَ ﴿٥٦﴾ فَيَوۡمَئِذٖ لَّا يَنفَعُ ٱلَّذِينَ ظَلَمُواْ مَعۡذِرَتُهُمۡ وَلَا هُمۡ يُسۡتَعۡتَبُونَ ﴿٥٧﴾", "w": [["خلقكم من ضعف", "من نطفة، وهي ماء مهين."], ["ثم جعل من بعد ضعف قوة", "من بعد ضعف الطفولة قوة الشباب."], ["ثم جعل من بعد قوة ضعفاً", "ضعف الكبر."], ["وشيبة", "الهرم."], ["كذلك كانوا يؤفكون", "كما صُرفوا عن معرفة مدة لبثهم صُرفوا في الدنيا عن الإيمان بالبعث."], ["لا ينفع الذين ظلموا معذرتهم", "في إنكارهم للبعث."], ["ولا هم يُستعتبون", "لا يُطلب منهم الرجوع إلى ما يرضي الله."]], "m": "ما زال السياق في تقرير البعث: الله وحده الذي خلقكم من نطفة ضعيفة، ثم جعل من بعد ضعف الطفولة قوة الشباب، ثم جعل من بعد قوة الشباب والكهولة ضعف الكبر والهرم، يخلق ما يشاء وهو العليم القدير، فالقادر على خلقهم من العدم قادر على بعثهم من الرمم. ويوم تقوم الساعة يحلف المجرمون ما لبثوا في قبورهم غير ساعة، كذلك كانوا يُصرفون في الدنيا عن الإيمان لظلمة نفوسهم. وقال الذين أوتوا العلم والإيمان: لقد لبثتم في كتاب المقادير إلى يوم البعث، فهذا يوم البعث ولكنكم كنتم لا تعلمون. فيومئذ لا ينفع الذين ظلموا معذرتهم، ولا يُطلب منهم الرجوع إلى ما يرضي الله.", "h": ["تقرير عقيدة البعث والجزاء بذكر الأدلة العقلية التي لا تُرد.", "بيان أطوار خلق الإنسان من نطفة إلى شيخوخة وهرم.", "فضل العلم والإيمان وأهلهما.", "بيان أن معذرة الظالمين لا تُقبل منهم يوم القيامة."], "k": "«ثم جعل من بعد قوة ضعفاً وشيبة»… قوّتي اليوم بين ضعفين؛ ففيم أنفقها؟"}, {"lbl": "الآيات ٥٨ – ٦٠", "q": "وَلَقَدۡ ضَرَبۡنَا لِلنَّاسِ فِي هَٰذَا ٱلۡقُرۡءَانِ مِن كُلِّ مَثَلٖۚ وَلَئِن جِئۡتَهُم بِـَٔايَةٖ لَّيَقُولَنَّ ٱلَّذِينَ كَفَرُوٓاْ إِنۡ أَنتُمۡ إِلَّا مُبۡطِلُونَ ﴿٥٨﴾ كَذَٰلِكَ يَطۡبَعُ ٱللَّهُ عَلَىٰ قُلُوبِ ٱلَّذِينَ لَا يَعۡلَمُونَ ﴿٥٩﴾ فَٱصۡبِرۡ إِنَّ وَعۡدَ ٱللَّهِ حَقّٞۖ وَلَا يَسۡتَخِفَّنَّكَ ٱلَّذِينَ لَا يُوقِنُونَ ﴿٦٠﴾", "w": [["ولقد ضربنا للناس", "جعلنا لهم."], ["من كل مثل", "من كل صفة مستغربة تلفت الانتباه وتحرك الضمير."], ["ولئن جئتهم بآية", "بكل حجة خارقة."], ["إن أنتم إلا مبطلون", "ما أنتم أيها الرسول والمؤمنون إلا من أهل الباطل في زعمهم."], ["الذين لا يعلمون", "ما أنزل الله على رسوله."], ["فاصبر إن وعد الله حق", "اصبر على أذاهم فإن العاقبة لك."], ["ولا يستخفّنّك الذين لا يوقنون", "لا يحملنّك المكذّبون على الخفة والطيش فتترك دعوتك."]], "m": "بعد إيراد الأدلة وعرض مشاهد القيامة قال تعالى: ولقد ضربنا للناس في هذا القرآن من كل أساليب الكلام وضروب التشبيه وعرض الأحداث بصور مثيرة موقظة للحس، لعلهم يتذكّرون فيؤمنوا، ولكنهم لم ينتفعوا، ولئن جئتهم بأية معجزة ليقولنّ الذين كفروا: ما أنتم إلا من أهل الباطل. كذلك يطبع الله على قلوب الذين لا يعلمون، إذ ظلمة الجهل كظلمة الشرك تحجب القلوب عن الفهم. فاصبر على دعوتك واثبت عليها حتى ينصرك الله، إن وعد الله حق لا يتخلّف، ولا يحملنّك عنادهم على الخفة والطيش وترك الحلم، فإن من لا يوقن بالله ولقائه يستفزّ الإنسان ويحمله على الخروج عن الأدب.", "h": ["إعذار الله تعالى إلى الناس بما ساقه في كتابه من أدلة الإيمان.", "أسوأ أحوال الإنسان عندما يُطبع على قلبه لكثرة ذنوبه فيصبح لا يفهم ولا يعقل.", "وجوب الصبر والتزام الحلم والأناة مهما جهل الجاهلون."], "k": "«ولا يستخفّنّك الذين لا يوقنون»… من يستفزّني فيُخرجني عن حلمي؟ وكيف أبقى ثابتاً؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (295, 31, 1, 11, 'سورة لقمان ١ – ١١', '«تلك آيات الكتاب الحكيم هدى ورحمة للمحسنين»، و«ومن الناس من يشتري لهو الحديث ليُضلّ عن سبيل الله»، و«هذا خلق الله فأروني ماذا خلق الذين من دونه»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 295) = $j$[{"lbl": "الآيات ١ – ٥", "q": "الٓمٓ ﴿١﴾ تِلۡكَ ءَايَٰتُ ٱلۡكِتَٰبِ ٱلۡحَكِيمِ ﴿٢﴾ هُدٗى وَرَحۡمَةٗ لِّلۡمُحۡسِنِينَ ﴿٣﴾ ٱلَّذِينَ يُقِيمُونَ ٱلصَّلَوٰةَ وَيُؤۡتُونَ ٱلزَّكَوٰةَ وَهُم بِٱلۡأٓخِرَةِ هُمۡ يُوقِنُونَ ﴿٤﴾ أُوْلَـٰٓئِكَ عَلَىٰ هُدٗى مِّن رَّبِّهِمۡۖ وَأُوْلَـٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ ﴿٥﴾", "w": [["الم", "تُكتب ألم وتُقرأ: ألف لام ميم."], ["تلك", "الآيات المؤلّفة من مثل هذه الحروف هي آيات الكتاب الحكيم."], ["الحكيم", "المحكم الذي لا نسخ يطرأ عليه بعد تمام نزوله ولا خلل فيه، والحكيم الذي يضع كل شيء في موضعه."], ["هدى ورحمة", "هدى يُهتدى به، ورحمة يُرحم بها."], ["للمحسنين", "الذين يراقبون الله في كل شؤونهم، إذ هم الذين يجدون الهدى والرحمة في القرآن."], ["أولئك على هدى من ربهم", "على هداية من الله فلا يضلّون."], ["المفلحون", "الفائزون بالنجاة من كل مرهوب، والظفر بكل مرغوب."]], "m": "الم، أحسن ما يُفسّر به: الله أعلم بمراده، وقد أفادت فائدتين: اضطرار المشركين إلى الإصغاء لنغمها ومدودها العجيبة وهم يتواصون بعدم السماع، وتحدّيهم بأن القرآن تألّف من مثلها فليؤلّفوا سورة مثله، فإن عجزوا فليسلّموا أنه كلام الله. تلك آيات القرآن الحكيم الذي يضع كل شيء موضعه، المحكم الذي لا نسخ يطرأ عليه بعد تمامه ولا تناقض بين أخباره وأحكامه، هدى ورحمة للمحسنين الذين أحسنوا عبادتهم فخلّصوها من الشرك والرياء وأدّوها على الوجه المرضي، الذين يقيمون الصلوات الخمس مستوفاة الشروط والأركان، ويؤتون زكاة أموالهم من ذهب وفضة وزروع وأنعام، وهم بالآخرة موقنون. أولئك على هدى من ربهم، وأولئك هم المفلحون الفائزون بالنجاة من النار ودخول الجنة.", "h": ["بيان إعجاز القرآن، حيث أُلّف من مثل «الم» و«ص» و«طس»، ولم يستطع خصومه أن يأتوا بسورة مثله.", "بيان معنى الحكيم وفضل الحكمة.", "بيان أن القرآن بيان للهدى المنجي المسعد، ورحمة لمن آمن به وعمل بما فيه.", "فضل الصلاة والزكاة واليقين.", "بيان مبنى الدين: وهو الإيمان والإسلام والإحسان."], "k": "«هدى ورحمة للمحسنين»… الهدى في القرآن لمن أحسن؛ فكيف أحسّن عبادتي لأنال نصيبي منه؟"}, {"lbl": "الآيات ٦ – ١١", "q": "وَمِنَ ٱلنَّاسِ مَن يَشۡتَرِي لَهۡوَ ٱلۡحَدِيثِ لِيُضِلَّ عَن سَبِيلِ ٱللَّهِ بِغَيۡرِ عِلۡمٖ وَيَتَّخِذَهَا هُزُوًاۚ أُوْلَـٰٓئِكَ لَهُمۡ عَذَابٞ مُّهِينٞ ﴿٦﴾ وَإِذَا تُتۡلَىٰ عَلَيۡهِ ءَايَٰتُنَا وَلَّىٰ مُسۡتَكۡبِرٗا كَأَن لَّمۡ يَسۡمَعۡهَا كَأَنَّ فِيٓ أُذُنَيۡهِ وَقۡرٗاۖ فَبَشِّرۡهُ بِعَذَابٍ أَلِيمٍ ﴿٧﴾ إِنَّ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ لَهُمۡ جَنَّـٰتُ ٱلنَّعِيمِ ﴿٨﴾ خَٰلِدِينَ فِيهَاۖ وَعۡدَ ٱللَّهِ حَقّٗاۚ وَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ ﴿٩﴾ خَلَقَ ٱلسَّمَٰوَٰتِ بِغَيۡرِ عَمَدٖ تَرَوۡنَهَاۖ وَأَلۡقَىٰ فِي ٱلۡأَرۡضِ رَوَٰسِيَ أَن تَمِيدَ بِكُمۡ وَبَثَّ فِيهَا مِن كُلِّ دَآبَّةٖۚ وَأَنزَلۡنَا مِنَ ٱلسَّمَآءِ مَآءٗ فَأَنۢبَتۡنَا فِيهَا مِن كُلِّ زَوۡجٖ كَرِيمٍ ﴿١٠﴾ هَٰذَا خَلۡقُ ٱللَّهِ فَأَرُونِي مَاذَا خَلَقَ ٱلَّذِينَ مِن دُونِهِۦۚ بَلِ ٱلظَّـٰلِمُونَ فِي ضَلَٰلٖ مُّبِينٖ ﴿١١﴾", "w": [["ومن الناس", "إنسان هو النضر بن الحارث حليف قريش."], ["لهو الحديث", "الحديث الملهي عن الخير والمعروف، وهو الغناء."], ["ليُضلّ عن سبيل الله", "ليصرف الناس عن الإسلام ويبعدهم عنه."], ["ويتّخذها هزواً", "يتخذ الإسلام وشرائعه وكتابه مهزوءاً به."], ["ولّى مستكبراً", "رجع في كبرياء ولم يستمع إليها."], ["في أذنيه وقراً", "ثقلاً يمنع من السماع كالصمم."], ["بغير عمد ترونها", "بدون عمد مرئية لكم ترفعها."], ["رواسي", "جبالاً راسية بها تثبت الأرض حتى لا تميل."], ["وبثّ فيها من كل دابة", "خلق ونشر فيها من صنوف الدواب."], ["من كل زوج كريم", "من كل صنف من النبات جميل نافع."]], "m": "لما ذكر المحسنين وبشّرهم بالفلاح ذكر صنفاً على النقيض: ومن الناس، كالنضر بن الحارث، من يشتري لهو الحديث، وهو الغناء، إذ كان يشتري الجواري المغنّيات ويفتح نادياً للهو ويدعو الناس إليه، ليصرفهم عن الإسلام فلا يجلسوا إلى النبي ولا يقرؤوا كتابه، بغير علم بعاقبة صنيعه، ويتّخذ سبيل الله هزواً، أولئك لهم عذاب مهين يُذلّهم يوم القيامة. وإذا تُتلى عليه آياتنا ولّى مستكبراً كأن لم يسمعها، كأن في أذنيه صمماً، فبشّره بعذاب أليم تهكّماً. إن الذين آمنوا وعملوا الصالحات لهم جنات النعيم خالدين فيها، وعد الله حقاً، وهو العزيز الحكيم. خلق السماوات بغير عمد مرئية، وفي هذا إشارة إلى عمد غير مرئية هي سنّة الجاذبية التي جعل بها الأجرام متماسكة، وألقى في الأرض جبالاً رواسي لتحفظ توازنها أن تميد بكم، وبثّ فيها من كل دابة، وأنزلنا من السماء ماءً فأنبتنا فيها من كل صنف كريم. هذا خلق الله، فأروني ماذا خلق الذين تعبدونهم من دونه؟ بل الظالمون في ضلال مبين، دواؤهم العلم والإيمان.", "h": ["حرمة غناء النساء للرجال الأجانب.", "حرمة شراء الأغاني الماجنة وما يُسجّل من غناء الفاجرات.", "حرمة حفلات الرقص والغناء الشائعة اليوم في العالم كافره ومسلمه.", "دعوة الله تقوم على دعامتي الترهيب والترغيب، والبشارة والنذارة.", "بيان مظاهر القدرة والعلم والعزة والحكمة الموجبة للإيمان والتوحيد.", "لا قصور في الأدلة والحجج الإلهية، وإنما ضلال العقول بالشرك والمعاصي يحجبها عن الاهتداء."], "k": "«ومن الناس من يشتري لهو الحديث»… ما الذي يملأ أذني ووقتي ويصرفني عن آيات الله؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 295;
