insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (296, 31, 12, 19, 'سورة لقمان ١٢ – ١٩', '«ولقد آتينا لقمان الحكمة أن اشكر لله»، و«يا بنيّ لا تشرك بالله إن الشرك لظلم عظيم»، و«يا بنيّ أقم الصلاة وأمر بالمعروف»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 296) = $j$[{"lbl": "الآيات ١٢ – ١٥", "q": "وَلَقَدۡ ءَاتَيۡنَا لُقۡمَٰنَ ٱلۡحِكۡمَةَ أَنِ ٱشۡكُرۡ لِلَّهِۚ وَمَن يَشۡكُرۡ فَإِنَّمَا يَشۡكُرُ لِنَفۡسِهِۦۖ وَمَن كَفَرَ فَإِنَّ ٱللَّهَ غَنِيٌّ حَمِيدٞ ﴿١٢﴾ وَإِذۡ قَالَ لُقۡمَٰنُ لِٱبۡنِهِۦ وَهُوَ يَعِظُهُۥ يَٰبُنَيَّ لَا تُشۡرِكۡ بِٱللَّهِۖ إِنَّ ٱلشِّرۡكَ لَظُلۡمٌ عَظِيمٞ ﴿١٣﴾ وَوَصَّيۡنَا ٱلۡإِنسَٰنَ بِوَٰلِدَيۡهِ حَمَلَتۡهُ أُمُّهُۥ وَهۡنًا عَلَىٰ وَهۡنٖ وَفِصَٰلُهُۥ فِي عَامَيۡنِ أَنِ ٱشۡكُرۡ لِي وَلِوَٰلِدَيۡكَ إِلَيَّ ٱلۡمَصِيرُ ﴿١٤﴾ وَإِن جَٰهَدَاكَ عَلَىٰٓ أَن تُشۡرِكَ بِي مَا لَيۡسَ لَكَ بِهِۦ عِلۡمٞ فَلَا تُطِعۡهُمَاۖ وَصَاحِبۡهُمَا فِي ٱلدُّنۡيَا مَعۡرُوفٗاۖ وَٱتَّبِعۡ سَبِيلَ مَنۡ أَنَابَ إِلَيَّۚ ثُمَّ إِلَيَّ مَرۡجِعُكُمۡ فَأُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ ﴿١٥﴾", "w": [["ولقد آتينا لقمان الحكمة", "أعطينا لقمان القاضي الفقه في الدين والإصابة في الأمور."], ["أن اشكر لله", "اشكر لله ما أنعم به عليك بطاعته وذكره."], ["لابنه وهو يعظه", "ابنه، وهو يأمره وينهاه مرغّباً مرهّباً."], ["ووصّينا الإنسان", "عهدنا إليه ببرّ والديه: كفّ الأذى عنهما والإحسان إليهما وطاعتهما في المعروف."], ["وهناً على وهن", "ضعفاً على ضعف، وشدة على شدة، وهي الحمل والولادة والإرضاع."], ["وفصاله في عامين", "مدة رضاعه تنتهي في عامين."], ["وإن جاهداك", "بذلا جهدهما في حملك على الشرك."], ["وصاحبهما في الدنيا معروفاً", "اصحبهما في حياتهما بالمعروف، وهو البرّ والصلة والطاعة في غير معصية."], ["من أناب إليّ", "رجع إليّ بتوحيدي وطاعتي وطاعة رسولي."]], "m": "ما زال السياق في تقرير التوحيد: ولقد آتينا لقمان الحكمة، وهي الفقه في الدين والإصابة في الأمور، ورأسها مخافة الله، وقلنا له: اشكر لله ما أنعم به عليك بصرف نعمه فيما يرضيه، ومن يشكر فإنما ثمرة شكره له بحفظ النعمة وزيادتها، ومن كفر فإن الله غني حميد. واذكر للمشركين قول لقمان لابنه وأخصّ الناس به، ينهاه عن الذي نهيتكم عنه: يا بنيّ لا تشرك بالله، إن الشرك لظلم عظيم، إذ الظلم وضع الشيء في غير موضعه، وعبادة غير الله وضع لها في غير موضعها. ووصّينا الإنسان بوالديه، حملته أمه ضعفاً على ضعف في الحمل والطلق والولادة والإرضاع، ولذا أُكّد برّها فوق برّ الأب، وفي الصحيح: «أمك، ثم أمك، ثم أمك، ثم أبوك»، وفطامه في عامين: أن اشكر لي بطاعتي، ولوالديك ببرّهما وصلتهما، إليّ المصير. وإن جاهداك على أن تشرك بي ما ليس لك به علم فلا تطعهما، وصاحبهما في الدنيا بالمعروف، واتّبع سبيل من رجع إليّ بالتوحيد والطاعة، وقد نزلت في سعد بن أبي وقاص وأمه، ثم إليّ مرجعكم فأنبّئكم بما كنتم تعملون.", "h": ["تقرير التوحيد والتنديد بالشرك.", "بيان الحكمة، وهي شكر الله تعالى بطاعته وذكره، إذ لا يشكر إلا عاقل فقيه.", "مشروعية الوعظ والإرشاد للكبير والصغير والقريب والبعيد.", "التهويل في شأن الشرك، وأنه لظلم عظيم.", "بيان مدة الرضاع، وهي في خلال العامين لا تزيد.", "وجوب برّ الوالدين وصلتهما.", "تقرير مبدأ: لا طاعة لمخلوق في معصية الخالق.", "وجوب اتّباع سبيل المؤمنين من أهل السنّة والجماعة."], "k": "«وصاحبهما في الدنيا معروفاً»… حتى مع الخلاف في أعظم المسائل يبقى المعروف؛ فكيف صحبتي لوالديّ؟"}, {"lbl": "الآيات ١٦ – ١٩", "q": "يَٰبُنَيَّ إِنَّهَآ إِن تَكُ مِثۡقَالَ حَبَّةٖ مِّنۡ خَرۡدَلٖ فَتَكُن فِي صَخۡرَةٍ أَوۡ فِي ٱلسَّمَٰوَٰتِ أَوۡ فِي ٱلۡأَرۡضِ يَأۡتِ بِهَا ٱللَّهُۚ إِنَّ ٱللَّهَ لَطِيفٌ خَبِيرٞ ﴿١٦﴾ يَٰبُنَيَّ أَقِمِ ٱلصَّلَوٰةَ وَأۡمُرۡ بِٱلۡمَعۡرُوفِ وَٱنۡهَ عَنِ ٱلۡمُنكَرِ وَٱصۡبِرۡ عَلَىٰ مَآ أَصَابَكَۖ إِنَّ ذَٰلِكَ مِنۡ عَزۡمِ ٱلۡأُمُورِ ﴿١٧﴾ وَلَا تُصَعِّرۡ خَدَّكَ لِلنَّاسِ وَلَا تَمۡشِ فِي ٱلۡأَرۡضِ مَرَحًاۖ إِنَّ ٱللَّهَ لَا يُحِبُّ كُلَّ مُخۡتَالٖ فَخُورٖ ﴿١٨﴾ وَٱقۡصِدۡ فِي مَشۡيِكَ وَٱغۡضُضۡ مِن صَوۡتِكَۚ إِنَّ أَنكَرَ ٱلۡأَصۡوَٰتِ لَصَوۡتُ ٱلۡحَمِيرِ ﴿١٩﴾", "w": [["إنها إن تك مثقال حبة", "إن توجد زنة حبة من خردل."], ["فتكن في صخرة", "في داخل صخرة لا يعلمها أحد."], ["لطيف خبير", "لطيف باستخراجها، خبير بموضعها."], ["وأمر بالمعروف وانهَ عن المنكر", "مُر الناس بطاعة الله وانههم عن معصيته."], ["من عزم الأمور", "مما أمر الله به عزماً لا رخصة فيه."], ["ولا تصعّر خدك للناس", "لا تُعرض بوجهك عمن تكلّمه تكبّراً."], ["مرحاً", "مختالاً تمشي خيلاء."], ["مختال فخور", "متبختر كثير الفخر بما أعطاه الله ولا يشكر."], ["واقصد في مشيك", "توسّط، فلا تعجل ولا تستكبر."], ["واغضض من صوتك", "اخفضه، وهو الاقتصاد في الصوت."], ["إن أنكر الأصوات", "أقبحها وأشدّها نكارة."]], "m": "ما زال السياق في وصايا لقمان لابنه: يا بنيّ إن الحسنة أو السيئة إن تكن زنة حبة من خردل فتكن في صخرة أو في السماوات أو في الأرض يأت بها الله ويحاسب عليها، إن الله لطيف باستخراجها خبير بموضعها، فاعمل الصالحات واجتنب السيئات. يا بنيّ أقم الصلاة بشروطها وأركانها، وأمر بطاعة الله، وانهَ عما حرّم من اعتقاد أو قول أو عمل، واصبر على ما أصابك من أذى في ذلك، إن ذلك من الأمور الواجبة التي لا رخصة فيها. ولا تُعرض بوجهك عن الناس تكبّراً، ولا تمش في الأرض مختالاً متبختراً، إن الله لا يحب كل مختال فخور. وتوسّط في مشيك فلا تسرع، واخفض من صوتك فلا ترفعه إلا بقدر الحاجة، كالمقتصد لا يُخرج درهمه إلا لحاجة، إن أقبح الأصوات لصوت الحمير لعلوّه، وأوله زفير وآخره شهيق.", "h": ["وجوب مراقبة الله تعالى، وعدم الاستخفاف بالحسنة والسيئة مهما قلّت وصغرت.", "وجوب إقام الصلاة، والأمر بالمعروف والنهي عن المنكر، والصبر على ما يلحق الآمر والناهي من أذى.", "حرمة التكبّر والاختيال في المشي، ووجوب القصد في المشي والصوت، فلا يرفع صوته إلا على قدر الحاجة."], "k": "«إنها إن تك مثقال حبة من خردل»… لا شيء يضيع؛ فما الحبّة الصغيرة من الخير التي أزرعها اليوم؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 296;
insert into public.tdb_cards(topic, i, body) select 296, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١٢ – ١٥", "q": "وَلَقَدۡ ءَاتَيۡنَا لُقۡمَٰنَ ٱلۡحِكۡمَةَ أَنِ ٱشۡكُرۡ لِلَّهِۚ وَمَن يَشۡكُرۡ فَإِنَّمَا يَشۡكُرُ لِنَفۡسِهِۦۖ وَمَن كَفَرَ فَإِنَّ ٱللَّهَ غَنِيٌّ حَمِيدٞ ﴿١٢﴾ وَإِذۡ قَالَ لُقۡمَٰنُ لِٱبۡنِهِۦ وَهُوَ يَعِظُهُۥ يَٰبُنَيَّ لَا تُشۡرِكۡ بِٱللَّهِۖ إِنَّ ٱلشِّرۡكَ لَظُلۡمٌ عَظِيمٞ ﴿١٣﴾ وَوَصَّيۡنَا ٱلۡإِنسَٰنَ بِوَٰلِدَيۡهِ حَمَلَتۡهُ أُمُّهُۥ وَهۡنًا عَلَىٰ وَهۡنٖ وَفِصَٰلُهُۥ فِي عَامَيۡنِ أَنِ ٱشۡكُرۡ لِي وَلِوَٰلِدَيۡكَ إِلَيَّ ٱلۡمَصِيرُ ﴿١٤﴾ وَإِن جَٰهَدَاكَ عَلَىٰٓ أَن تُشۡرِكَ بِي مَا لَيۡسَ لَكَ بِهِۦ عِلۡمٞ فَلَا تُطِعۡهُمَاۖ وَصَاحِبۡهُمَا فِي ٱلدُّنۡيَا مَعۡرُوفٗاۖ وَٱتَّبِعۡ سَبِيلَ مَنۡ أَنَابَ إِلَيَّۚ ثُمَّ إِلَيَّ مَرۡجِعُكُمۡ فَأُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ ﴿١٥﴾", "w": [["ولقد آتينا لقمان الحكمة", "أعطينا لقمان القاضي الفقه في الدين والإصابة في الأمور."], ["أن اشكر لله", "اشكر لله ما أنعم به عليك بطاعته وذكره."], ["لابنه وهو يعظه", "ابنه، وهو يأمره وينهاه مرغّباً مرهّباً."], ["ووصّينا الإنسان", "عهدنا إليه ببرّ والديه: كفّ الأذى عنهما والإحسان إليهما وطاعتهما في المعروف."], ["وهناً على وهن", "ضعفاً على ضعف، وشدة على شدة، وهي الحمل والولادة والإرضاع."], ["وفصاله في عامين", "مدة رضاعه تنتهي في عامين."], ["وإن جاهداك", "بذلا جهدهما في حملك على الشرك."], ["وصاحبهما في الدنيا معروفاً", "اصحبهما في حياتهما بالمعروف، وهو البرّ والصلة والطاعة في غير معصية."], ["من أناب إليّ", "رجع إليّ بتوحيدي وطاعتي وطاعة رسولي."]], "m": "ما زال السياق في تقرير التوحيد: ولقد آتينا لقمان الحكمة، وهي الفقه في الدين والإصابة في الأمور، ورأسها مخافة الله، وقلنا له: اشكر لله ما أنعم به عليك بصرف نعمه فيما يرضيه، ومن يشكر فإنما ثمرة شكره له بحفظ النعمة وزيادتها، ومن كفر فإن الله غني حميد. واذكر للمشركين قول لقمان لابنه وأخصّ الناس به، ينهاه عن الذي نهيتكم عنه: يا بنيّ لا تشرك بالله، إن الشرك لظلم عظيم، إذ الظلم وضع الشيء في غير موضعه، وعبادة غير الله وضع لها في غير موضعها. ووصّينا الإنسان بوالديه، حملته أمه ضعفاً على ضعف في الحمل والطلق والولادة والإرضاع، ولذا أُكّد برّها فوق برّ الأب، وفي الصحيح: «أمك، ثم أمك، ثم أمك، ثم أبوك»، وفطامه في عامين: أن اشكر لي بطاعتي، ولوالديك ببرّهما وصلتهما، إليّ المصير. وإن جاهداك على أن تشرك بي ما ليس لك به علم فلا تطعهما، وصاحبهما في الدنيا بالمعروف، واتّبع سبيل من رجع إليّ بالتوحيد والطاعة، وقد نزلت في سعد بن أبي وقاص وأمه، ثم إليّ مرجعكم فأنبّئكم بما كنتم تعملون.", "h": ["تقرير التوحيد والتنديد بالشرك.", "بيان الحكمة، وهي شكر الله تعالى بطاعته وذكره، إذ لا يشكر إلا عاقل فقيه.", "مشروعية الوعظ والإرشاد للكبير والصغير والقريب والبعيد.", "التهويل في شأن الشرك، وأنه لظلم عظيم.", "بيان مدة الرضاع، وهي في خلال العامين لا تزيد.", "وجوب برّ الوالدين وصلتهما.", "تقرير مبدأ: لا طاعة لمخلوق في معصية الخالق.", "وجوب اتّباع سبيل المؤمنين من أهل السنّة والجماعة."], "k": "«وصاحبهما في الدنيا معروفاً»… حتى مع الخلاف في أعظم المسائل يبقى المعروف؛ فكيف صحبتي لوالديّ؟"}, {"lbl": "الآيات ١٦ – ١٩", "q": "يَٰبُنَيَّ إِنَّهَآ إِن تَكُ مِثۡقَالَ حَبَّةٖ مِّنۡ خَرۡدَلٖ فَتَكُن فِي صَخۡرَةٍ أَوۡ فِي ٱلسَّمَٰوَٰتِ أَوۡ فِي ٱلۡأَرۡضِ يَأۡتِ بِهَا ٱللَّهُۚ إِنَّ ٱللَّهَ لَطِيفٌ خَبِيرٞ ﴿١٦﴾ يَٰبُنَيَّ أَقِمِ ٱلصَّلَوٰةَ وَأۡمُرۡ بِٱلۡمَعۡرُوفِ وَٱنۡهَ عَنِ ٱلۡمُنكَرِ وَٱصۡبِرۡ عَلَىٰ مَآ أَصَابَكَۖ إِنَّ ذَٰلِكَ مِنۡ عَزۡمِ ٱلۡأُمُورِ ﴿١٧﴾ وَلَا تُصَعِّرۡ خَدَّكَ لِلنَّاسِ وَلَا تَمۡشِ فِي ٱلۡأَرۡضِ مَرَحًاۖ إِنَّ ٱللَّهَ لَا يُحِبُّ كُلَّ مُخۡتَالٖ فَخُورٖ ﴿١٨﴾ وَٱقۡصِدۡ فِي مَشۡيِكَ وَٱغۡضُضۡ مِن صَوۡتِكَۚ إِنَّ أَنكَرَ ٱلۡأَصۡوَٰتِ لَصَوۡتُ ٱلۡحَمِيرِ ﴿١٩﴾", "w": [["إنها إن تك مثقال حبة", "إن توجد زنة حبة من خردل."], ["فتكن في صخرة", "في داخل صخرة لا يعلمها أحد."], ["لطيف خبير", "لطيف باستخراجها، خبير بموضعها."], ["وأمر بالمعروف وانهَ عن المنكر", "مُر الناس بطاعة الله وانههم عن معصيته."], ["من عزم الأمور", "مما أمر الله به عزماً لا رخصة فيه."], ["ولا تصعّر خدك للناس", "لا تُعرض بوجهك عمن تكلّمه تكبّراً."], ["مرحاً", "مختالاً تمشي خيلاء."], ["مختال فخور", "متبختر كثير الفخر بما أعطاه الله ولا يشكر."], ["واقصد في مشيك", "توسّط، فلا تعجل ولا تستكبر."], ["واغضض من صوتك", "اخفضه، وهو الاقتصاد في الصوت."], ["إن أنكر الأصوات", "أقبحها وأشدّها نكارة."]], "m": "ما زال السياق في وصايا لقمان لابنه: يا بنيّ إن الحسنة أو السيئة إن تكن زنة حبة من خردل فتكن في صخرة أو في السماوات أو في الأرض يأت بها الله ويحاسب عليها، إن الله لطيف باستخراجها خبير بموضعها، فاعمل الصالحات واجتنب السيئات. يا بنيّ أقم الصلاة بشروطها وأركانها، وأمر بطاعة الله، وانهَ عما حرّم من اعتقاد أو قول أو عمل، واصبر على ما أصابك من أذى في ذلك، إن ذلك من الأمور الواجبة التي لا رخصة فيها. ولا تُعرض بوجهك عن الناس تكبّراً، ولا تمش في الأرض مختالاً متبختراً، إن الله لا يحب كل مختال فخور. وتوسّط في مشيك فلا تسرع، واخفض من صوتك فلا ترفعه إلا بقدر الحاجة، كالمقتصد لا يُخرج درهمه إلا لحاجة، إن أقبح الأصوات لصوت الحمير لعلوّه، وأوله زفير وآخره شهيق.", "h": ["وجوب مراقبة الله تعالى، وعدم الاستخفاف بالحسنة والسيئة مهما قلّت وصغرت.", "وجوب إقام الصلاة، والأمر بالمعروف والنهي عن المنكر، والصبر على ما يلحق الآمر والناهي من أذى.", "حرمة التكبّر والاختيال في المشي، ووجوب القصد في المشي والصوت، فلا يرفع صوته إلا على قدر الحاجة."], "k": "«إنها إن تك مثقال حبة من خردل»… لا شيء يضيع؛ فما الحبّة الصغيرة من الخير التي أزرعها اليوم؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (297, 31, 20, 34, 'سورة لقمان ٢٠ – ٣٤', '«وأسبغ عليكم نعمه ظاهرة وباطنة»، و«ومن يُسلم وجهه إلى الله وهو محسن فقد استمسك بالعروة الوثقى»، و«إن الله عنده علم الساعة»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 297) = $j$[{"lbl": "الآيتان ٢٠ – ٢١", "q": "أَلَمۡ تَرَوۡاْ أَنَّ ٱللَّهَ سَخَّرَ لَكُم مَّا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِ وَأَسۡبَغَ عَلَيۡكُمۡ نِعَمَهُۥ ظَٰهِرَةٗ وَبَاطِنَةٗۗ وَمِنَ ٱلنَّاسِ مَن يُجَٰدِلُ فِي ٱللَّهِ بِغَيۡرِ عِلۡمٖ وَلَا هُدٗى وَلَا كِتَٰبٖ مُّنِيرٖ ﴿٢٠﴾ وَإِذَا قِيلَ لَهُمُ ٱتَّبِعُواْ مَآ أَنزَلَ ٱللَّهُ قَالُواْ بَلۡ نَتَّبِعُ مَا وَجَدۡنَا عَلَيۡهِ ءَابَآءَنَآۚ أَوَلَوۡ كَانَ ٱلشَّيۡطَٰنُ يَدۡعُوهُمۡ إِلَىٰ عَذَابِ ٱلسَّعِيرِ ﴿٢١﴾", "w": [["ألم تروا", "ألم تعلموا أيها الناس."], ["سخّر لكم ما في السماوات", "من شمس وقمر وكواكب ورياح وأمطار لمنافعكم."], ["وما في الأرض", "من أشجار وأنهار وجبال وبحار."], ["وأسبغ عليكم نعمه ظاهرة", "أوسعها وأتمّها، كالصحة وكمال الخلق."], ["وباطنة", "كالعقل والمعرفة."], ["من يجادل في الله", "يخاصم في توحيده منكراً له."], ["بغير علم", "بلا وحي ولا دليل عقلي."], ["ولا هدى ولا كتاب منير", "لا سنّة من سنن الرسل، ولا كتاب إلهي واضح."], ["أوَلو كان الشيطان يدعوهم", "أيتّبعونهم ولو كان الشيطان يدعو آباءهم إلى موجبات عذاب السعير؟"]], "m": "عاد السياق بعد قصة لقمان إلى خطاب المشركين: ألم تعلموا أن الله سخّر لكم ما في السماوات من شمس وقمر ومطر، وما في الأرض من أشجار وأنهار وبحار وحيوان لمنافعكم، وأوسع عليكم نعمه ظاهرة كحسن الصورة وكمال الخلق، وباطنة كالعقل والعلم، مما لا يُحصى؟ ومع هذا من الناس من يجادل في توحيد الله وأسمائه وطاعته بغير علم من وحي ولا دليل عقل ولا كتاب منير. وإذا قيل لهم: اتّبعوا ما أنزل الله، قالوا: بل نتّبع ما وجدنا عليه آباءنا من عقائد وثنية وتقاليد جاهلية، أيتّبعونهم ولو كان الشيطان يدعو آباءهم إلى عذاب النار؟", "h": ["تعيين الاستدلال بالخلق على الخالق، وبالنعمة على المنعم.", "وجوب ذكر النعم وشكرها لله تعالى بطاعته وطاعة رسوله ﷺ.", "حرمة الجدال بالجهل ودون علم.", "حرمة التقليد في الباطل والشر والفساد، كتقليد بعض المسلمين اليوم الكفارَ في عاداتهم وأخلاقهم."], "k": "«وأسبغ عليكم نعمه ظاهرة وباطنة»… أعدّ نعمة باطنة واحدة لم أشكرها قط."}, {"lbl": "الآيات ٢٢ – ٢٦", "q": "۞وَمَن يُسۡلِمۡ وَجۡهَهُۥٓ إِلَى ٱللَّهِ وَهُوَ مُحۡسِنٞ فَقَدِ ٱسۡتَمۡسَكَ بِٱلۡعُرۡوَةِ ٱلۡوُثۡقَىٰۗ وَإِلَى ٱللَّهِ عَٰقِبَةُ ٱلۡأُمُورِ ﴿٢٢﴾ وَمَن كَفَرَ فَلَا يَحۡزُنكَ كُفۡرُهُۥٓۚ إِلَيۡنَا مَرۡجِعُهُمۡ فَنُنَبِّئُهُم بِمَا عَمِلُوٓاْۚ إِنَّ ٱللَّهَ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ ﴿٢٣﴾ نُمَتِّعُهُمۡ قَلِيلٗا ثُمَّ نَضۡطَرُّهُمۡ إِلَىٰ عَذَابٍ غَلِيظٖ ﴿٢٤﴾ وَلَئِن سَأَلۡتَهُم مَّنۡ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ لَيَقُولُنَّ ٱللَّهُۚ قُلِ ٱلۡحَمۡدُ لِلَّهِۚ بَلۡ أَكۡثَرُهُمۡ لَا يَعۡلَمُونَ ﴿٢٥﴾ لِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ إِنَّ ٱللَّهَ هُوَ ٱلۡغَنِيُّ ٱلۡحَمِيدُ ﴿٢٦﴾", "w": [["ومن يُسلم وجهه إلى الله", "أقبل على طاعته مخلصاً له العبادة."], ["وهو محسن", "محسن في طاعته إخلاصاً واتّباعاً."], ["فقد استمسك بالعروة الوثقى", "تعلّق بأوثق ما يُتعلّق به فلا يخاف انقطاعاً."], ["وإلى الله عاقبة الأمور", "مرجع كل الأمور إليه."], ["نمتّعهم قليلاً", "متاعاً في الدنيا إلى نهاية آجالهم."], ["ثم نضطرّهم إلى عذاب غليظ", "نُلجئهم في الآخرة إلى عذاب النار."], ["قل الحمد لله", "احمد الله على ظهور الحجة."], ["لا يعلمون", "من يستحق الحمد ومن لا يستحقه."]], "m": "بعد إقامة الحجة على المشركين قال مرغّباً في النجاة: ومن يُقبل بوجهه وقلبه على ربه يعبده متذلّلاً، وهو محسن في عبادته إخلاصاً لله واتّباعاً لرسوله، فقد استمسك بالطرف الأوثق فلا يخاف انقطاعاً، وإلى الله عاقبة الأمور، فليفوّض العبد أموره إليه. ومن كفر فلا يحزنك كفره، إلينا مرجعهم فننبّئهم بما عملوا ونجزيهم، إن الله عليم بما تُكنّه الصدور. نمهلهم فيتمتّعون قليلاً، ثم نُلجئهم بعد موتهم إلى عذاب غليظ لا يُطاق. ولئن سألتهم: من خلق السماوات والأرض؟ ليقولنّ: الله، قل: الحمد لله على إقامة الحجة عليكم باعترافكم، فكيف يُعبد غيره؟ بل أكثرهم لا يعلمون. لله ما في السماوات والأرض خلقاً وملكاً، فهو غني عن المشركين وعبادتهم، الحميد في فعله وصنعه.", "h": ["بيان نجاة أهل «لا إله إلا الله»، وهم الذين عبدوا الله وحده بما شرع لهم.", "تقرير عقيدة البعث والجزاء.", "بيان أن المشركين من العرب موحّدون في الربوبية مشركون في العبادة، ومثلهم كثير من الناس اليوم يعتقدون أن الله رب كل شيء، ويذبحون وينذرون ويحلفون بغيره ويخافون غيره."], "k": "«فقد استمسك بالعروة الوثقى»… بماذا أتمسّك حين تهتزّ الأمور من حولي؟"}, {"lbl": "الآيتان ٢٧ – ٢٨", "q": "وَلَوۡ أَنَّمَا فِي ٱلۡأَرۡضِ مِن شَجَرَةٍ أَقۡلَٰمٞ وَٱلۡبَحۡرُ يَمُدُّهُۥ مِنۢ بَعۡدِهِۦ سَبۡعَةُ أَبۡحُرٖ مَّا نَفِدَتۡ كَلِمَٰتُ ٱللَّهِۚ إِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٞ ﴿٢٧﴾ مَّا خَلۡقُكُمۡ وَلَا بَعۡثُكُمۡ إِلَّا كَنَفۡسٖ وَٰحِدَةٍۚ إِنَّ ٱللَّهَ سَمِيعُۢ بَصِيرٌ ﴿٢٨﴾", "w": [["ولو أن ما في الأرض", "من شجرة."], ["أقلام", "يُكتب بها."], ["والبحر", "المحيط."], ["يمدّه", "تمدّه سبعة أبحر أخرى مداداً."], ["إن الله عزيز حكيم", "غالب على ما أراد، حكيم في تدبيره."], ["ما خلقكم ولا بعثكم", "ما خلقكم ابتداءً ولا بعثكم إعادةً إلا كخلق وبعث نفس واحدة."]], "m": "لو أن شجر الأرض كله بُري أقلاماً، والبحر المحيط صار مداداً، ومن ورائه سبعة أبحر أخرى تمدّه، فكُتبت بها كلمات الله، لنفد البحر والأقلام ولم تنفد كلمات الله، لأنها غير متناهية، فعلمه وكلامه كذاته وصفاته لا نهاية لها، ونزلت رداً على اليهود لما قالوا: أوتينا التوراة فيها تبيان كل شيء. ونزلت «ما خلقكم ولا بعثكم إلا كنفس واحدة» رداً على أُبيّ بن خلف لما استبعد أن يُعاد الخلق في يوم واحد، فالله كما يسمع أصوات المخلوقات كلها لا يشغله صوت عن صوت، ويبصرهم لا تحجبه ذات عن ذات، كذلك يخلقهم ويبعثهم في وقت واحد، إذ يقول للشيء كن فيكون.", "h": ["بيان سعة علم الله تعالى، وأنه متكلّم وكلماته لا تنفد بحال.", "بيان أن ما أوتيه الإنسان من علوم ومعارف ليس بشيء إلى علم الله تعالى.", "بيان قدرة الله تعالى، وأنها لا تُحدّ ولا يعجزها شيء.", "إثبات صفات الله كالعزة والحكمة والسمع والبصر."], "k": "«ما نفدت كلمات الله»… كم مما أعرفه يكفي لأتواضع أمام ما لا أعرفه؟"}, {"lbl": "الآيات ٢٩ – ٣٢", "q": "أَلَمۡ تَرَ أَنَّ ٱللَّهَ يُولِجُ ٱلَّيۡلَ فِي ٱلنَّهَارِ وَيُولِجُ ٱلنَّهَارَ فِي ٱلَّيۡلِ وَسَخَّرَ ٱلشَّمۡسَ وَٱلۡقَمَرَۖ كُلّٞ يَجۡرِيٓ إِلَىٰٓ أَجَلٖ مُّسَمّٗى وَأَنَّ ٱللَّهَ بِمَا تَعۡمَلُونَ خَبِيرٞ ﴿٢٩﴾ ذَٰلِكَ بِأَنَّ ٱللَّهَ هُوَ ٱلۡحَقُّ وَأَنَّ مَا يَدۡعُونَ مِن دُونِهِ ٱلۡبَٰطِلُ وَأَنَّ ٱللَّهَ هُوَ ٱلۡعَلِيُّ ٱلۡكَبِيرُ ﴿٣٠﴾ أَلَمۡ تَرَ أَنَّ ٱلۡفُلۡكَ تَجۡرِي فِي ٱلۡبَحۡرِ بِنِعۡمَتِ ٱللَّهِ لِيُرِيَكُم مِّنۡ ءَايَٰتِهِۦٓۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّكُلِّ صَبَّارٖ شَكُورٖ ﴿٣١﴾ وَإِذَا غَشِيَهُم مَّوۡجٞ كَٱلظُّلَلِ دَعَوُاْ ٱللَّهَ مُخۡلِصِينَ لَهُ ٱلدِّينَ فَلَمَّا نَجَّىٰهُمۡ إِلَى ٱلۡبَرِّ فَمِنۡهُم مُّقۡتَصِدٞۚ وَمَا يَجۡحَدُ بِـَٔايَٰتِنَآ إِلَّا كُلُّ خَتَّارٖ كَفُورٖ ﴿٣٢﴾", "w": [["ألم تر", "ألم تعلم أيها المخاطب."], ["يولج الليل في النهار", "يُدخل جزءاً من كلٍّ منهما في الآخر بحسب الفصول."], ["وسخّر الشمس والقمر", "يسبحان في فلكيهما إلى يوم القيامة، وهو الأجل المسمّى."], ["ذلك بأن الله هو الحق", "ذلك المذكور بسبب أن الله هو الإله الحق."], ["بنعمة الله", "بإفضاله على العباد إذ هيّأ أسباب جريها."], ["لكل صبّار شكور", "صبّار عن المعاصي، شكور للنعم."], ["وإذا غشيهم موج كالظلل", "علاهم وغطّاهم كالجبال التي تظلّل من تحتها."], ["فمنهم مقتصد", "معتدل بين الكفر والإيمان."], ["ختّار", "غدّار بالعهود، كفور لنعم الله."]], "m": "ما زال السياق في تقرير التوحيد: ألم تر أن الله يُدخل جزءاً من الليل في النهار ومن النهار في الليل بحسب الفصول، وسخّر الشمس والقمر يجريان لمنافع الناس إلى يوم القيامة، وأن الله بما تعملون خبير فيجزيكم؟ ذلك قاطع بأن الله هو الحق، وأن ما يدعون من دونه الباطل، وأن الله هو العلي الكبير. ألم تر أن السفن تجري في البحر بنعمة الله، تحمل السلع والأقوات من إقليم إلى إقليم، ليريكم من آياته؟ إن في ذلك لعبراً لكل صبور على الطاعات وعن المعاصي وعلى الأقدار، شكور لنعم الله. وإذا غشي المشركين وهم في السفينة موج كالجبال دعوا الله مخلصين له الدعاء، فلما نجّاهم إلى البر فمنهم معتدل لا يغلو في كفره ولا يعلن إيمانه، وما يجحد بآياتنا إلا كل غدّار كفور لا خير فيه.", "h": ["تقرير التوحيد وإبطال الشرك بذكر الأدلة المستفادة من مظاهر قدرة الله.", "فضيلة الصبر والشكر، والجمع بينهما خير من افتراقهما.", "بيان أن المشركين أيام نزول القرآن كانوا يوحّدون في الشدة ويشركون في الرخاء.", "شر الناس الختّار، أي الغدّار الكفور."], "k": "«لكل صبّار شكور»… هل أنا صبور في البلاء وشكور في النعمة، أم أنسى الأولى وأجحد الثانية؟"}, {"lbl": "الآيتان ٣٣ – ٣٤", "q": "يَـٰٓأَيُّهَا ٱلنَّاسُ ٱتَّقُواْ رَبَّكُمۡ وَٱخۡشَوۡاْ يَوۡمٗا لَّا يَجۡزِي وَالِدٌ عَن وَلَدِهِۦ وَلَا مَوۡلُودٌ هُوَ جَازٍ عَن وَالِدِهِۦ شَيۡـًٔاۚ إِنَّ وَعۡدَ ٱللَّهِ حَقّٞۖ فَلَا تَغُرَّنَّكُمُ ٱلۡحَيَوٰةُ ٱلدُّنۡيَا وَلَا يَغُرَّنَّكُم بِٱللَّهِ ٱلۡغَرُورُ ﴿٣٣﴾ إِنَّ ٱللَّهَ عِندَهُۥ عِلۡمُ ٱلسَّاعَةِ وَيُنَزِّلُ ٱلۡغَيۡثَ وَيَعۡلَمُ مَا فِي ٱلۡأَرۡحَامِۖ وَمَا تَدۡرِي نَفۡسٞ مَّاذَا تَكۡسِبُ غَدٗاۖ وَمَا تَدۡرِي نَفۡسُۢ بِأَيِّ أَرۡضٖ تَمُوتُۚ إِنَّ ٱللَّهَ عَلِيمٌ خَبِيرُۢ ﴿٣٤﴾", "w": [["اتّقوا ربكم", "خافوه فآمنوا به واعبدوه وحده تنجوا من عذابه."], ["واخشوا يوماً", "يوم الحساب وما يجري فيه."], ["لا يجزي والد عن ولده", "لا يغني والد فيه عن ولده شيئاً."], ["إن وعد الله حق", "وعده بالحساب والجزاء ثابت لا محالة."], ["فلا تغرّنّكم الحياة الدنيا", "فإنها زائلة."], ["ولا يغرّنّكم بالله الغَرور", "الشيطان يغتنم حلم الله وإمهاله فيجرّئكم على المعاصي ويسوّفكم في التوبة."], ["ويعلم ما في الأرحام", "من ذكر أو أنثى، ولا يعلم ذلك سواه."], ["ماذا تكسب غداً", "من خير أو شر."]], "m": "هذا نداء عام لكل البشر: اتّقوا ربكم بالإيمان به وعبادته وحده، واخشوا يوماً عظيماً لا يغني فيه والد عن ولده ولا مولود عن والده شيئاً، كلٌّ يقول: نفسي نفسي، إن وعد الله حق، فلا تغرّنّكم الحياة الدنيا بملاذّها وطول العمر فيها، ولا يغرّنّكم بحلم الله وكرمه الشيطانُ فيحملكم على تأخير التوبة ومزاولة المعاصي، فإن الموت قد يأتي فجأة، فالتوبة التوبة. إن الله استقلّ بعلم الساعة فلا يعلمها أحد، وهي حال تتطلّب المبادرة بالتوبة، وينزّل الغيث ويعلم وقته، ويعلم ما في الأرحام من ذكر أو أنثى ومن إيمان أو كفر، وما تدري نفس ماذا تكسب غداً من خير أو شر، وما تدري نفس بأي أرض تموت، وهذه مفاتح الغيب الخمس كما في الصحيح، إن الله عليم بكل شيء خبير ببواطن الأمور كظواهرها.", "h": ["وجوب تقوى الله عز وجل بالإيمان به وتوحيده في عبادته.", "تقرير عقيدة البعث والجزاء.", "التحذير من الاغترار بالحياة الدنيا، ومن الشيطان وما يزيّنه من المعاصي.", "بيان مفاتح الغيب الخمسة، واختصاص الرب تعالى بمعرفتها.", "كل مدّعٍ لمعرفة الغيب من الجن والإنس فهو طاغوت تجب معاداته.", "ما عُرف اليوم بالآلات الحديثة مما في رحم المرأة ليس داخلاً في قوله: «ويعلم ما في الأرحام»، لأنه بمثابة من فتح فنظر، أما المنفيّ عن كل أحد إلا الله فهو العلم بذلك دون وسيلة."], "k": "«وما تدري نفس ماذا تكسب غداً»… غدي ليس بيدي، فماذا أكسب اليوم؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 297;
insert into public.tdb_cards(topic, i, body) select 297, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيتان ٢٠ – ٢١", "q": "أَلَمۡ تَرَوۡاْ أَنَّ ٱللَّهَ سَخَّرَ لَكُم مَّا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِ وَأَسۡبَغَ عَلَيۡكُمۡ نِعَمَهُۥ ظَٰهِرَةٗ وَبَاطِنَةٗۗ وَمِنَ ٱلنَّاسِ مَن يُجَٰدِلُ فِي ٱللَّهِ بِغَيۡرِ عِلۡمٖ وَلَا هُدٗى وَلَا كِتَٰبٖ مُّنِيرٖ ﴿٢٠﴾ وَإِذَا قِيلَ لَهُمُ ٱتَّبِعُواْ مَآ أَنزَلَ ٱللَّهُ قَالُواْ بَلۡ نَتَّبِعُ مَا وَجَدۡنَا عَلَيۡهِ ءَابَآءَنَآۚ أَوَلَوۡ كَانَ ٱلشَّيۡطَٰنُ يَدۡعُوهُمۡ إِلَىٰ عَذَابِ ٱلسَّعِيرِ ﴿٢١﴾", "w": [["ألم تروا", "ألم تعلموا أيها الناس."], ["سخّر لكم ما في السماوات", "من شمس وقمر وكواكب ورياح وأمطار لمنافعكم."], ["وما في الأرض", "من أشجار وأنهار وجبال وبحار."], ["وأسبغ عليكم نعمه ظاهرة", "أوسعها وأتمّها، كالصحة وكمال الخلق."], ["وباطنة", "كالعقل والمعرفة."], ["من يجادل في الله", "يخاصم في توحيده منكراً له."], ["بغير علم", "بلا وحي ولا دليل عقلي."], ["ولا هدى ولا كتاب منير", "لا سنّة من سنن الرسل، ولا كتاب إلهي واضح."], ["أوَلو كان الشيطان يدعوهم", "أيتّبعونهم ولو كان الشيطان يدعو آباءهم إلى موجبات عذاب السعير؟"]], "m": "عاد السياق بعد قصة لقمان إلى خطاب المشركين: ألم تعلموا أن الله سخّر لكم ما في السماوات من شمس وقمر ومطر، وما في الأرض من أشجار وأنهار وبحار وحيوان لمنافعكم، وأوسع عليكم نعمه ظاهرة كحسن الصورة وكمال الخلق، وباطنة كالعقل والعلم، مما لا يُحصى؟ ومع هذا من الناس من يجادل في توحيد الله وأسمائه وطاعته بغير علم من وحي ولا دليل عقل ولا كتاب منير. وإذا قيل لهم: اتّبعوا ما أنزل الله، قالوا: بل نتّبع ما وجدنا عليه آباءنا من عقائد وثنية وتقاليد جاهلية، أيتّبعونهم ولو كان الشيطان يدعو آباءهم إلى عذاب النار؟", "h": ["تعيين الاستدلال بالخلق على الخالق، وبالنعمة على المنعم.", "وجوب ذكر النعم وشكرها لله تعالى بطاعته وطاعة رسوله ﷺ.", "حرمة الجدال بالجهل ودون علم.", "حرمة التقليد في الباطل والشر والفساد، كتقليد بعض المسلمين اليوم الكفارَ في عاداتهم وأخلاقهم."], "k": "«وأسبغ عليكم نعمه ظاهرة وباطنة»… أعدّ نعمة باطنة واحدة لم أشكرها قط."}, {"lbl": "الآيات ٢٢ – ٢٦", "q": "۞وَمَن يُسۡلِمۡ وَجۡهَهُۥٓ إِلَى ٱللَّهِ وَهُوَ مُحۡسِنٞ فَقَدِ ٱسۡتَمۡسَكَ بِٱلۡعُرۡوَةِ ٱلۡوُثۡقَىٰۗ وَإِلَى ٱللَّهِ عَٰقِبَةُ ٱلۡأُمُورِ ﴿٢٢﴾ وَمَن كَفَرَ فَلَا يَحۡزُنكَ كُفۡرُهُۥٓۚ إِلَيۡنَا مَرۡجِعُهُمۡ فَنُنَبِّئُهُم بِمَا عَمِلُوٓاْۚ إِنَّ ٱللَّهَ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ ﴿٢٣﴾ نُمَتِّعُهُمۡ قَلِيلٗا ثُمَّ نَضۡطَرُّهُمۡ إِلَىٰ عَذَابٍ غَلِيظٖ ﴿٢٤﴾ وَلَئِن سَأَلۡتَهُم مَّنۡ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ لَيَقُولُنَّ ٱللَّهُۚ قُلِ ٱلۡحَمۡدُ لِلَّهِۚ بَلۡ أَكۡثَرُهُمۡ لَا يَعۡلَمُونَ ﴿٢٥﴾ لِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ إِنَّ ٱللَّهَ هُوَ ٱلۡغَنِيُّ ٱلۡحَمِيدُ ﴿٢٦﴾", "w": [["ومن يُسلم وجهه إلى الله", "أقبل على طاعته مخلصاً له العبادة."], ["وهو محسن", "محسن في طاعته إخلاصاً واتّباعاً."], ["فقد استمسك بالعروة الوثقى", "تعلّق بأوثق ما يُتعلّق به فلا يخاف انقطاعاً."], ["وإلى الله عاقبة الأمور", "مرجع كل الأمور إليه."], ["نمتّعهم قليلاً", "متاعاً في الدنيا إلى نهاية آجالهم."], ["ثم نضطرّهم إلى عذاب غليظ", "نُلجئهم في الآخرة إلى عذاب النار."], ["قل الحمد لله", "احمد الله على ظهور الحجة."], ["لا يعلمون", "من يستحق الحمد ومن لا يستحقه."]], "m": "بعد إقامة الحجة على المشركين قال مرغّباً في النجاة: ومن يُقبل بوجهه وقلبه على ربه يعبده متذلّلاً، وهو محسن في عبادته إخلاصاً لله واتّباعاً لرسوله، فقد استمسك بالطرف الأوثق فلا يخاف انقطاعاً، وإلى الله عاقبة الأمور، فليفوّض العبد أموره إليه. ومن كفر فلا يحزنك كفره، إلينا مرجعهم فننبّئهم بما عملوا ونجزيهم، إن الله عليم بما تُكنّه الصدور. نمهلهم فيتمتّعون قليلاً، ثم نُلجئهم بعد موتهم إلى عذاب غليظ لا يُطاق. ولئن سألتهم: من خلق السماوات والأرض؟ ليقولنّ: الله، قل: الحمد لله على إقامة الحجة عليكم باعترافكم، فكيف يُعبد غيره؟ بل أكثرهم لا يعلمون. لله ما في السماوات والأرض خلقاً وملكاً، فهو غني عن المشركين وعبادتهم، الحميد في فعله وصنعه.", "h": ["بيان نجاة أهل «لا إله إلا الله»، وهم الذين عبدوا الله وحده بما شرع لهم.", "تقرير عقيدة البعث والجزاء.", "بيان أن المشركين من العرب موحّدون في الربوبية مشركون في العبادة، ومثلهم كثير من الناس اليوم يعتقدون أن الله رب كل شيء، ويذبحون وينذرون ويحلفون بغيره ويخافون غيره."], "k": "«فقد استمسك بالعروة الوثقى»… بماذا أتمسّك حين تهتزّ الأمور من حولي؟"}, {"lbl": "الآيتان ٢٧ – ٢٨", "q": "وَلَوۡ أَنَّمَا فِي ٱلۡأَرۡضِ مِن شَجَرَةٍ أَقۡلَٰمٞ وَٱلۡبَحۡرُ يَمُدُّهُۥ مِنۢ بَعۡدِهِۦ سَبۡعَةُ أَبۡحُرٖ مَّا نَفِدَتۡ كَلِمَٰتُ ٱللَّهِۚ إِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٞ ﴿٢٧﴾ مَّا خَلۡقُكُمۡ وَلَا بَعۡثُكُمۡ إِلَّا كَنَفۡسٖ وَٰحِدَةٍۚ إِنَّ ٱللَّهَ سَمِيعُۢ بَصِيرٌ ﴿٢٨﴾", "w": [["ولو أن ما في الأرض", "من شجرة."], ["أقلام", "يُكتب بها."], ["والبحر", "المحيط."], ["يمدّه", "تمدّه سبعة أبحر أخرى مداداً."], ["إن الله عزيز حكيم", "غالب على ما أراد، حكيم في تدبيره."], ["ما خلقكم ولا بعثكم", "ما خلقكم ابتداءً ولا بعثكم إعادةً إلا كخلق وبعث نفس واحدة."]], "m": "لو أن شجر الأرض كله بُري أقلاماً، والبحر المحيط صار مداداً، ومن ورائه سبعة أبحر أخرى تمدّه، فكُتبت بها كلمات الله، لنفد البحر والأقلام ولم تنفد كلمات الله، لأنها غير متناهية، فعلمه وكلامه كذاته وصفاته لا نهاية لها، ونزلت رداً على اليهود لما قالوا: أوتينا التوراة فيها تبيان كل شيء. ونزلت «ما خلقكم ولا بعثكم إلا كنفس واحدة» رداً على أُبيّ بن خلف لما استبعد أن يُعاد الخلق في يوم واحد، فالله كما يسمع أصوات المخلوقات كلها لا يشغله صوت عن صوت، ويبصرهم لا تحجبه ذات عن ذات، كذلك يخلقهم ويبعثهم في وقت واحد، إذ يقول للشيء كن فيكون.", "h": ["بيان سعة علم الله تعالى، وأنه متكلّم وكلماته لا تنفد بحال.", "بيان أن ما أوتيه الإنسان من علوم ومعارف ليس بشيء إلى علم الله تعالى.", "بيان قدرة الله تعالى، وأنها لا تُحدّ ولا يعجزها شيء.", "إثبات صفات الله كالعزة والحكمة والسمع والبصر."], "k": "«ما نفدت كلمات الله»… كم مما أعرفه يكفي لأتواضع أمام ما لا أعرفه؟"}, {"lbl": "الآيات ٢٩ – ٣٢", "q": "أَلَمۡ تَرَ أَنَّ ٱللَّهَ يُولِجُ ٱلَّيۡلَ فِي ٱلنَّهَارِ وَيُولِجُ ٱلنَّهَارَ فِي ٱلَّيۡلِ وَسَخَّرَ ٱلشَّمۡسَ وَٱلۡقَمَرَۖ كُلّٞ يَجۡرِيٓ إِلَىٰٓ أَجَلٖ مُّسَمّٗى وَأَنَّ ٱللَّهَ بِمَا تَعۡمَلُونَ خَبِيرٞ ﴿٢٩﴾ ذَٰلِكَ بِأَنَّ ٱللَّهَ هُوَ ٱلۡحَقُّ وَأَنَّ مَا يَدۡعُونَ مِن دُونِهِ ٱلۡبَٰطِلُ وَأَنَّ ٱللَّهَ هُوَ ٱلۡعَلِيُّ ٱلۡكَبِيرُ ﴿٣٠﴾ أَلَمۡ تَرَ أَنَّ ٱلۡفُلۡكَ تَجۡرِي فِي ٱلۡبَحۡرِ بِنِعۡمَتِ ٱللَّهِ لِيُرِيَكُم مِّنۡ ءَايَٰتِهِۦٓۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّكُلِّ صَبَّارٖ شَكُورٖ ﴿٣١﴾ وَإِذَا غَشِيَهُم مَّوۡجٞ كَٱلظُّلَلِ دَعَوُاْ ٱللَّهَ مُخۡلِصِينَ لَهُ ٱلدِّينَ فَلَمَّا نَجَّىٰهُمۡ إِلَى ٱلۡبَرِّ فَمِنۡهُم مُّقۡتَصِدٞۚ وَمَا يَجۡحَدُ بِـَٔايَٰتِنَآ إِلَّا كُلُّ خَتَّارٖ كَفُورٖ ﴿٣٢﴾", "w": [["ألم تر", "ألم تعلم أيها المخاطب."], ["يولج الليل في النهار", "يُدخل جزءاً من كلٍّ منهما في الآخر بحسب الفصول."], ["وسخّر الشمس والقمر", "يسبحان في فلكيهما إلى يوم القيامة، وهو الأجل المسمّى."], ["ذلك بأن الله هو الحق", "ذلك المذكور بسبب أن الله هو الإله الحق."], ["بنعمة الله", "بإفضاله على العباد إذ هيّأ أسباب جريها."], ["لكل صبّار شكور", "صبّار عن المعاصي، شكور للنعم."], ["وإذا غشيهم موج كالظلل", "علاهم وغطّاهم كالجبال التي تظلّل من تحتها."], ["فمنهم مقتصد", "معتدل بين الكفر والإيمان."], ["ختّار", "غدّار بالعهود، كفور لنعم الله."]], "m": "ما زال السياق في تقرير التوحيد: ألم تر أن الله يُدخل جزءاً من الليل في النهار ومن النهار في الليل بحسب الفصول، وسخّر الشمس والقمر يجريان لمنافع الناس إلى يوم القيامة، وأن الله بما تعملون خبير فيجزيكم؟ ذلك قاطع بأن الله هو الحق، وأن ما يدعون من دونه الباطل، وأن الله هو العلي الكبير. ألم تر أن السفن تجري في البحر بنعمة الله، تحمل السلع والأقوات من إقليم إلى إقليم، ليريكم من آياته؟ إن في ذلك لعبراً لكل صبور على الطاعات وعن المعاصي وعلى الأقدار، شكور لنعم الله. وإذا غشي المشركين وهم في السفينة موج كالجبال دعوا الله مخلصين له الدعاء، فلما نجّاهم إلى البر فمنهم معتدل لا يغلو في كفره ولا يعلن إيمانه، وما يجحد بآياتنا إلا كل غدّار كفور لا خير فيه.", "h": ["تقرير التوحيد وإبطال الشرك بذكر الأدلة المستفادة من مظاهر قدرة الله.", "فضيلة الصبر والشكر، والجمع بينهما خير من افتراقهما.", "بيان أن المشركين أيام نزول القرآن كانوا يوحّدون في الشدة ويشركون في الرخاء.", "شر الناس الختّار، أي الغدّار الكفور."], "k": "«لكل صبّار شكور»… هل أنا صبور في البلاء وشكور في النعمة، أم أنسى الأولى وأجحد الثانية؟"}, {"lbl": "الآيتان ٣٣ – ٣٤", "q": "يَـٰٓأَيُّهَا ٱلنَّاسُ ٱتَّقُواْ رَبَّكُمۡ وَٱخۡشَوۡاْ يَوۡمٗا لَّا يَجۡزِي وَالِدٌ عَن وَلَدِهِۦ وَلَا مَوۡلُودٌ هُوَ جَازٍ عَن وَالِدِهِۦ شَيۡـًٔاۚ إِنَّ وَعۡدَ ٱللَّهِ حَقّٞۖ فَلَا تَغُرَّنَّكُمُ ٱلۡحَيَوٰةُ ٱلدُّنۡيَا وَلَا يَغُرَّنَّكُم بِٱللَّهِ ٱلۡغَرُورُ ﴿٣٣﴾ إِنَّ ٱللَّهَ عِندَهُۥ عِلۡمُ ٱلسَّاعَةِ وَيُنَزِّلُ ٱلۡغَيۡثَ وَيَعۡلَمُ مَا فِي ٱلۡأَرۡحَامِۖ وَمَا تَدۡرِي نَفۡسٞ مَّاذَا تَكۡسِبُ غَدٗاۖ وَمَا تَدۡرِي نَفۡسُۢ بِأَيِّ أَرۡضٖ تَمُوتُۚ إِنَّ ٱللَّهَ عَلِيمٌ خَبِيرُۢ ﴿٣٤﴾", "w": [["اتّقوا ربكم", "خافوه فآمنوا به واعبدوه وحده تنجوا من عذابه."], ["واخشوا يوماً", "يوم الحساب وما يجري فيه."], ["لا يجزي والد عن ولده", "لا يغني والد فيه عن ولده شيئاً."], ["إن وعد الله حق", "وعده بالحساب والجزاء ثابت لا محالة."], ["فلا تغرّنّكم الحياة الدنيا", "فإنها زائلة."], ["ولا يغرّنّكم بالله الغَرور", "الشيطان يغتنم حلم الله وإمهاله فيجرّئكم على المعاصي ويسوّفكم في التوبة."], ["ويعلم ما في الأرحام", "من ذكر أو أنثى، ولا يعلم ذلك سواه."], ["ماذا تكسب غداً", "من خير أو شر."]], "m": "هذا نداء عام لكل البشر: اتّقوا ربكم بالإيمان به وعبادته وحده، واخشوا يوماً عظيماً لا يغني فيه والد عن ولده ولا مولود عن والده شيئاً، كلٌّ يقول: نفسي نفسي، إن وعد الله حق، فلا تغرّنّكم الحياة الدنيا بملاذّها وطول العمر فيها، ولا يغرّنّكم بحلم الله وكرمه الشيطانُ فيحملكم على تأخير التوبة ومزاولة المعاصي، فإن الموت قد يأتي فجأة، فالتوبة التوبة. إن الله استقلّ بعلم الساعة فلا يعلمها أحد، وهي حال تتطلّب المبادرة بالتوبة، وينزّل الغيث ويعلم وقته، ويعلم ما في الأرحام من ذكر أو أنثى ومن إيمان أو كفر، وما تدري نفس ماذا تكسب غداً من خير أو شر، وما تدري نفس بأي أرض تموت، وهذه مفاتح الغيب الخمس كما في الصحيح، إن الله عليم بكل شيء خبير ببواطن الأمور كظواهرها.", "h": ["وجوب تقوى الله عز وجل بالإيمان به وتوحيده في عبادته.", "تقرير عقيدة البعث والجزاء.", "التحذير من الاغترار بالحياة الدنيا، ومن الشيطان وما يزيّنه من المعاصي.", "بيان مفاتح الغيب الخمسة، واختصاص الرب تعالى بمعرفتها.", "كل مدّعٍ لمعرفة الغيب من الجن والإنس فهو طاغوت تجب معاداته.", "ما عُرف اليوم بالآلات الحديثة مما في رحم المرأة ليس داخلاً في قوله: «ويعلم ما في الأرحام»، لأنه بمثابة من فتح فنظر، أما المنفيّ عن كل أحد إلا الله فهو العلم بذلك دون وسيلة."], "k": "«وما تدري نفس ماذا تكسب غداً»… غدي ليس بيدي، فماذا أكسب اليوم؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (298, 32, 1, 14, 'سورة السجدة ١ – ١٤', '«تنزيل الكتاب لا ريب فيه من رب العالمين»، و«الذي أحسن كل شيء خلقه»، و«ولو ترى إذ المجرمون ناكسو رؤوسهم عند ربهم»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 298) = $j$[{"lbl": "الآيات ١ – ٤", "q": "الٓمٓ ﴿١﴾ تَنزِيلُ ٱلۡكِتَٰبِ لَا رَيۡبَ فِيهِ مِن رَّبِّ ٱلۡعَٰلَمِينَ ﴿٢﴾ أَمۡ يَقُولُونَ ٱفۡتَرَىٰهُۚ بَلۡ هُوَ ٱلۡحَقُّ مِن رَّبِّكَ لِتُنذِرَ قَوۡمٗا مَّآ أَتَىٰهُم مِّن نَّذِيرٖ مِّن قَبۡلِكَ لَعَلَّهُمۡ يَهۡتَدُونَ ﴿٣﴾ ٱللَّهُ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ وَمَا بَيۡنَهُمَا فِي سِتَّةِ أَيَّامٖ ثُمَّ ٱسۡتَوَىٰ عَلَى ٱلۡعَرۡشِۖ مَا لَكُم مِّن دُونِهِۦ مِن وَلِيّٖ وَلَا شَفِيعٍۚ أَفَلَا تَتَذَكَّرُونَ ﴿٤﴾", "w": [["الم", "تُكتب ألم وتُقرأ: ألف لام ميم."], ["لا ريب فيه", "لا شك في أنه نزل من رب العالمين."], ["أم يقولون افتراه", "بل أيقولون اختلقه محمد؟"], ["قوماً ما أتاهم من نذير", "من زمن بعيد، وهم قريش والعرب."], ["لعلهم يهتدون", "بعد ضلالهم إلى الحق."], ["في ستة أيام", "أولها الأحد وآخرها الجمعة."], ["ثم استوى على العرش", "استوى على عرشه يدبّر أمر خليقته."], ["من وليّ ولا شفيع", "ليس لكم من دون الله وليّ يتولاكم ولا شفيع."], ["أفلا تتذكّرون", "أفلا تتّعظون فتؤمنوا وتوحّدوا؟"]], "m": "الم، الأسلم أن يُقال: الله أعلم بمراده، وفيها فائدتان: استهواء المشركين بنغمها فيسمعون، وتحدّيهم بأن القرآن تألّف من مثلها. تنزيل القرآن لا شك فيه من رب العالمين. بل أيقولون اختلقه محمد من تلقاء نفسه؟ لا، بل هو الحق من ربك أوحاه إليك لتنذر قوماً ما أتاهم من نذير من قبلك، مشركي العرب، لعلهم يهتدون فينجوا. الله الذي خلق السماوات والأرض وما بينهما في ستة أيام، أولها الأحد وآخرها الجمعة، ولذا كانت الجمعة من أفضل الأيام، ثم استوى على العرش استواءً يليق به يدبّر أمر مخلوقاته، هو الإله الحق، ما للبشرية من دونه وليّ يتولاها إن أراد خذلانها، ولا شفيع يشفع لها إن أراد إهلاكها، أفلا تتذكّرون فتعبدوه وحده؟", "h": ["تقرير النبوة المحمدية، بتقرير أن القرآن تنزيل الله ووحيه أوحاه إليه.", "إبطال ما كان المشركون يقولون في القرآن بأنه شعر وسجع كهّان وأساطير.", "بيان الحكمة من إنزال القرآن على النبي ﷺ، وهي الإنذار.", "بيان الزمان الذي خلق الله فيه السماوات والأرض وما بينهما.", "إثبات صفة الاستواء على العرش لله تعالى.", "تقرير أنه ما للبشرية من إله إلا الله، وليس لها من دونه من وليّ ولا شفيع، إلا أن تؤمن به وتعبده فتكمل وتسعد."], "k": "«ما لكم من دونه من وليّ ولا شفيع»… حين أشعر أن لا أحد معي، هل أتذكّر أن وليّي هو الله؟"}, {"lbl": "الآيات ٥ – ٩", "q": "يُدَبِّرُ ٱلۡأَمۡرَ مِنَ ٱلسَّمَآءِ إِلَى ٱلۡأَرۡضِ ثُمَّ يَعۡرُجُ إِلَيۡهِ فِي يَوۡمٖ كَانَ مِقۡدَارُهُۥٓ أَلۡفَ سَنَةٖ مِّمَّا تَعُدُّونَ ﴿٥﴾ ذَٰلِكَ عَٰلِمُ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِ ٱلۡعَزِيزُ ٱلرَّحِيمُ ﴿٦﴾ ٱلَّذِيٓ أَحۡسَنَ كُلَّ شَيۡءٍ خَلَقَهُۥۖ وَبَدَأَ خَلۡقَ ٱلۡإِنسَٰنِ مِن طِينٖ ﴿٧﴾ ثُمَّ جَعَلَ نَسۡلَهُۥ مِن سُلَٰلَةٖ مِّن مَّآءٖ مَّهِينٖ ﴿٨﴾ ثُمَّ سَوَّىٰهُ وَنَفَخَ فِيهِ مِن رُّوحِهِۦۖ وَجَعَلَ لَكُمُ ٱلسَّمۡعَ وَٱلۡأَبۡصَٰرَ وَٱلۡأَفۡـِٔدَةَۚ قَلِيلٗا مَّا تَشۡكُرُونَ ﴿٩﴾", "w": [["يدبّر الأمر من السماء إلى الأرض", "أمر المخلوقات طوال الحياة."], ["ثم يعرج إليه في يوم", "يوم القيامة حيث تنتهي هذه الحياة."], ["ألف سنة مما تعدّون", "من أيام الدنيا."], ["عالم الغيب والشهادة", "ما غاب عن الناس وما شاهدوه."], ["وبدأ خلق الإنسان من طين", "بدأ خلق آدم من طين."], ["من سلالة من ماء مهين", "خلق ذريته من ماء النطفة."], ["ثم سوّاه ونفخ فيه من روحه", "سوّى الجنين في بطن أمه ونفخ فيه الروح كما سوّى آدم."], ["والأفئدة", "القلوب."], ["قليلاً ما تشكرون", "شكراً قليلاً لا يوازي قدر النعمة."]], "m": "ما زال السياق في تقرير أصول العقيدة بذكر مظاهر القدرة: يدبّر الله أمر المخلوقات من السماء، من عند العرش وكتاب المقادير، إلى الأرض، حيث الحياة والموت، والصحة والمرض، والغنى والفقر، والحرب والسلم، والعزّ والذل، ثم يعرج الأمر إليه في يوم القيامة حين يعمّ الفناء، ومقداره ألف سنة من أيام الدنيا. ذلك عالم الغيب والشهادة، العزيز الغالب، الرحيم بالمؤمنين، الذي أحسن كل شيء خلقه وأتقنه، وبدأ خلق الإنسان الأول آدم من طين، ثم جعل نسله من سلالة من ماء مهين، ثم سوّاه ونفخ فيه من روحه، كما نرى الإنسان في رحم أمه، وجعل لكم السمع والأبصار والقلوب لتسمعوا وتبصروا وتفقهوا، قليلاً ما تشكرون هذه النعم الجليلة.", "h": ["بيان جلال الله وعظمته في تدبيره أمر الخلائق.", "بيان صفات الله تعالى من العلم والعزة والرحمة.", "بيان كيفية خلق الإنسان ومادة خلقه.", "شكر العباد، إن شكروا، لا يوازي نعم الله تعالى عليهم.", "وجوب شكر النعم بالاعتراف بها وذكرها وحمد الله عليها وصرفها في مرضاته."], "k": "«وجعل لكم السمع والأبصار والأفئدة قليلاً ما تشكرون»… ماذا سمعت ورأيت وفكّرت اليوم مما يُرضيه؟"}, {"lbl": "الآيتان ١٠ – ١١", "q": "وَقَالُوٓاْ أَءِذَا ضَلَلۡنَا فِي ٱلۡأَرۡضِ أَءِنَّا لَفِي خَلۡقٖ جَدِيدِۭۚ بَلۡ هُم بِلِقَآءِ رَبِّهِمۡ كَٰفِرُونَ ﴿١٠﴾ ۞قُلۡ يَتَوَفَّىٰكُم مَّلَكُ ٱلۡمَوۡتِ ٱلَّذِي وُكِّلَ بِكُمۡ ثُمَّ إِلَىٰ رَبِّكُمۡ تُرۡجَعُونَ ﴿١١﴾", "w": [["أئذا ضللنا في الأرض", "غبنا فيها فصرنا تراباً."], ["أئنا لفي خلق جديد", "أنعود خلقاً جديداً بعد فنائنا؟"], ["بل هم بلقاء ربهم كافرون", "لم يقف الأمر عند استبعادهم البعث، بل كفرهم بلقاء ربهم هو الذي جعلهم ينكرونه."], ["قل يتوفّاكم ملك الموت", "يقبض أرواحكم ملك الموت المكلّف بذلك."], ["ثم إلى ربكم تُرجعون", "بعد الموت، فرجوعكم حتمي."]], "m": "أخبر تعالى عن منكري البعث: وقالوا: أئذا غبنا في الأرض وصرنا تراباً أئنا لعائدون في خلق جديد؟ إنكاراً واستبعاداً، وعلّة ذلك أنهم بلقاء ربهم كافرون. قل لهم يا رسولنا: يتوفّاكم ملك الموت الذي وُكّل بقبض أرواحكم، ثم إلى ربكم ترجعون بعد البعث، وما دمتم لا تدفعون الموت عن أنفسكم فكيف تدفعون الحياة حين يريدها الله لكم؟ وهل دفعتموها حين كنتم عدماً فأوجدكم؟", "h": ["تقرير عقيدة البعث والجزاء.", "الذنب الذي هو سبب كل ذنب هو الكفر بلقاء الله تعالى.", "بيان أن لقبض الأرواح ملكاً، وله أعوان من الملائكة."], "k": "«قل يتوفّاكم ملك الموت»… موعد مؤكّد لا يُؤجَّل؛ فهل أنا مستعدّ له اليوم؟"}, {"lbl": "الآيات ١٢ – ١٤", "q": "وَلَوۡ تَرَىٰٓ إِذِ ٱلۡمُجۡرِمُونَ نَاكِسُواْ رُءُوسِهِمۡ عِندَ رَبِّهِمۡ رَبَّنَآ أَبۡصَرۡنَا وَسَمِعۡنَا فَٱرۡجِعۡنَا نَعۡمَلۡ صَٰلِحًا إِنَّا مُوقِنُونَ ﴿١٢﴾ وَلَوۡ شِئۡنَا لَأٓتَيۡنَا كُلَّ نَفۡسٍ هُدَىٰهَا وَلَٰكِنۡ حَقَّ ٱلۡقَوۡلُ مِنِّي لَأَمۡلَأَنَّ جَهَنَّمَ مِنَ ٱلۡجِنَّةِ وَٱلنَّاسِ أَجۡمَعِينَ ﴿١٣﴾ فَذُوقُواْ بِمَا نَسِيتُمۡ لِقَآءَ يَوۡمِكُمۡ هَٰذَآ إِنَّا نَسِينَٰكُمۡۖ وَذُوقُواْ عَذَابَ ٱلۡخُلۡدِ بِمَا كُنتُمۡ تَعۡمَلُونَ ﴿١٤﴾", "w": [["إذ المجرمون", "المشركون المكذّبون بلقاء ربهم."], ["ناكسو رؤوسهم", "مطأطئوها من الحياء والذل والخزي."], ["أبصرنا وسمعنا", "صدقَ ما كانت رسلك تخبرنا به."], ["فارجعنا", "إلى دار الدنيا."], ["لآتينا كل نفس هداها", "لو أردنا هداية الناس قسراً بلا اختيار لهديناهم."], ["ولكن حقّ القول مني", "وجب: لأملأنّ جهنم من الجنة والناس أجمعين."], ["إنا نسيناكم", "تركناكم في العذاب."], ["عذاب الخلد", "العذاب الدائم."]], "m": "ولو ترى يا رسولنا إذ المجرمون الذين دنّسوا أنفسهم بالشرك والمعاصي مطأطئو رؤوسهم عند ربهم من الخزي يوم البعث لرأيت أمراً فظيعاً، يقولون: ربنا أبصرنا ما كنا نكذّب به، وسمعنا منك تصديق ما كانت رسلك تأمرنا به، فارجعنا إلى الدنيا نعمل صالحاً، إنا موقنون الآن. فأخبر تعالى أنه لا يردّهم، إذ لو شاء هدايتهم قسراً لهداهم بدون اختيارهم، ولكن سبق القضاء بدخولهم جهنم: لأملأنّ جهنم من كفار الجن والإنس أجمعين. فذوقوا العذاب بسبب نسيانكم لقاء يومكم هذا، فلم تؤمنوا ولم تعملوا صالحاً، إنا تركناكم في العذاب، وذوقوا العذاب الدائم بما كنتم تعملون، يُقال لهم ذلك تقريعاً زيادة في عذابهم.", "h": ["التنديد بالإجرام والمجرمين، وبيان حالهم يوم القيامة.", "بيان عدم نفع الإيمان عند معاينة العذاب.", "بيان حكم الله في امتلاء جهنم من مجرمي الإنس والجن.", "تقرير حكم السببية، فالأعمال سبب للجزاء خيراً كان أو شراً."], "k": "«فارجعنا نعمل صالحاً»… أنا الآن في الفرصة التي سيتمنّونها؛ فما العمل الصالح الذي أؤخّره؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 298;
insert into public.tdb_cards(topic, i, body) select 298, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ٤", "q": "الٓمٓ ﴿١﴾ تَنزِيلُ ٱلۡكِتَٰبِ لَا رَيۡبَ فِيهِ مِن رَّبِّ ٱلۡعَٰلَمِينَ ﴿٢﴾ أَمۡ يَقُولُونَ ٱفۡتَرَىٰهُۚ بَلۡ هُوَ ٱلۡحَقُّ مِن رَّبِّكَ لِتُنذِرَ قَوۡمٗا مَّآ أَتَىٰهُم مِّن نَّذِيرٖ مِّن قَبۡلِكَ لَعَلَّهُمۡ يَهۡتَدُونَ ﴿٣﴾ ٱللَّهُ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ وَمَا بَيۡنَهُمَا فِي سِتَّةِ أَيَّامٖ ثُمَّ ٱسۡتَوَىٰ عَلَى ٱلۡعَرۡشِۖ مَا لَكُم مِّن دُونِهِۦ مِن وَلِيّٖ وَلَا شَفِيعٍۚ أَفَلَا تَتَذَكَّرُونَ ﴿٤﴾", "w": [["الم", "تُكتب ألم وتُقرأ: ألف لام ميم."], ["لا ريب فيه", "لا شك في أنه نزل من رب العالمين."], ["أم يقولون افتراه", "بل أيقولون اختلقه محمد؟"], ["قوماً ما أتاهم من نذير", "من زمن بعيد، وهم قريش والعرب."], ["لعلهم يهتدون", "بعد ضلالهم إلى الحق."], ["في ستة أيام", "أولها الأحد وآخرها الجمعة."], ["ثم استوى على العرش", "استوى على عرشه يدبّر أمر خليقته."], ["من وليّ ولا شفيع", "ليس لكم من دون الله وليّ يتولاكم ولا شفيع."], ["أفلا تتذكّرون", "أفلا تتّعظون فتؤمنوا وتوحّدوا؟"]], "m": "الم، الأسلم أن يُقال: الله أعلم بمراده، وفيها فائدتان: استهواء المشركين بنغمها فيسمعون، وتحدّيهم بأن القرآن تألّف من مثلها. تنزيل القرآن لا شك فيه من رب العالمين. بل أيقولون اختلقه محمد من تلقاء نفسه؟ لا، بل هو الحق من ربك أوحاه إليك لتنذر قوماً ما أتاهم من نذير من قبلك، مشركي العرب، لعلهم يهتدون فينجوا. الله الذي خلق السماوات والأرض وما بينهما في ستة أيام، أولها الأحد وآخرها الجمعة، ولذا كانت الجمعة من أفضل الأيام، ثم استوى على العرش استواءً يليق به يدبّر أمر مخلوقاته، هو الإله الحق، ما للبشرية من دونه وليّ يتولاها إن أراد خذلانها، ولا شفيع يشفع لها إن أراد إهلاكها، أفلا تتذكّرون فتعبدوه وحده؟", "h": ["تقرير النبوة المحمدية، بتقرير أن القرآن تنزيل الله ووحيه أوحاه إليه.", "إبطال ما كان المشركون يقولون في القرآن بأنه شعر وسجع كهّان وأساطير.", "بيان الحكمة من إنزال القرآن على النبي ﷺ، وهي الإنذار.", "بيان الزمان الذي خلق الله فيه السماوات والأرض وما بينهما.", "إثبات صفة الاستواء على العرش لله تعالى.", "تقرير أنه ما للبشرية من إله إلا الله، وليس لها من دونه من وليّ ولا شفيع، إلا أن تؤمن به وتعبده فتكمل وتسعد."], "k": "«ما لكم من دونه من وليّ ولا شفيع»… حين أشعر أن لا أحد معي، هل أتذكّر أن وليّي هو الله؟"}, {"lbl": "الآيات ٥ – ٩", "q": "يُدَبِّرُ ٱلۡأَمۡرَ مِنَ ٱلسَّمَآءِ إِلَى ٱلۡأَرۡضِ ثُمَّ يَعۡرُجُ إِلَيۡهِ فِي يَوۡمٖ كَانَ مِقۡدَارُهُۥٓ أَلۡفَ سَنَةٖ مِّمَّا تَعُدُّونَ ﴿٥﴾ ذَٰلِكَ عَٰلِمُ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِ ٱلۡعَزِيزُ ٱلرَّحِيمُ ﴿٦﴾ ٱلَّذِيٓ أَحۡسَنَ كُلَّ شَيۡءٍ خَلَقَهُۥۖ وَبَدَأَ خَلۡقَ ٱلۡإِنسَٰنِ مِن طِينٖ ﴿٧﴾ ثُمَّ جَعَلَ نَسۡلَهُۥ مِن سُلَٰلَةٖ مِّن مَّآءٖ مَّهِينٖ ﴿٨﴾ ثُمَّ سَوَّىٰهُ وَنَفَخَ فِيهِ مِن رُّوحِهِۦۖ وَجَعَلَ لَكُمُ ٱلسَّمۡعَ وَٱلۡأَبۡصَٰرَ وَٱلۡأَفۡـِٔدَةَۚ قَلِيلٗا مَّا تَشۡكُرُونَ ﴿٩﴾", "w": [["يدبّر الأمر من السماء إلى الأرض", "أمر المخلوقات طوال الحياة."], ["ثم يعرج إليه في يوم", "يوم القيامة حيث تنتهي هذه الحياة."], ["ألف سنة مما تعدّون", "من أيام الدنيا."], ["عالم الغيب والشهادة", "ما غاب عن الناس وما شاهدوه."], ["وبدأ خلق الإنسان من طين", "بدأ خلق آدم من طين."], ["من سلالة من ماء مهين", "خلق ذريته من ماء النطفة."], ["ثم سوّاه ونفخ فيه من روحه", "سوّى الجنين في بطن أمه ونفخ فيه الروح كما سوّى آدم."], ["والأفئدة", "القلوب."], ["قليلاً ما تشكرون", "شكراً قليلاً لا يوازي قدر النعمة."]], "m": "ما زال السياق في تقرير أصول العقيدة بذكر مظاهر القدرة: يدبّر الله أمر المخلوقات من السماء، من عند العرش وكتاب المقادير، إلى الأرض، حيث الحياة والموت، والصحة والمرض، والغنى والفقر، والحرب والسلم، والعزّ والذل، ثم يعرج الأمر إليه في يوم القيامة حين يعمّ الفناء، ومقداره ألف سنة من أيام الدنيا. ذلك عالم الغيب والشهادة، العزيز الغالب، الرحيم بالمؤمنين، الذي أحسن كل شيء خلقه وأتقنه، وبدأ خلق الإنسان الأول آدم من طين، ثم جعل نسله من سلالة من ماء مهين، ثم سوّاه ونفخ فيه من روحه، كما نرى الإنسان في رحم أمه، وجعل لكم السمع والأبصار والقلوب لتسمعوا وتبصروا وتفقهوا، قليلاً ما تشكرون هذه النعم الجليلة.", "h": ["بيان جلال الله وعظمته في تدبيره أمر الخلائق.", "بيان صفات الله تعالى من العلم والعزة والرحمة.", "بيان كيفية خلق الإنسان ومادة خلقه.", "شكر العباد، إن شكروا، لا يوازي نعم الله تعالى عليهم.", "وجوب شكر النعم بالاعتراف بها وذكرها وحمد الله عليها وصرفها في مرضاته."], "k": "«وجعل لكم السمع والأبصار والأفئدة قليلاً ما تشكرون»… ماذا سمعت ورأيت وفكّرت اليوم مما يُرضيه؟"}, {"lbl": "الآيتان ١٠ – ١١", "q": "وَقَالُوٓاْ أَءِذَا ضَلَلۡنَا فِي ٱلۡأَرۡضِ أَءِنَّا لَفِي خَلۡقٖ جَدِيدِۭۚ بَلۡ هُم بِلِقَآءِ رَبِّهِمۡ كَٰفِرُونَ ﴿١٠﴾ ۞قُلۡ يَتَوَفَّىٰكُم مَّلَكُ ٱلۡمَوۡتِ ٱلَّذِي وُكِّلَ بِكُمۡ ثُمَّ إِلَىٰ رَبِّكُمۡ تُرۡجَعُونَ ﴿١١﴾", "w": [["أئذا ضللنا في الأرض", "غبنا فيها فصرنا تراباً."], ["أئنا لفي خلق جديد", "أنعود خلقاً جديداً بعد فنائنا؟"], ["بل هم بلقاء ربهم كافرون", "لم يقف الأمر عند استبعادهم البعث، بل كفرهم بلقاء ربهم هو الذي جعلهم ينكرونه."], ["قل يتوفّاكم ملك الموت", "يقبض أرواحكم ملك الموت المكلّف بذلك."], ["ثم إلى ربكم تُرجعون", "بعد الموت، فرجوعكم حتمي."]], "m": "أخبر تعالى عن منكري البعث: وقالوا: أئذا غبنا في الأرض وصرنا تراباً أئنا لعائدون في خلق جديد؟ إنكاراً واستبعاداً، وعلّة ذلك أنهم بلقاء ربهم كافرون. قل لهم يا رسولنا: يتوفّاكم ملك الموت الذي وُكّل بقبض أرواحكم، ثم إلى ربكم ترجعون بعد البعث، وما دمتم لا تدفعون الموت عن أنفسكم فكيف تدفعون الحياة حين يريدها الله لكم؟ وهل دفعتموها حين كنتم عدماً فأوجدكم؟", "h": ["تقرير عقيدة البعث والجزاء.", "الذنب الذي هو سبب كل ذنب هو الكفر بلقاء الله تعالى.", "بيان أن لقبض الأرواح ملكاً، وله أعوان من الملائكة."], "k": "«قل يتوفّاكم ملك الموت»… موعد مؤكّد لا يُؤجَّل؛ فهل أنا مستعدّ له اليوم؟"}, {"lbl": "الآيات ١٢ – ١٤", "q": "وَلَوۡ تَرَىٰٓ إِذِ ٱلۡمُجۡرِمُونَ نَاكِسُواْ رُءُوسِهِمۡ عِندَ رَبِّهِمۡ رَبَّنَآ أَبۡصَرۡنَا وَسَمِعۡنَا فَٱرۡجِعۡنَا نَعۡمَلۡ صَٰلِحًا إِنَّا مُوقِنُونَ ﴿١٢﴾ وَلَوۡ شِئۡنَا لَأٓتَيۡنَا كُلَّ نَفۡسٍ هُدَىٰهَا وَلَٰكِنۡ حَقَّ ٱلۡقَوۡلُ مِنِّي لَأَمۡلَأَنَّ جَهَنَّمَ مِنَ ٱلۡجِنَّةِ وَٱلنَّاسِ أَجۡمَعِينَ ﴿١٣﴾ فَذُوقُواْ بِمَا نَسِيتُمۡ لِقَآءَ يَوۡمِكُمۡ هَٰذَآ إِنَّا نَسِينَٰكُمۡۖ وَذُوقُواْ عَذَابَ ٱلۡخُلۡدِ بِمَا كُنتُمۡ تَعۡمَلُونَ ﴿١٤﴾", "w": [["إذ المجرمون", "المشركون المكذّبون بلقاء ربهم."], ["ناكسو رؤوسهم", "مطأطئوها من الحياء والذل والخزي."], ["أبصرنا وسمعنا", "صدقَ ما كانت رسلك تخبرنا به."], ["فارجعنا", "إلى دار الدنيا."], ["لآتينا كل نفس هداها", "لو أردنا هداية الناس قسراً بلا اختيار لهديناهم."], ["ولكن حقّ القول مني", "وجب: لأملأنّ جهنم من الجنة والناس أجمعين."], ["إنا نسيناكم", "تركناكم في العذاب."], ["عذاب الخلد", "العذاب الدائم."]], "m": "ولو ترى يا رسولنا إذ المجرمون الذين دنّسوا أنفسهم بالشرك والمعاصي مطأطئو رؤوسهم عند ربهم من الخزي يوم البعث لرأيت أمراً فظيعاً، يقولون: ربنا أبصرنا ما كنا نكذّب به، وسمعنا منك تصديق ما كانت رسلك تأمرنا به، فارجعنا إلى الدنيا نعمل صالحاً، إنا موقنون الآن. فأخبر تعالى أنه لا يردّهم، إذ لو شاء هدايتهم قسراً لهداهم بدون اختيارهم، ولكن سبق القضاء بدخولهم جهنم: لأملأنّ جهنم من كفار الجن والإنس أجمعين. فذوقوا العذاب بسبب نسيانكم لقاء يومكم هذا، فلم تؤمنوا ولم تعملوا صالحاً، إنا تركناكم في العذاب، وذوقوا العذاب الدائم بما كنتم تعملون، يُقال لهم ذلك تقريعاً زيادة في عذابهم.", "h": ["التنديد بالإجرام والمجرمين، وبيان حالهم يوم القيامة.", "بيان عدم نفع الإيمان عند معاينة العذاب.", "بيان حكم الله في امتلاء جهنم من مجرمي الإنس والجن.", "تقرير حكم السببية، فالأعمال سبب للجزاء خيراً كان أو شراً."], "k": "«فارجعنا نعمل صالحاً»… أنا الآن في الفرصة التي سيتمنّونها؛ فما العمل الصالح الذي أؤخّره؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (299, 32, 15, 30, 'سورة السجدة ١٥ – ٣٠', '«تتجافى جنوبهم عن المضاجع يدعون ربهم خوفاً وطمعاً»، و«أفمن كان مؤمناً كمن كان فاسقاً لا يستوون»، و«وجعلنا منهم أئمة يهدون بأمرنا لما صبروا»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 299) = $j$[{"lbl": "الآيات ١٥ – ١٧", "q": "إِنَّمَا يُؤۡمِنُ بِـَٔايَٰتِنَا ٱلَّذِينَ إِذَا ذُكِّرُواْ بِهَا خَرُّواْۤ سُجَّدٗاۤ وَسَبَّحُواْ بِحَمۡدِ رَبِّهِمۡ وَهُمۡ لَا يَسۡتَكۡبِرُونَ۩ ﴿١٥﴾ تَتَجَافَىٰ جُنُوبُهُمۡ عَنِ ٱلۡمَضَاجِعِ يَدۡعُونَ رَبَّهُمۡ خَوۡفٗا وَطَمَعٗا وَمِمَّا رَزَقۡنَٰهُمۡ يُنفِقُونَ ﴿١٦﴾ فَلَا تَعۡلَمُ نَفۡسٞ مَّآ أُخۡفِيَ لَهُم مِّن قُرَّةِ أَعۡيُنٖ جَزَآءَۢ بِمَا كَانُواْ يَعۡمَلُونَ ﴿١٧﴾", "w": [["إذا ذُكّروا بها", "وُعظوا بما فيها من أمر ونهي ووعد ووعيد."], ["خرّوا سجّداً", "وقعوا على الأرض ساجدين بوضع جباههم وأنوفهم."], ["وسبّحوا بحمد ربهم", "نزّهوه وهم ساجدون يقولون: سبحان ربي الأعلى."], ["وهم لا يستكبرون", "عن عبادة ربهم في كل أحايينهم."], ["تتجافى جنوبهم", "تتباعد عن الفرش من أجل القيام للصلاة في جوف الليل."], ["خوفاً وطمعاً", "يسألونه النجاة من النار ودخول الجنة."], ["ما أُخفي لهم من قرة أعين", "ما أخفى الله وادّخر لهم من النعيم الذي تقرّ به أعينهم."]], "m": "لما ذكر جزاء المجرمين ذكر جزاء المؤمنين بأجمل صفاتهم: إنما يؤمن بآياتنا حقّ الإيمان الذين إذا قُرئت عليهم، وكانت من آيات السجود، خرّوا ساجدين بوضع جباههم وأنوفهم على الأرض، وسبّحوا بحمد ربهم في سجودهم، وهم لا يستكبرون عن عبادته مطلقاً بل يأتونها متذلّلين خاشعين. تتباعد جنوبهم عن فرشهم في الليل لصلاة التهجّد، يدعون ربهم في صلاتهم وغيرها خوفاً من عذابه وطمعاً في رحمته، ومما رزقناهم ينفقون فضول أموالهم زيادة على الزكاة، كتهجّدهم زيادة على الصلوات الخمس. فلا تعلم نفس ما خبّأ الله لهم من النعيم المقيم الذي تقرّ به أعينهم، جزاءً بما كانوا يعملون، وفي الحديث القدسي: «أعددت لعبادي الصالحين ما لا عين رأت، ولا أذن سمعت، ولا خطر على قلب بشر».", "h": ["فضيلة التسبيح في الصلاة، وهو «سبحان ربي العظيم» في الركوع، و«سبحان ربي الأعلى» في السجود.", "ذمّ الاستكبار وأهله، ومدح التواضع وأهله.", "فضيلة قيام الليل، وهو المعروف بالتهجّد، والدعاء خوفاً وطمعاً.", "بيان ما أعدّ الله للمؤمنين الصادقين من ذوي الصفات المذكورة مما لا عين رأت ولا أذن سمعت ولا خطر على قلب بشر."], "k": "«تتجافى جنوبهم عن المضاجع»… متى آخر مرة فارقت فراشي لربي؟"}, {"lbl": "الآيات ١٨ – ٢٢", "q": "أَفَمَن كَانَ مُؤۡمِنٗا كَمَن كَانَ فَاسِقٗاۚ لَّا يَسۡتَوُۥنَ ﴿١٨﴾ أَمَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ فَلَهُمۡ جَنَّـٰتُ ٱلۡمَأۡوَىٰ نُزُلَۢا بِمَا كَانُواْ يَعۡمَلُونَ ﴿١٩﴾ وَأَمَّا ٱلَّذِينَ فَسَقُواْ فَمَأۡوَىٰهُمُ ٱلنَّارُۖ كُلَّمَآ أَرَادُوٓاْ أَن يَخۡرُجُواْ مِنۡهَآ أُعِيدُواْ فِيهَا وَقِيلَ لَهُمۡ ذُوقُواْ عَذَابَ ٱلنَّارِ ٱلَّذِي كُنتُم بِهِۦ تُكَذِّبُونَ ﴿٢٠﴾ وَلَنُذِيقَنَّهُم مِّنَ ٱلۡعَذَابِ ٱلۡأَدۡنَىٰ دُونَ ٱلۡعَذَابِ ٱلۡأَكۡبَرِ لَعَلَّهُمۡ يَرۡجِعُونَ ﴿٢١﴾ وَمَنۡ أَظۡلَمُ مِمَّن ذُكِّرَ بِـَٔايَٰتِ رَبِّهِۦ ثُمَّ أَعۡرَضَ عَنۡهَآۚ إِنَّا مِنَ ٱلۡمُجۡرِمِينَ مُنتَقِمُونَ ﴿٢٢﴾", "w": [["أفمن كان مؤمناً", "مصدّقاً بالله ورسوله ولقاء ربه."], ["كمن كان فاسقاً", "كافراً؟ لا يستوون."], ["جنات المأوى نُزُلاً", "النُّزُل ما يُعدّ للضيف من قِرى."], ["من العذاب الأدنى", "عذاب الدنيا من القحط والجدب والقتل والأسر."], ["العذاب الأكبر", "عذاب الآخرة في نار جهنم."], ["لعلهم يرجعون", "يصيبهم بالمصائب في الدنيا رجاء أن يؤمنوا."], ["ومن أظلم ممن ذُكّر بآيات ربه فأعرض عنها", "لا أحد أظلم منه أبداً."], ["إنا من المجرمين منتقمون", "من المشركين، بتعذيبهم أشد أنواع العذاب."]], "m": "أفمن كان مؤمناً كمن كان كافراً؟ لا يستوون. أما الذين آمنوا بالله رباً وإلهاً وبمحمد رسولاً وبالإسلام ديناً، وعملوا الصالحات بأداء الفرائض واجتناب المحارم، فلهم جنات المأوى ضيافةً بما كانوا يعملون. وأما الذين فسقوا عن أمر الله فلم يوحّدوه ولم يطيعوه حتى ماتوا فمأواهم النار، كلما همّوا أن يخرجوا منها أُعيدوا فيها، وقيل لهم إهانة: ذوقوا عذاب النار الذي كنتم به تكذّبون. ولنذيقنّهم من العذاب الأدنى في الدنيا بالقحط والقتل والأسر دون العذاب الأكبر يوم القيامة، لعلهم يتوبون، وفعلاً تاب من قريش كثيرون. ومن أظلم ممن وُعظ بآيات ربه فأعرض عنها مستكبراً؟ إنا من أهل الشرك والمعاصي منتقمون.", "h": ["بيان خطأ من يسوّي بين المؤمن والكافر، والبرّ والفاجر، والمطيع والفاسق.", "بيان جزاء كلٍّ من المؤمنين والفاسقين.", "بيان أن الله تعالى كان يأخذ قريشاً بألوان من المصائب لعلهم يتوبون.", "بيان أنه لا أظلم ممن ذُكّر بآيات الله فأعرض عنها مستكبراً جاحداً."], "k": "«ولنذيقنّهم من العذاب الأدنى… لعلهم يرجعون»… هل أقرأ المصيبة الصغيرة دعوةً للرجوع قبل الكبرى؟"}, {"lbl": "الآيات ٢٣ – ٢٦", "q": "وَلَقَدۡ ءَاتَيۡنَا مُوسَى ٱلۡكِتَٰبَ فَلَا تَكُن فِي مِرۡيَةٖ مِّن لِّقَآئِهِۦۖ وَجَعَلۡنَٰهُ هُدٗى لِّبَنِيٓ إِسۡرَـٰٓءِيلَ ﴿٢٣﴾ وَجَعَلۡنَا مِنۡهُمۡ أَئِمَّةٗ يَهۡدُونَ بِأَمۡرِنَا لَمَّا صَبَرُواْۖ وَكَانُواْ بِـَٔايَٰتِنَا يُوقِنُونَ ﴿٢٤﴾ إِنَّ رَبَّكَ هُوَ يَفۡصِلُ بَيۡنَهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ فِيمَا كَانُواْ فِيهِ يَخۡتَلِفُونَ ﴿٢٥﴾ أَوَلَمۡ يَهۡدِ لَهُمۡ كَمۡ أَهۡلَكۡنَا مِن قَبۡلِهِم مِّنَ ٱلۡقُرُونِ يَمۡشُونَ فِي مَسَٰكِنِهِمۡۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٍۚ أَفَلَا يَسۡمَعُونَ ﴿٢٦﴾", "w": [["ولقد آتينا موسى الكتاب", "أنزلنا عليه التوراة."], ["فلا تكن في مرية من لقائه", "فلا تشكّ في لقائك بموسى ليلة الإسراء."], ["وجعلناه هدى لبني إسرائيل", "جعلنا التوراة هادية لهم."], ["وجعلنا منهم أئمة يهدون بأمرنا", "قادة هداة يهدون الناس بأمرنا لهم بذلك."], ["وكانوا بآياتنا يوقنون", "يوقنون بآيات ربهم وما تحمله من وعد ووعيد."], ["هو يفصل بينهم يوم القيامة", "بين الأنبياء وأممهم، وبين المؤمنين والكافرين."], ["أوَلم يهدِ لهم", "أغفلوا ولم يتبيّن لهم؟"], ["كم أهلكنا من قبلهم من القرون", "إهلاكنا كثيراً من الأمم بكفرهم وتكذيبهم."], ["يمشون في مساكنهم", "يمرّون ماشين بديارهم في طريقهم إلى الشام، كمدائن صالح وبحيرة لوط."]], "m": "ولقد آتينا موسى التوراة، فلمَ ينكر المشركون أن يؤتيك الله القرآن؟ وفي هذا تقرير للوحي والنبوة. فلا تكن في شك من لقائك موسى، فقد لقيه ليلة الإسراء والمعراج وطلب إليه أن يراجع ربه في شأن الصلاة حتى صارت خمساً بعد أن كانت خمسين. وجعلنا الكتاب هادياً لبني إسرائيل، وجعلنا منهم أئمة هداة يهدون الناس بأمرنا لما صبروا على أذى أقوامهم، وكانوا بآياتنا يوقنون، فتأهّلوا للإمامة بالصبر واليقين. إن ربك هو يفصل بين المختلفين من الأنبياء وأممهم، والموحّدين والمشركين، يوم القيامة، وفي هذا تسلية للرسول. أوَلم يتبيّن لهم كم أهلكنا من قبلهم من الأمم يمرّون بديارهم في أسفارهم إلى الشام، كمدائن صالح وبحيرة لوط، أننا قادرون على إهلاكهم؟ إن في ذلك لآيات، أفلا يسمعون هذه المواعظ فيتوبوا؟", "h": ["تقرير النبوة المحمدية، وتأكيد قصة الإسراء والمعراج.", "الكتاب والسنّة كلاهما هادٍ للعباد إن طلبوا الهداية فيهما.", "بيان ما تُنال به الإمامة في الدين، وهو الصبر وصحة اليقين.", "كل خلاف كان في هذه الحياة سينتهي بحكم الله تعالى فيه يوم القيامة.", "في إهلاك الله تعالى للقرون السابقة أكبر واعظ لمن له قلب وسمع وبصر."], "k": "«لما صبروا وكانوا بآياتنا يوقنون»… الإمامة في الدين بالصبر واليقين؛ فأيّهما أضعف عندي؟"}, {"lbl": "الآيات ٢٧ – ٣٠", "q": "أَوَلَمۡ يَرَوۡاْ أَنَّا نَسُوقُ ٱلۡمَآءَ إِلَى ٱلۡأَرۡضِ ٱلۡجُرُزِ فَنُخۡرِجُ بِهِۦ زَرۡعٗا تَأۡكُلُ مِنۡهُ أَنۡعَٰمُهُمۡ وَأَنفُسُهُمۡۚ أَفَلَا يُبۡصِرُونَ ﴿٢٧﴾ وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلۡفَتۡحُ إِن كُنتُمۡ صَٰدِقِينَ ﴿٢٨﴾ قُلۡ يَوۡمَ ٱلۡفَتۡحِ لَا يَنفَعُ ٱلَّذِينَ كَفَرُوٓاْ إِيمَٰنُهُمۡ وَلَا هُمۡ يُنظَرُونَ ﴿٢٩﴾ فَأَعۡرِضۡ عَنۡهُمۡ وَٱنتَظِرۡ إِنَّهُم مُّنتَظِرُونَ ﴿٣٠﴾", "w": [["أوَلم يروا أنا نسوق الماء", "أغفلوا ولم يروا سوقنا الماء للإنبات؟"], ["إلى الأرض الجرز", "اليابسة التي لا نبات فيها."], ["تأكل منه أنعامهم", "مواشيهم من إبل وبقر وغنم."], ["أفلا يبصرون", "أعموا فلا يبصرون أن القادر على إحياء الأرض قادر على البعث؟"], ["متى هذا الفتح", "الفصل والحكم بيننا وبينكم، يستعجلون العذاب."], ["ولا هم يُنظرون", "ولا هم يُمهلون للتوبة أو الاعتذار."], ["وانتظر إنهم منتظرون", "انتظر ما سيحلّ بهم، فإنهم منتظرون بك موتاً أو قتلاً."]], "m": "ما زال السياق في تقرير البعث الذي عليه مدار الإصلاح: أوَلم يرَ المكذّبون أنا نسوق ماء الأمطار والأنهار إلى الأرض اليابسة التي لا نبات بها، فنخرج به زرعاً تأكل منه أنعامهم الشعير والذرة، وأنفسهم الحب ونحوه؟ أفلا يبصرون آثار قدرة الله على إحياء الأرض فيؤمنوا بإحياء الموتى؟ ويقولون للمؤمنين لما يخوّفونهم بعذاب الله: متى هذا الفصل بيننا وبينكم إن كنتم صادقين؟ يستعجلونه لخفة أحلامهم. قل: يوم الفتح لا ينفع الذين كفروا إيمانهم عند معاينة العذاب، ولا هم يُمهلون ليتوبوا. فأعرض عنهم وانتظر ما سينزل بهم، إنهم منتظرون بك موتاً أو قتلاً ليستريحوا منك في نظرهم.", "h": ["تقرير عقيدة البعث والجزاء بذكر الأدلة المقرّرة لها.", "استعجال الكافرين العذاب دالّ على جهلهم وطيشهم.", "بيان أن التوبة لا تُقبل عند معاينة العذاب أو مشاهدة ملك الموت ساعة الاحتضار."], "k": "«يوم الفتح لا ينفع الذين كفروا إيمانهم»… للإيمان وقت ينفع فيه؛ فهل أغتنمه قبل أن يُغلق الباب؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 299;
insert into public.tdb_cards(topic, i, body) select 299, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١٥ – ١٧", "q": "إِنَّمَا يُؤۡمِنُ بِـَٔايَٰتِنَا ٱلَّذِينَ إِذَا ذُكِّرُواْ بِهَا خَرُّواْۤ سُجَّدٗاۤ وَسَبَّحُواْ بِحَمۡدِ رَبِّهِمۡ وَهُمۡ لَا يَسۡتَكۡبِرُونَ۩ ﴿١٥﴾ تَتَجَافَىٰ جُنُوبُهُمۡ عَنِ ٱلۡمَضَاجِعِ يَدۡعُونَ رَبَّهُمۡ خَوۡفٗا وَطَمَعٗا وَمِمَّا رَزَقۡنَٰهُمۡ يُنفِقُونَ ﴿١٦﴾ فَلَا تَعۡلَمُ نَفۡسٞ مَّآ أُخۡفِيَ لَهُم مِّن قُرَّةِ أَعۡيُنٖ جَزَآءَۢ بِمَا كَانُواْ يَعۡمَلُونَ ﴿١٧﴾", "w": [["إذا ذُكّروا بها", "وُعظوا بما فيها من أمر ونهي ووعد ووعيد."], ["خرّوا سجّداً", "وقعوا على الأرض ساجدين بوضع جباههم وأنوفهم."], ["وسبّحوا بحمد ربهم", "نزّهوه وهم ساجدون يقولون: سبحان ربي الأعلى."], ["وهم لا يستكبرون", "عن عبادة ربهم في كل أحايينهم."], ["تتجافى جنوبهم", "تتباعد عن الفرش من أجل القيام للصلاة في جوف الليل."], ["خوفاً وطمعاً", "يسألونه النجاة من النار ودخول الجنة."], ["ما أُخفي لهم من قرة أعين", "ما أخفى الله وادّخر لهم من النعيم الذي تقرّ به أعينهم."]], "m": "لما ذكر جزاء المجرمين ذكر جزاء المؤمنين بأجمل صفاتهم: إنما يؤمن بآياتنا حقّ الإيمان الذين إذا قُرئت عليهم، وكانت من آيات السجود، خرّوا ساجدين بوضع جباههم وأنوفهم على الأرض، وسبّحوا بحمد ربهم في سجودهم، وهم لا يستكبرون عن عبادته مطلقاً بل يأتونها متذلّلين خاشعين. تتباعد جنوبهم عن فرشهم في الليل لصلاة التهجّد، يدعون ربهم في صلاتهم وغيرها خوفاً من عذابه وطمعاً في رحمته، ومما رزقناهم ينفقون فضول أموالهم زيادة على الزكاة، كتهجّدهم زيادة على الصلوات الخمس. فلا تعلم نفس ما خبّأ الله لهم من النعيم المقيم الذي تقرّ به أعينهم، جزاءً بما كانوا يعملون، وفي الحديث القدسي: «أعددت لعبادي الصالحين ما لا عين رأت، ولا أذن سمعت، ولا خطر على قلب بشر».", "h": ["فضيلة التسبيح في الصلاة، وهو «سبحان ربي العظيم» في الركوع، و«سبحان ربي الأعلى» في السجود.", "ذمّ الاستكبار وأهله، ومدح التواضع وأهله.", "فضيلة قيام الليل، وهو المعروف بالتهجّد، والدعاء خوفاً وطمعاً.", "بيان ما أعدّ الله للمؤمنين الصادقين من ذوي الصفات المذكورة مما لا عين رأت ولا أذن سمعت ولا خطر على قلب بشر."], "k": "«تتجافى جنوبهم عن المضاجع»… متى آخر مرة فارقت فراشي لربي؟"}, {"lbl": "الآيات ١٨ – ٢٢", "q": "أَفَمَن كَانَ مُؤۡمِنٗا كَمَن كَانَ فَاسِقٗاۚ لَّا يَسۡتَوُۥنَ ﴿١٨﴾ أَمَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ فَلَهُمۡ جَنَّـٰتُ ٱلۡمَأۡوَىٰ نُزُلَۢا بِمَا كَانُواْ يَعۡمَلُونَ ﴿١٩﴾ وَأَمَّا ٱلَّذِينَ فَسَقُواْ فَمَأۡوَىٰهُمُ ٱلنَّارُۖ كُلَّمَآ أَرَادُوٓاْ أَن يَخۡرُجُواْ مِنۡهَآ أُعِيدُواْ فِيهَا وَقِيلَ لَهُمۡ ذُوقُواْ عَذَابَ ٱلنَّارِ ٱلَّذِي كُنتُم بِهِۦ تُكَذِّبُونَ ﴿٢٠﴾ وَلَنُذِيقَنَّهُم مِّنَ ٱلۡعَذَابِ ٱلۡأَدۡنَىٰ دُونَ ٱلۡعَذَابِ ٱلۡأَكۡبَرِ لَعَلَّهُمۡ يَرۡجِعُونَ ﴿٢١﴾ وَمَنۡ أَظۡلَمُ مِمَّن ذُكِّرَ بِـَٔايَٰتِ رَبِّهِۦ ثُمَّ أَعۡرَضَ عَنۡهَآۚ إِنَّا مِنَ ٱلۡمُجۡرِمِينَ مُنتَقِمُونَ ﴿٢٢﴾", "w": [["أفمن كان مؤمناً", "مصدّقاً بالله ورسوله ولقاء ربه."], ["كمن كان فاسقاً", "كافراً؟ لا يستوون."], ["جنات المأوى نُزُلاً", "النُّزُل ما يُعدّ للضيف من قِرى."], ["من العذاب الأدنى", "عذاب الدنيا من القحط والجدب والقتل والأسر."], ["العذاب الأكبر", "عذاب الآخرة في نار جهنم."], ["لعلهم يرجعون", "يصيبهم بالمصائب في الدنيا رجاء أن يؤمنوا."], ["ومن أظلم ممن ذُكّر بآيات ربه فأعرض عنها", "لا أحد أظلم منه أبداً."], ["إنا من المجرمين منتقمون", "من المشركين، بتعذيبهم أشد أنواع العذاب."]], "m": "أفمن كان مؤمناً كمن كان كافراً؟ لا يستوون. أما الذين آمنوا بالله رباً وإلهاً وبمحمد رسولاً وبالإسلام ديناً، وعملوا الصالحات بأداء الفرائض واجتناب المحارم، فلهم جنات المأوى ضيافةً بما كانوا يعملون. وأما الذين فسقوا عن أمر الله فلم يوحّدوه ولم يطيعوه حتى ماتوا فمأواهم النار، كلما همّوا أن يخرجوا منها أُعيدوا فيها، وقيل لهم إهانة: ذوقوا عذاب النار الذي كنتم به تكذّبون. ولنذيقنّهم من العذاب الأدنى في الدنيا بالقحط والقتل والأسر دون العذاب الأكبر يوم القيامة، لعلهم يتوبون، وفعلاً تاب من قريش كثيرون. ومن أظلم ممن وُعظ بآيات ربه فأعرض عنها مستكبراً؟ إنا من أهل الشرك والمعاصي منتقمون.", "h": ["بيان خطأ من يسوّي بين المؤمن والكافر، والبرّ والفاجر، والمطيع والفاسق.", "بيان جزاء كلٍّ من المؤمنين والفاسقين.", "بيان أن الله تعالى كان يأخذ قريشاً بألوان من المصائب لعلهم يتوبون.", "بيان أنه لا أظلم ممن ذُكّر بآيات الله فأعرض عنها مستكبراً جاحداً."], "k": "«ولنذيقنّهم من العذاب الأدنى… لعلهم يرجعون»… هل أقرأ المصيبة الصغيرة دعوةً للرجوع قبل الكبرى؟"}, {"lbl": "الآيات ٢٣ – ٢٦", "q": "وَلَقَدۡ ءَاتَيۡنَا مُوسَى ٱلۡكِتَٰبَ فَلَا تَكُن فِي مِرۡيَةٖ مِّن لِّقَآئِهِۦۖ وَجَعَلۡنَٰهُ هُدٗى لِّبَنِيٓ إِسۡرَـٰٓءِيلَ ﴿٢٣﴾ وَجَعَلۡنَا مِنۡهُمۡ أَئِمَّةٗ يَهۡدُونَ بِأَمۡرِنَا لَمَّا صَبَرُواْۖ وَكَانُواْ بِـَٔايَٰتِنَا يُوقِنُونَ ﴿٢٤﴾ إِنَّ رَبَّكَ هُوَ يَفۡصِلُ بَيۡنَهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ فِيمَا كَانُواْ فِيهِ يَخۡتَلِفُونَ ﴿٢٥﴾ أَوَلَمۡ يَهۡدِ لَهُمۡ كَمۡ أَهۡلَكۡنَا مِن قَبۡلِهِم مِّنَ ٱلۡقُرُونِ يَمۡشُونَ فِي مَسَٰكِنِهِمۡۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٍۚ أَفَلَا يَسۡمَعُونَ ﴿٢٦﴾", "w": [["ولقد آتينا موسى الكتاب", "أنزلنا عليه التوراة."], ["فلا تكن في مرية من لقائه", "فلا تشكّ في لقائك بموسى ليلة الإسراء."], ["وجعلناه هدى لبني إسرائيل", "جعلنا التوراة هادية لهم."], ["وجعلنا منهم أئمة يهدون بأمرنا", "قادة هداة يهدون الناس بأمرنا لهم بذلك."], ["وكانوا بآياتنا يوقنون", "يوقنون بآيات ربهم وما تحمله من وعد ووعيد."], ["هو يفصل بينهم يوم القيامة", "بين الأنبياء وأممهم، وبين المؤمنين والكافرين."], ["أوَلم يهدِ لهم", "أغفلوا ولم يتبيّن لهم؟"], ["كم أهلكنا من قبلهم من القرون", "إهلاكنا كثيراً من الأمم بكفرهم وتكذيبهم."], ["يمشون في مساكنهم", "يمرّون ماشين بديارهم في طريقهم إلى الشام، كمدائن صالح وبحيرة لوط."]], "m": "ولقد آتينا موسى التوراة، فلمَ ينكر المشركون أن يؤتيك الله القرآن؟ وفي هذا تقرير للوحي والنبوة. فلا تكن في شك من لقائك موسى، فقد لقيه ليلة الإسراء والمعراج وطلب إليه أن يراجع ربه في شأن الصلاة حتى صارت خمساً بعد أن كانت خمسين. وجعلنا الكتاب هادياً لبني إسرائيل، وجعلنا منهم أئمة هداة يهدون الناس بأمرنا لما صبروا على أذى أقوامهم، وكانوا بآياتنا يوقنون، فتأهّلوا للإمامة بالصبر واليقين. إن ربك هو يفصل بين المختلفين من الأنبياء وأممهم، والموحّدين والمشركين، يوم القيامة، وفي هذا تسلية للرسول. أوَلم يتبيّن لهم كم أهلكنا من قبلهم من الأمم يمرّون بديارهم في أسفارهم إلى الشام، كمدائن صالح وبحيرة لوط، أننا قادرون على إهلاكهم؟ إن في ذلك لآيات، أفلا يسمعون هذه المواعظ فيتوبوا؟", "h": ["تقرير النبوة المحمدية، وتأكيد قصة الإسراء والمعراج.", "الكتاب والسنّة كلاهما هادٍ للعباد إن طلبوا الهداية فيهما.", "بيان ما تُنال به الإمامة في الدين، وهو الصبر وصحة اليقين.", "كل خلاف كان في هذه الحياة سينتهي بحكم الله تعالى فيه يوم القيامة.", "في إهلاك الله تعالى للقرون السابقة أكبر واعظ لمن له قلب وسمع وبصر."], "k": "«لما صبروا وكانوا بآياتنا يوقنون»… الإمامة في الدين بالصبر واليقين؛ فأيّهما أضعف عندي؟"}, {"lbl": "الآيات ٢٧ – ٣٠", "q": "أَوَلَمۡ يَرَوۡاْ أَنَّا نَسُوقُ ٱلۡمَآءَ إِلَى ٱلۡأَرۡضِ ٱلۡجُرُزِ فَنُخۡرِجُ بِهِۦ زَرۡعٗا تَأۡكُلُ مِنۡهُ أَنۡعَٰمُهُمۡ وَأَنفُسُهُمۡۚ أَفَلَا يُبۡصِرُونَ ﴿٢٧﴾ وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلۡفَتۡحُ إِن كُنتُمۡ صَٰدِقِينَ ﴿٢٨﴾ قُلۡ يَوۡمَ ٱلۡفَتۡحِ لَا يَنفَعُ ٱلَّذِينَ كَفَرُوٓاْ إِيمَٰنُهُمۡ وَلَا هُمۡ يُنظَرُونَ ﴿٢٩﴾ فَأَعۡرِضۡ عَنۡهُمۡ وَٱنتَظِرۡ إِنَّهُم مُّنتَظِرُونَ ﴿٣٠﴾", "w": [["أوَلم يروا أنا نسوق الماء", "أغفلوا ولم يروا سوقنا الماء للإنبات؟"], ["إلى الأرض الجرز", "اليابسة التي لا نبات فيها."], ["تأكل منه أنعامهم", "مواشيهم من إبل وبقر وغنم."], ["أفلا يبصرون", "أعموا فلا يبصرون أن القادر على إحياء الأرض قادر على البعث؟"], ["متى هذا الفتح", "الفصل والحكم بيننا وبينكم، يستعجلون العذاب."], ["ولا هم يُنظرون", "ولا هم يُمهلون للتوبة أو الاعتذار."], ["وانتظر إنهم منتظرون", "انتظر ما سيحلّ بهم، فإنهم منتظرون بك موتاً أو قتلاً."]], "m": "ما زال السياق في تقرير البعث الذي عليه مدار الإصلاح: أوَلم يرَ المكذّبون أنا نسوق ماء الأمطار والأنهار إلى الأرض اليابسة التي لا نبات بها، فنخرج به زرعاً تأكل منه أنعامهم الشعير والذرة، وأنفسهم الحب ونحوه؟ أفلا يبصرون آثار قدرة الله على إحياء الأرض فيؤمنوا بإحياء الموتى؟ ويقولون للمؤمنين لما يخوّفونهم بعذاب الله: متى هذا الفصل بيننا وبينكم إن كنتم صادقين؟ يستعجلونه لخفة أحلامهم. قل: يوم الفتح لا ينفع الذين كفروا إيمانهم عند معاينة العذاب، ولا هم يُمهلون ليتوبوا. فأعرض عنهم وانتظر ما سينزل بهم، إنهم منتظرون بك موتاً أو قتلاً ليستريحوا منك في نظرهم.", "h": ["تقرير عقيدة البعث والجزاء بذكر الأدلة المقرّرة لها.", "استعجال الكافرين العذاب دالّ على جهلهم وطيشهم.", "بيان أن التوبة لا تُقبل عند معاينة العذاب أو مشاهدة ملك الموت ساعة الاحتضار."], "k": "«يوم الفتح لا ينفع الذين كفروا إيمانهم»… للإيمان وقت ينفع فيه؛ فهل أغتنمه قبل أن يُغلق الباب؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (300, 33, 1, 8, 'سورة الأحزاب ١ – ٨', '«يا أيها النبي اتق الله ولا تطع الكافرين والمنافقين»، و«ادعوهم لآبائهم هو أقسط عند الله»، و«النبي أولى بالمؤمنين من أنفسهم وأزواجه أمهاتهم»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 300) = $j$[{"lbl": "الآيات ١ – ٣", "q": "يَـٰٓأَيُّهَا ٱلنَّبِيُّ ٱتَّقِ ٱللَّهَ وَلَا تُطِعِ ٱلۡكَٰفِرِينَ وَٱلۡمُنَٰفِقِينَۚ إِنَّ ٱللَّهَ كَانَ عَلِيمًا حَكِيمٗا ﴿١﴾ وَٱتَّبِعۡ مَا يُوحَىٰٓ إِلَيۡكَ مِن رَّبِّكَۚ إِنَّ ٱللَّهَ كَانَ بِمَا تَعۡمَلُونَ خَبِيرٗا ﴿٢﴾ وَتَوَكَّلۡ عَلَى ٱللَّهِۚ وَكَفَىٰ بِٱللَّهِ وَكِيلٗا ﴿٣﴾", "w": [["اتق الله", "دُم على تقواه بامتثال أوامره واجتناب نواهيه."], ["ولا تطع الكافرين", "المشركين فيما يقترحون عليك."], ["والمنافقين", "الذين يُظهرون الإيمان ويبطنون الكفر، فيما يخوّفونك به."], ["إن الله كان عليماً حكيماً", "عليماً بخلقه ظاهراً وباطناً، حكيماً في تدبيره."], ["واتّبع ما يوحى إليك من ربك", "تقيّد بما يُشرع لك، ولا تلتفت إلى اقتراحات خصومك أو تهديداتهم."], ["وتوكّل على الله", "فوّض أمرك إليه وامضِ فيما أمرك به غير مبالٍ."]], "m": "واصل المشركون اقتراحاتهم من مكة إلى المدينة، يعرضون على النبي ﷺ أن يتخلّى عن بعض دينه أو يطرد بعض أصحابه، والمنافقون يهدّدونه بالقتل غيلة إن لم يكفّ عن ذكر آلهتهم، ففي هذا الظرف نزل: يا أيها النبي، ناداه بعنوان النبوة تشريفاً له لا باسمه كما نادى موسى وعيسى: دُم على تقوى الله، ولا تقبل اقتراح الكافرين، ولا ترهب تهديد المنافقين، إن الله كان عليماً بخلقه حكيماً في تدبيره، فلا يخذلك ولا يمكّنهم منك. واتّبع ما يوحى إليك من ربك من التشريعات، فهي طريق فوزك أنت وأمتك، إن الله كان بما تعملون خبيراً، فيجزي على العمل الصالح حسناً وعلى الفاسد سوءاً. وتوكّل على الله وامضِ منفّذاً أحكامه غير مبالٍ بالكافرين والمنافقين، وكفى بالله وكيلاً حافظاً.", "h": ["وجوب تقوى الله تعالى بفعل المأمور به وترك المنهي عنه.", "حرمة طاعة الكافرين والمنافقين فيما يقترحون أو يهدّدون من أجله.", "وجوب اتّباع الكتاب والسنّة والتوكّل على الله والمضيّ في ذلك بلا خوف."], "k": "«وتوكّل على الله وكفى بالله وكيلاً»… ما الضغط الذي يدفعني اليوم لأتنازل عن شيء من ديني؟"}, {"lbl": "الآيتان ٤ – ٥", "q": "مَّا جَعَلَ ٱللَّهُ لِرَجُلٖ مِّن قَلۡبَيۡنِ فِي جَوۡفِهِۦۚ وَمَا جَعَلَ أَزۡوَٰجَكُمُ ٱلَّـٰٓـِٔي تُظَٰهِرُونَ مِنۡهُنَّ أُمَّهَٰتِكُمۡۚ وَمَا جَعَلَ أَدۡعِيَآءَكُمۡ أَبۡنَآءَكُمۡۚ ذَٰلِكُمۡ قَوۡلُكُم بِأَفۡوَٰهِكُمۡۖ وَٱللَّهُ يَقُولُ ٱلۡحَقَّ وَهُوَ يَهۡدِي ٱلسَّبِيلَ ﴿٤﴾ ٱدۡعُوهُمۡ لِأٓبَآئِهِمۡ هُوَ أَقۡسَطُ عِندَ ٱللَّهِۚ فَإِن لَّمۡ تَعۡلَمُوٓاْ ءَابَآءَهُمۡ فَإِخۡوَٰنُكُمۡ فِي ٱلدِّينِ وَمَوَٰلِيكُمۡۚ وَلَيۡسَ عَلَيۡكُمۡ جُنَاحٞ فِيمَآ أَخۡطَأۡتُم بِهِۦ وَلَٰكِن مَّا تَعَمَّدَتۡ قُلُوبُكُمۡۚ وَكَانَ ٱللَّهُ غَفُورٗا رَّحِيمًا ﴿٥﴾", "w": [["ما جعل الله لرجل من قلبين في جوفه", "لم يخلق الله رجلاً بقلبين كما ادّعى بعض المشركين."], ["تظاهرون منهن أمهاتكم", "يقول الرجل لامرأته: أنتِ عليّ كظهر أمي."], ["وما جعل أدعياءكم أبناءكم", "لم يجعل الدّعيّ ابناً لمن ادّعاه."], ["ذلكم قولكم بأفواهكم", "مجرد قول باللسان لا حقيقة له، فلا تصير المرأة أماً ولا الدّعيّ ابناً."], ["هو أقسط عند الله", "أعدل."], ["فإخوانكم في الدين ومواليكم", "فمن لم يُعرف أبوه قيل له: يا أخي، أو يا ابن عمي."], ["ليس عليكم جناح فيما أخطأتم به", "لا حرج في الخطأ، فمن قال للدّعيّ: يا ابن فلان سبق لسان، فلا إثم عليه."], ["ولكن ما تعمّدت قلوبكم", "الإثم في التعمّد."]], "m": "لما كان القلب محطّ العقل والإدراك كان وجود قلبين في جوف رجل يؤدي إلى التعارض والفساد، فلم يجعل الله ذلك، ردّاً على من ادّعى من أهل مكة أن له قلبين يعقل بهما أفضل من محمد، وفيه إشارة إلى أنه لا يجتمع حب الله وحب أعدائه في قلب. وما جعل أزواجكم اللائي تظاهرون منهن أمهاتكم، وقد كانوا في الجاهلية يعدّون الظهار محرّماً للزوجة كالأم، فأبطل الله ذلك وجعل فيه كفارة في سورة المجادلة. وما جعل أدعياءكم أبناءكم، وقد كانوا في الجاهلية وصدر الإسلام يجعلون المتبنّى ابناً تترتب عليه أحكام البنوة، ذلكم قولكم بأفواهكم لا حقيقة له، والله يقول الحق وهو يهدي السبيل. انسبوهم لآبائهم: يا فلان بن فلان، هو أعدل عند الله، فإن لم تعلموا آباءهم فقولوا: أخي في الإسلام، أو ابن عمي، أو مولاي لمن حرّرتموه، وليس عليكم حرج فيما أخطأتم به سبق لسان أو ظناً، ولكن الإثم فيما تعمّدت قلوبكم، وكان الله غفوراً رحيماً.", "h": ["إبطال التحريم بالظهار الذي كان في الجاهلية.", "إبطال عادة التبنّي، وما يترتب عليها من حرمة نكاح امرأة المتبنّى.", "وجوب دعاء الدّعيّ المتبنّى بأبيه إن عُرف.", "إن لم يُعرف للدّعيّ أب دُعي بعنوان الأخوة الإسلامية أو العمومة.", "رفع الحرج والإثم في الخطأ عموماً، وفي دعاء الدّعيّ باسم مدّعيه سبق لسان خصوصاً."], "k": "«ما جعل الله لرجل من قلبين في جوفه»… قلب واحد لا يتّسع لحبين متعارضين؛ فلمن قلبي؟"}, {"lbl": "الآيات ٦ – ٨", "q": "ٱلنَّبِيُّ أَوۡلَىٰ بِٱلۡمُؤۡمِنِينَ مِنۡ أَنفُسِهِمۡۖ وَأَزۡوَٰجُهُۥٓ أُمَّهَٰتُهُمۡۗ وَأُوْلُواْ ٱلۡأَرۡحَامِ بَعۡضُهُمۡ أَوۡلَىٰ بِبَعۡضٖ فِي كِتَٰبِ ٱللَّهِ مِنَ ٱلۡمُؤۡمِنِينَ وَٱلۡمُهَٰجِرِينَ إِلَّآ أَن تَفۡعَلُوٓاْ إِلَىٰٓ أَوۡلِيَآئِكُم مَّعۡرُوفٗاۚ كَانَ ذَٰلِكَ فِي ٱلۡكِتَٰبِ مَسۡطُورٗا ﴿٦﴾ وَإِذۡ أَخَذۡنَا مِنَ ٱلنَّبِيِّـۧنَ مِيثَٰقَهُمۡ وَمِنكَ وَمِن نُّوحٖ وَإِبۡرَٰهِيمَ وَمُوسَىٰ وَعِيسَى ٱبۡنِ مَرۡيَمَۖ وَأَخَذۡنَا مِنۡهُم مِّيثَٰقًا غَلِيظٗا ﴿٧﴾ لِّيَسۡـَٔلَ ٱلصَّـٰدِقِينَ عَن صِدۡقِهِمۡۚ وَأَعَدَّ لِلۡكَٰفِرِينَ عَذَابًا أَلِيمٗا ﴿٨﴾", "w": [["النبي أولى بالمؤمنين من أنفسهم", "فيما يأمرهم به وينهاهم عنه ويطلبه منهم."], ["وأزواجه أمهاتهم", "في الحرمة، فلا يحلّ نكاحهن."], ["وأولو الأرحام بعضهم أولى ببعض", "في التوارث من المهاجرين والمتعاقدين."], ["إلا أن تفعلوا إلى أوليائكم معروفاً", "بأن توصوا لهم وصية جائزة، وهي الثلث فأقل."], ["كان ذلك في الكتاب مسطوراً", "مكتوباً في اللوح المحفوظ."], ["وإذ أخذنا من النبيين ميثاقهم", "أن يعبدوا الله وحده ويدعوا إلى عبادته."], ["ومنك ومن نوح وإبراهيم وموسى وعيسى", "وقُدّم محمد ﷺ في الذكر تشريفاً له."], ["ميثاقاً غليظاً", "شديداً مؤكّداً."], ["ليسأل الصادقين عن صدقهم", "عن صدقهم في تبليغ الرسالة، تبكيتاً للكافرين بهم."]], "m": "لما أبطل الله التبنّي، وكان النبي ﷺ قد تبنّى زيد بن حارثة فكان يُدعى زيد بن محمد، أعلم المؤمنين أن النبي أولى بهم من أنفسهم فيما يأمرهم وينهاهم، وأن أزواجه أمهاتهم في الحرمة، فلا يتزوّج إحداهن أحد بعده، وأعطاه من الرفعة ما لم يعطه أحداً تعويضاً عما أُخذ منه من بنوّة زيد. وأولو الأرحام بعضهم أولى ببعض في الإرث، فأبطل التوارث بالإيمان والهجرة والحلف الذي كان في صدر الإسلام، وصار بالنسب والمصاهرة والولاء، إلا أن توصوا لأوليائكم من المؤمنين وصيّة بالثلث، كان ذلك في اللوح المحفوظ مكتوباً. واذكر إذ أخذنا من النبيين عامة ميثاقهم أن يعبدوا الله وحده ويدعوا أممهم إليه، ومن أولي العزم خاصة: منك ومن نوح وإبراهيم وموسى وعيسى، وأخذنا منهم ميثاقاً غليظاً، ليسأل الأنبياء الصادقين عن صدقهم في التبليغ تقريعاً لأممهم المكذّبين، فأثاب المؤمنين وأعدّ للكافرين عذاباً أليماً.", "h": ["وجوب تقديم ما يريده الرسول ﷺ من المؤمن على ما يريده المؤمن لنفسه.", "حرمة أزواج النبي ﷺ، وأنهن أمهات المؤمنين، وهو ﷺ كالأب لهم.", "بطلان التوارث بالمؤاخاة والهجرة والتحالف الذي كان في صدر الإسلام.", "جواز الوصية لغير الوارث بالثلث فأقل.", "وجوب توحيد الله تعالى في عبادته ودعوة الناس إلى ذلك.", "تقرير التوحيد بأخذ الميثاق به على كافة الأنبياء والمرسلين."], "k": "«النبي أولى بالمؤمنين من أنفسهم»… حين يتعارض هواي مع سنّته، أيّهما أقدّم؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 300;
insert into public.tdb_cards(topic, i, body) select 300, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ٣", "q": "يَـٰٓأَيُّهَا ٱلنَّبِيُّ ٱتَّقِ ٱللَّهَ وَلَا تُطِعِ ٱلۡكَٰفِرِينَ وَٱلۡمُنَٰفِقِينَۚ إِنَّ ٱللَّهَ كَانَ عَلِيمًا حَكِيمٗا ﴿١﴾ وَٱتَّبِعۡ مَا يُوحَىٰٓ إِلَيۡكَ مِن رَّبِّكَۚ إِنَّ ٱللَّهَ كَانَ بِمَا تَعۡمَلُونَ خَبِيرٗا ﴿٢﴾ وَتَوَكَّلۡ عَلَى ٱللَّهِۚ وَكَفَىٰ بِٱللَّهِ وَكِيلٗا ﴿٣﴾", "w": [["اتق الله", "دُم على تقواه بامتثال أوامره واجتناب نواهيه."], ["ولا تطع الكافرين", "المشركين فيما يقترحون عليك."], ["والمنافقين", "الذين يُظهرون الإيمان ويبطنون الكفر، فيما يخوّفونك به."], ["إن الله كان عليماً حكيماً", "عليماً بخلقه ظاهراً وباطناً، حكيماً في تدبيره."], ["واتّبع ما يوحى إليك من ربك", "تقيّد بما يُشرع لك، ولا تلتفت إلى اقتراحات خصومك أو تهديداتهم."], ["وتوكّل على الله", "فوّض أمرك إليه وامضِ فيما أمرك به غير مبالٍ."]], "m": "واصل المشركون اقتراحاتهم من مكة إلى المدينة، يعرضون على النبي ﷺ أن يتخلّى عن بعض دينه أو يطرد بعض أصحابه، والمنافقون يهدّدونه بالقتل غيلة إن لم يكفّ عن ذكر آلهتهم، ففي هذا الظرف نزل: يا أيها النبي، ناداه بعنوان النبوة تشريفاً له لا باسمه كما نادى موسى وعيسى: دُم على تقوى الله، ولا تقبل اقتراح الكافرين، ولا ترهب تهديد المنافقين، إن الله كان عليماً بخلقه حكيماً في تدبيره، فلا يخذلك ولا يمكّنهم منك. واتّبع ما يوحى إليك من ربك من التشريعات، فهي طريق فوزك أنت وأمتك، إن الله كان بما تعملون خبيراً، فيجزي على العمل الصالح حسناً وعلى الفاسد سوءاً. وتوكّل على الله وامضِ منفّذاً أحكامه غير مبالٍ بالكافرين والمنافقين، وكفى بالله وكيلاً حافظاً.", "h": ["وجوب تقوى الله تعالى بفعل المأمور به وترك المنهي عنه.", "حرمة طاعة الكافرين والمنافقين فيما يقترحون أو يهدّدون من أجله.", "وجوب اتّباع الكتاب والسنّة والتوكّل على الله والمضيّ في ذلك بلا خوف."], "k": "«وتوكّل على الله وكفى بالله وكيلاً»… ما الضغط الذي يدفعني اليوم لأتنازل عن شيء من ديني؟"}, {"lbl": "الآيتان ٤ – ٥", "q": "مَّا جَعَلَ ٱللَّهُ لِرَجُلٖ مِّن قَلۡبَيۡنِ فِي جَوۡفِهِۦۚ وَمَا جَعَلَ أَزۡوَٰجَكُمُ ٱلَّـٰٓـِٔي تُظَٰهِرُونَ مِنۡهُنَّ أُمَّهَٰتِكُمۡۚ وَمَا جَعَلَ أَدۡعِيَآءَكُمۡ أَبۡنَآءَكُمۡۚ ذَٰلِكُمۡ قَوۡلُكُم بِأَفۡوَٰهِكُمۡۖ وَٱللَّهُ يَقُولُ ٱلۡحَقَّ وَهُوَ يَهۡدِي ٱلسَّبِيلَ ﴿٤﴾ ٱدۡعُوهُمۡ لِأٓبَآئِهِمۡ هُوَ أَقۡسَطُ عِندَ ٱللَّهِۚ فَإِن لَّمۡ تَعۡلَمُوٓاْ ءَابَآءَهُمۡ فَإِخۡوَٰنُكُمۡ فِي ٱلدِّينِ وَمَوَٰلِيكُمۡۚ وَلَيۡسَ عَلَيۡكُمۡ جُنَاحٞ فِيمَآ أَخۡطَأۡتُم بِهِۦ وَلَٰكِن مَّا تَعَمَّدَتۡ قُلُوبُكُمۡۚ وَكَانَ ٱللَّهُ غَفُورٗا رَّحِيمًا ﴿٥﴾", "w": [["ما جعل الله لرجل من قلبين في جوفه", "لم يخلق الله رجلاً بقلبين كما ادّعى بعض المشركين."], ["تظاهرون منهن أمهاتكم", "يقول الرجل لامرأته: أنتِ عليّ كظهر أمي."], ["وما جعل أدعياءكم أبناءكم", "لم يجعل الدّعيّ ابناً لمن ادّعاه."], ["ذلكم قولكم بأفواهكم", "مجرد قول باللسان لا حقيقة له، فلا تصير المرأة أماً ولا الدّعيّ ابناً."], ["هو أقسط عند الله", "أعدل."], ["فإخوانكم في الدين ومواليكم", "فمن لم يُعرف أبوه قيل له: يا أخي، أو يا ابن عمي."], ["ليس عليكم جناح فيما أخطأتم به", "لا حرج في الخطأ، فمن قال للدّعيّ: يا ابن فلان سبق لسان، فلا إثم عليه."], ["ولكن ما تعمّدت قلوبكم", "الإثم في التعمّد."]], "m": "لما كان القلب محطّ العقل والإدراك كان وجود قلبين في جوف رجل يؤدي إلى التعارض والفساد، فلم يجعل الله ذلك، ردّاً على من ادّعى من أهل مكة أن له قلبين يعقل بهما أفضل من محمد، وفيه إشارة إلى أنه لا يجتمع حب الله وحب أعدائه في قلب. وما جعل أزواجكم اللائي تظاهرون منهن أمهاتكم، وقد كانوا في الجاهلية يعدّون الظهار محرّماً للزوجة كالأم، فأبطل الله ذلك وجعل فيه كفارة في سورة المجادلة. وما جعل أدعياءكم أبناءكم، وقد كانوا في الجاهلية وصدر الإسلام يجعلون المتبنّى ابناً تترتب عليه أحكام البنوة، ذلكم قولكم بأفواهكم لا حقيقة له، والله يقول الحق وهو يهدي السبيل. انسبوهم لآبائهم: يا فلان بن فلان، هو أعدل عند الله، فإن لم تعلموا آباءهم فقولوا: أخي في الإسلام، أو ابن عمي، أو مولاي لمن حرّرتموه، وليس عليكم حرج فيما أخطأتم به سبق لسان أو ظناً، ولكن الإثم فيما تعمّدت قلوبكم، وكان الله غفوراً رحيماً.", "h": ["إبطال التحريم بالظهار الذي كان في الجاهلية.", "إبطال عادة التبنّي، وما يترتب عليها من حرمة نكاح امرأة المتبنّى.", "وجوب دعاء الدّعيّ المتبنّى بأبيه إن عُرف.", "إن لم يُعرف للدّعيّ أب دُعي بعنوان الأخوة الإسلامية أو العمومة.", "رفع الحرج والإثم في الخطأ عموماً، وفي دعاء الدّعيّ باسم مدّعيه سبق لسان خصوصاً."], "k": "«ما جعل الله لرجل من قلبين في جوفه»… قلب واحد لا يتّسع لحبين متعارضين؛ فلمن قلبي؟"}, {"lbl": "الآيات ٦ – ٨", "q": "ٱلنَّبِيُّ أَوۡلَىٰ بِٱلۡمُؤۡمِنِينَ مِنۡ أَنفُسِهِمۡۖ وَأَزۡوَٰجُهُۥٓ أُمَّهَٰتُهُمۡۗ وَأُوْلُواْ ٱلۡأَرۡحَامِ بَعۡضُهُمۡ أَوۡلَىٰ بِبَعۡضٖ فِي كِتَٰبِ ٱللَّهِ مِنَ ٱلۡمُؤۡمِنِينَ وَٱلۡمُهَٰجِرِينَ إِلَّآ أَن تَفۡعَلُوٓاْ إِلَىٰٓ أَوۡلِيَآئِكُم مَّعۡرُوفٗاۚ كَانَ ذَٰلِكَ فِي ٱلۡكِتَٰبِ مَسۡطُورٗا ﴿٦﴾ وَإِذۡ أَخَذۡنَا مِنَ ٱلنَّبِيِّـۧنَ مِيثَٰقَهُمۡ وَمِنكَ وَمِن نُّوحٖ وَإِبۡرَٰهِيمَ وَمُوسَىٰ وَعِيسَى ٱبۡنِ مَرۡيَمَۖ وَأَخَذۡنَا مِنۡهُم مِّيثَٰقًا غَلِيظٗا ﴿٧﴾ لِّيَسۡـَٔلَ ٱلصَّـٰدِقِينَ عَن صِدۡقِهِمۡۚ وَأَعَدَّ لِلۡكَٰفِرِينَ عَذَابًا أَلِيمٗا ﴿٨﴾", "w": [["النبي أولى بالمؤمنين من أنفسهم", "فيما يأمرهم به وينهاهم عنه ويطلبه منهم."], ["وأزواجه أمهاتهم", "في الحرمة، فلا يحلّ نكاحهن."], ["وأولو الأرحام بعضهم أولى ببعض", "في التوارث من المهاجرين والمتعاقدين."], ["إلا أن تفعلوا إلى أوليائكم معروفاً", "بأن توصوا لهم وصية جائزة، وهي الثلث فأقل."], ["كان ذلك في الكتاب مسطوراً", "مكتوباً في اللوح المحفوظ."], ["وإذ أخذنا من النبيين ميثاقهم", "أن يعبدوا الله وحده ويدعوا إلى عبادته."], ["ومنك ومن نوح وإبراهيم وموسى وعيسى", "وقُدّم محمد ﷺ في الذكر تشريفاً له."], ["ميثاقاً غليظاً", "شديداً مؤكّداً."], ["ليسأل الصادقين عن صدقهم", "عن صدقهم في تبليغ الرسالة، تبكيتاً للكافرين بهم."]], "m": "لما أبطل الله التبنّي، وكان النبي ﷺ قد تبنّى زيد بن حارثة فكان يُدعى زيد بن محمد، أعلم المؤمنين أن النبي أولى بهم من أنفسهم فيما يأمرهم وينهاهم، وأن أزواجه أمهاتهم في الحرمة، فلا يتزوّج إحداهن أحد بعده، وأعطاه من الرفعة ما لم يعطه أحداً تعويضاً عما أُخذ منه من بنوّة زيد. وأولو الأرحام بعضهم أولى ببعض في الإرث، فأبطل التوارث بالإيمان والهجرة والحلف الذي كان في صدر الإسلام، وصار بالنسب والمصاهرة والولاء، إلا أن توصوا لأوليائكم من المؤمنين وصيّة بالثلث، كان ذلك في اللوح المحفوظ مكتوباً. واذكر إذ أخذنا من النبيين عامة ميثاقهم أن يعبدوا الله وحده ويدعوا أممهم إليه، ومن أولي العزم خاصة: منك ومن نوح وإبراهيم وموسى وعيسى، وأخذنا منهم ميثاقاً غليظاً، ليسأل الأنبياء الصادقين عن صدقهم في التبليغ تقريعاً لأممهم المكذّبين، فأثاب المؤمنين وأعدّ للكافرين عذاباً أليماً.", "h": ["وجوب تقديم ما يريده الرسول ﷺ من المؤمن على ما يريده المؤمن لنفسه.", "حرمة أزواج النبي ﷺ، وأنهن أمهات المؤمنين، وهو ﷺ كالأب لهم.", "بطلان التوارث بالمؤاخاة والهجرة والتحالف الذي كان في صدر الإسلام.", "جواز الوصية لغير الوارث بالثلث فأقل.", "وجوب توحيد الله تعالى في عبادته ودعوة الناس إلى ذلك.", "تقرير التوحيد بأخذ الميثاق به على كافة الأنبياء والمرسلين."], "k": "«النبي أولى بالمؤمنين من أنفسهم»… حين يتعارض هواي مع سنّته، أيّهما أقدّم؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (301, 33, 9, 19, 'سورة الأحزاب ٩ – ١٩', 'غزوة الأحزاب: «إذ جاءتكم جنود فأرسلنا عليهم ريحاً وجنوداً لم تروها»، و«وبلغت القلوب الحناجر»، و«قل لن ينفعكم الفرار إن فررتم من الموت»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 301) = $j$[{"lbl": "الآيات ٩ – ١٤", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱذۡكُرُواْ نِعۡمَةَ ٱللَّهِ عَلَيۡكُمۡ إِذۡ جَآءَتۡكُمۡ جُنُودٞ فَأَرۡسَلۡنَا عَلَيۡهِمۡ رِيحٗا وَجُنُودٗا لَّمۡ تَرَوۡهَاۚ وَكَانَ ٱللَّهُ بِمَا تَعۡمَلُونَ بَصِيرًا ﴿٩﴾ إِذۡ جَآءُوكُم مِّن فَوۡقِكُمۡ وَمِنۡ أَسۡفَلَ مِنكُمۡ وَإِذۡ زَاغَتِ ٱلۡأَبۡصَٰرُ وَبَلَغَتِ ٱلۡقُلُوبُ ٱلۡحَنَاجِرَ وَتَظُنُّونَ بِٱللَّهِ ٱلظُّنُونَا۠ ﴿١٠﴾ هُنَالِكَ ٱبۡتُلِيَ ٱلۡمُؤۡمِنُونَ وَزُلۡزِلُواْ زِلۡزَالٗا شَدِيدٗا ﴿١١﴾ وَإِذۡ يَقُولُ ٱلۡمُنَٰفِقُونَ وَٱلَّذِينَ فِي قُلُوبِهِم مَّرَضٞ مَّا وَعَدَنَا ٱللَّهُ وَرَسُولُهُۥٓ إِلَّا غُرُورٗا ﴿١٢﴾ وَإِذۡ قَالَت طَّآئِفَةٞ مِّنۡهُمۡ يَـٰٓأَهۡلَ يَثۡرِبَ لَا مُقَامَ لَكُمۡ فَٱرۡجِعُواْۚ وَيَسۡتَـٔۡذِنُ فَرِيقٞ مِّنۡهُمُ ٱلنَّبِيَّ يَقُولُونَ إِنَّ بُيُوتَنَا عَوۡرَةٞ وَمَا هِيَ بِعَوۡرَةٍۖ إِن يُرِيدُونَ إِلَّا فِرَارٗا ﴿١٣﴾ وَلَوۡ دُخِلَتۡ عَلَيۡهِم مِّنۡ أَقۡطَارِهَا ثُمَّ سُئِلُواْ ٱلۡفِتۡنَةَ لَأٓتَوۡهَا وَمَا تَلَبَّثُواْ بِهَآ إِلَّا يَسِيرٗا ﴿١٤﴾", "w": [["اذكروا نعمة الله عليكم", "دفاعه عنكم لتشكروه."], ["جنود", "جنود المشركين المتحزّبين."], ["ريحاً وجنوداً لم تروها", "ريح الصَّبا، وجنود الملائكة."], ["إذ جاؤوكم من فوقكم", "أسد وغطفان من قِبل نجد شرق المدينة."], ["ومن أسفل منكم", "قريش وكنانة من الغرب."], ["وإذ زاغت الأبصار", "مالت عن كل شيء إلا عن العدو من شدة الخوف."], ["وبلغت القلوب الحناجر", "منتهى الحلقوم من شدة الخوف."], ["وتظنّون بالله الظنونا", "المختلفة من نصر وهزيمة، ونجاة وهلاك."], ["وزُلزلوا زلزالاً شديداً", "حُرّكوا حراكاً قوياً من شدة الفزع."], ["يا أهل يثرب لا مقام لكم", "لا مقام لكم حول الخندق."], ["إن بيوتنا عورة", "غير حصينة."], ["ثم سُئلوا الفتنة لآتوها", "لو طُلبت منهم الردّة لأعطوها مسرعين."]], "m": "هذه غزوة الخندق، قصّها الله امتناناً على المؤمنين ليشكروا: اذكروا نعمة الله عليكم إذ جاءتكم جنود قريش وأسد وغطفان، وبنو قريظة الذين نقضوا عهدهم، حزّبهم حيي بن أخطب، فأمر النبي ﷺ بحفر الخندق بإشارة سلمان الفارسي، وتمّ حفره في شهر، ونزل المشركون وكانوا قرابة اثني عشر ألفاً، ودام الحصار قرابة الشهر في ليالٍ باردة ومجاعة. فأرسلنا عليهم ريح الصّبا التي قال فيها ﷺ: «نُصرت بالصبا»، فلم تُبق لهم ناراً إلا أطفأتها ولا خيمة إلا أسقطتها، وجنوداً من الملائكة ألقت في قلوبهم الرعب، فرحلوا يجرّون أذيال الخيبة. إذ جاؤوكم من الشرق والغرب، وإذ مالت الأبصار إلا عن العدو، وارتفعت القلوب إلى الحناجر، وظننتم بالله الظنون، هنالك اختُبر المؤمنون ليُرى الثابت من المتزعزع، وأُزعجوا إزعاجاً شديداً لقوة العدو والجوع والبرد ونقض قريظة عهدها. وإذ يقول المنافقون: ما وعدنا الله ورسوله إلا غروراً، وقد بشّرهم ﷺ عند الصخرة بفتح فارس والروم واليمن، فقالوا: يعدنا بكنوز كسرى وأحدنا لا يأمن أن يقضي حاجته! وقالت طائفة منهم: يا أهل يثرب لا مقام لكم فارجعوا، ويستأذن فريق منهم النبي يقولون: إن بيوتنا مكشوفة، وما هي بمكشوفة، إن يريدون إلا الفرار. ولو دخل العدو عليهم المدينة من نواحيها ثم طُلبت منهم الردة لأعطوها فوراً.", "h": ["مشروعية التذكير بالنعم ليشكرها المذكَّرون بها.", "عرض غزوة الأحزاب عرضاً صادقاً لا أمثل منه في عرض الأحداث.", "بيان أن غزوة الخندق كانت من أشد الغزوات وأكثرها ألماً وتعباً على المؤمنين.", "بيان أن حسن الظن بالله ممدوح، وأن سوء الظن به كفر ونفاق.", "بيان مواقف المنافقين الداعية إلى الهزيمة، ليكون ذلك درساً للمؤمنين.", "تقرير النبوة المحمدية بإخبار الغيب، كإخباره ﷺ بفتح فارس والروم واليمن."], "k": "«وتظنّون بالله الظنونا»… حين اشتدّ عليّ الأمر آخر مرة، كيف كان ظني بربي؟"}, {"lbl": "الآيات ١٥ – ١٩", "q": "وَلَقَدۡ كَانُواْ عَٰهَدُواْ ٱللَّهَ مِن قَبۡلُ لَا يُوَلُّونَ ٱلۡأَدۡبَٰرَۚ وَكَانَ عَهۡدُ ٱللَّهِ مَسۡـُٔولٗا ﴿١٥﴾ قُل لَّن يَنفَعَكُمُ ٱلۡفِرَارُ إِن فَرَرۡتُم مِّنَ ٱلۡمَوۡتِ أَوِ ٱلۡقَتۡلِ وَإِذٗا لَّا تُمَتَّعُونَ إِلَّا قَلِيلٗا ﴿١٦﴾ قُلۡ مَن ذَا ٱلَّذِي يَعۡصِمُكُم مِّنَ ٱللَّهِ إِنۡ أَرَادَ بِكُمۡ سُوٓءًا أَوۡ أَرَادَ بِكُمۡ رَحۡمَةٗۚ وَلَا يَجِدُونَ لَهُم مِّن دُونِ ٱللَّهِ وَلِيّٗا وَلَا نَصِيرٗا ﴿١٧﴾ ۞قَدۡ يَعۡلَمُ ٱللَّهُ ٱلۡمُعَوِّقِينَ مِنكُمۡ وَٱلۡقَآئِلِينَ لِإِخۡوَٰنِهِمۡ هَلُمَّ إِلَيۡنَاۖ وَلَا يَأۡتُونَ ٱلۡبَأۡسَ إِلَّا قَلِيلًا ﴿١٨﴾ أَشِحَّةً عَلَيۡكُمۡۖ فَإِذَا جَآءَ ٱلۡخَوۡفُ رَأَيۡتَهُمۡ يَنظُرُونَ إِلَيۡكَ تَدُورُ أَعۡيُنُهُمۡ كَٱلَّذِي يُغۡشَىٰ عَلَيۡهِ مِنَ ٱلۡمَوۡتِۖ فَإِذَا ذَهَبَ ٱلۡخَوۡفُ سَلَقُوكُم بِأَلۡسِنَةٍ حِدَادٍ أَشِحَّةً عَلَى ٱلۡخَيۡرِۚ أُوْلَـٰٓئِكَ لَمۡ يُؤۡمِنُواْ فَأَحۡبَطَ ٱللَّهُ أَعۡمَٰلَهُمۡۚ وَكَانَ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٗا ﴿١٩﴾", "w": [["ولقد كانوا عاهدوا الله من قبل", "يوم أحد: لئن أشهدنا الله قتالاً لنقاتلنّ ولا نولّي الأدبار."], ["وكان عهد الله مسؤولاً", "صاحبه مسؤول عن الوفاء به."], ["وإذاً لا تمتّعون إلا قليلاً", "وإذا فررتم لا تمتّعون بالحياة إلا قليلاً."], ["من ذا الذي يعصمكم من الله", "من يجيركم منه؟"], ["إن أراد بكم سوءاً", "عذاباً تستاؤون له."], ["المعوّقين منكم", "المثبّطين عن القتال."], ["هلمّ إلينا", "تعالوا إلينا ولا تخرجوا مع رسول الله."], ["أشحّةً عليكم", "بخلاء لا ينفقون معكم في الجهاد ولا على الفقراء."], ["كالذي يُغشى عليه من الموت", "من شدة الخوف كالمحتضر."], ["سلقوكم بألسنة حداد", "آذوكم بألسنة ذربة حادة بكثرة كلامهم وتبجّحهم."], ["أولئك لم يؤمنوا", "الإيمان الصحيح، فلذا هم جبناء بخلاء."]], "m": "ما زال السياق في أحداث الأحزاب: ولقد كان أولئك المنافقون عاهدوا الله من قبل، يوم أحد، لا يولّون الأدبار، وكان عهد الله يُسأل عنه صاحبه. قل لهم: لن ينفعكم الفرار من الموت أو القتل، فالآجال محدّدة، ومن لم يمت بالسيف مات بغيره، وإذا فررتم لا تمتّعون إلا قليلاً ثم تموتون، فالفرار لا يطيل العمر والقتال لا ينقصه. قل: من ذا الذي يجيركم من الله إن أراد بكم سوءاً أو أراد بكم رحمة؟ ولا يجدون لهم من دونه وليّاً ولا نصيراً. قد يعلم الله المثبّطين منكم الذين يهوّنون في الخفاء من شأن المسلمين ويعظّمون العدو، والقائلين لإخوانهم: تعالوا إلينا واتركوا محمداً وأصحابه، ولا يحضرون القتال إلا قليلاً دفعاً للمعرّة، بخلاء عليكم. فإذا جاء الخوف رأيتهم ينظرون إليك تدور أعينهم كالمحتضر، فإذا ذهب الخوف ضربوكم بألسنة حادة يطالبون بالغنيمة ويتبجّحون بالكذب، بخلاء بالخير، أولئك لم يؤمنوا فأبطل الله أعمالهم، وكان ذلك على الله يسيراً.", "h": ["وجوب الوفاء بالعهد، إذ نقض العهد من علامات النفاق.", "ترك الجهاد خوفاً من القتل عمل غير صالح، إذ القتال لا ينقص العمر.", "الشحّ والجبن من صفات المنافقين، وهما شرّ الصفات في الإنسان.", "الثرثرة وكثرة الكلام والتبجّح بالأقوال من صفات أهل الجبن والنفاق.", "الكفر محبط للأعمال."], "k": "«سلقوكم بألسنة حداد»… هل كثر كلامي حيث قلّ فعلي؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 301;
insert into public.tdb_cards(topic, i, body) select 301, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٩ – ١٤", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱذۡكُرُواْ نِعۡمَةَ ٱللَّهِ عَلَيۡكُمۡ إِذۡ جَآءَتۡكُمۡ جُنُودٞ فَأَرۡسَلۡنَا عَلَيۡهِمۡ رِيحٗا وَجُنُودٗا لَّمۡ تَرَوۡهَاۚ وَكَانَ ٱللَّهُ بِمَا تَعۡمَلُونَ بَصِيرًا ﴿٩﴾ إِذۡ جَآءُوكُم مِّن فَوۡقِكُمۡ وَمِنۡ أَسۡفَلَ مِنكُمۡ وَإِذۡ زَاغَتِ ٱلۡأَبۡصَٰرُ وَبَلَغَتِ ٱلۡقُلُوبُ ٱلۡحَنَاجِرَ وَتَظُنُّونَ بِٱللَّهِ ٱلظُّنُونَا۠ ﴿١٠﴾ هُنَالِكَ ٱبۡتُلِيَ ٱلۡمُؤۡمِنُونَ وَزُلۡزِلُواْ زِلۡزَالٗا شَدِيدٗا ﴿١١﴾ وَإِذۡ يَقُولُ ٱلۡمُنَٰفِقُونَ وَٱلَّذِينَ فِي قُلُوبِهِم مَّرَضٞ مَّا وَعَدَنَا ٱللَّهُ وَرَسُولُهُۥٓ إِلَّا غُرُورٗا ﴿١٢﴾ وَإِذۡ قَالَت طَّآئِفَةٞ مِّنۡهُمۡ يَـٰٓأَهۡلَ يَثۡرِبَ لَا مُقَامَ لَكُمۡ فَٱرۡجِعُواْۚ وَيَسۡتَـٔۡذِنُ فَرِيقٞ مِّنۡهُمُ ٱلنَّبِيَّ يَقُولُونَ إِنَّ بُيُوتَنَا عَوۡرَةٞ وَمَا هِيَ بِعَوۡرَةٍۖ إِن يُرِيدُونَ إِلَّا فِرَارٗا ﴿١٣﴾ وَلَوۡ دُخِلَتۡ عَلَيۡهِم مِّنۡ أَقۡطَارِهَا ثُمَّ سُئِلُواْ ٱلۡفِتۡنَةَ لَأٓتَوۡهَا وَمَا تَلَبَّثُواْ بِهَآ إِلَّا يَسِيرٗا ﴿١٤﴾", "w": [["اذكروا نعمة الله عليكم", "دفاعه عنكم لتشكروه."], ["جنود", "جنود المشركين المتحزّبين."], ["ريحاً وجنوداً لم تروها", "ريح الصَّبا، وجنود الملائكة."], ["إذ جاؤوكم من فوقكم", "أسد وغطفان من قِبل نجد شرق المدينة."], ["ومن أسفل منكم", "قريش وكنانة من الغرب."], ["وإذ زاغت الأبصار", "مالت عن كل شيء إلا عن العدو من شدة الخوف."], ["وبلغت القلوب الحناجر", "منتهى الحلقوم من شدة الخوف."], ["وتظنّون بالله الظنونا", "المختلفة من نصر وهزيمة، ونجاة وهلاك."], ["وزُلزلوا زلزالاً شديداً", "حُرّكوا حراكاً قوياً من شدة الفزع."], ["يا أهل يثرب لا مقام لكم", "لا مقام لكم حول الخندق."], ["إن بيوتنا عورة", "غير حصينة."], ["ثم سُئلوا الفتنة لآتوها", "لو طُلبت منهم الردّة لأعطوها مسرعين."]], "m": "هذه غزوة الخندق، قصّها الله امتناناً على المؤمنين ليشكروا: اذكروا نعمة الله عليكم إذ جاءتكم جنود قريش وأسد وغطفان، وبنو قريظة الذين نقضوا عهدهم، حزّبهم حيي بن أخطب، فأمر النبي ﷺ بحفر الخندق بإشارة سلمان الفارسي، وتمّ حفره في شهر، ونزل المشركون وكانوا قرابة اثني عشر ألفاً، ودام الحصار قرابة الشهر في ليالٍ باردة ومجاعة. فأرسلنا عليهم ريح الصّبا التي قال فيها ﷺ: «نُصرت بالصبا»، فلم تُبق لهم ناراً إلا أطفأتها ولا خيمة إلا أسقطتها، وجنوداً من الملائكة ألقت في قلوبهم الرعب، فرحلوا يجرّون أذيال الخيبة. إذ جاؤوكم من الشرق والغرب، وإذ مالت الأبصار إلا عن العدو، وارتفعت القلوب إلى الحناجر، وظننتم بالله الظنون، هنالك اختُبر المؤمنون ليُرى الثابت من المتزعزع، وأُزعجوا إزعاجاً شديداً لقوة العدو والجوع والبرد ونقض قريظة عهدها. وإذ يقول المنافقون: ما وعدنا الله ورسوله إلا غروراً، وقد بشّرهم ﷺ عند الصخرة بفتح فارس والروم واليمن، فقالوا: يعدنا بكنوز كسرى وأحدنا لا يأمن أن يقضي حاجته! وقالت طائفة منهم: يا أهل يثرب لا مقام لكم فارجعوا، ويستأذن فريق منهم النبي يقولون: إن بيوتنا مكشوفة، وما هي بمكشوفة، إن يريدون إلا الفرار. ولو دخل العدو عليهم المدينة من نواحيها ثم طُلبت منهم الردة لأعطوها فوراً.", "h": ["مشروعية التذكير بالنعم ليشكرها المذكَّرون بها.", "عرض غزوة الأحزاب عرضاً صادقاً لا أمثل منه في عرض الأحداث.", "بيان أن غزوة الخندق كانت من أشد الغزوات وأكثرها ألماً وتعباً على المؤمنين.", "بيان أن حسن الظن بالله ممدوح، وأن سوء الظن به كفر ونفاق.", "بيان مواقف المنافقين الداعية إلى الهزيمة، ليكون ذلك درساً للمؤمنين.", "تقرير النبوة المحمدية بإخبار الغيب، كإخباره ﷺ بفتح فارس والروم واليمن."], "k": "«وتظنّون بالله الظنونا»… حين اشتدّ عليّ الأمر آخر مرة، كيف كان ظني بربي؟"}, {"lbl": "الآيات ١٥ – ١٩", "q": "وَلَقَدۡ كَانُواْ عَٰهَدُواْ ٱللَّهَ مِن قَبۡلُ لَا يُوَلُّونَ ٱلۡأَدۡبَٰرَۚ وَكَانَ عَهۡدُ ٱللَّهِ مَسۡـُٔولٗا ﴿١٥﴾ قُل لَّن يَنفَعَكُمُ ٱلۡفِرَارُ إِن فَرَرۡتُم مِّنَ ٱلۡمَوۡتِ أَوِ ٱلۡقَتۡلِ وَإِذٗا لَّا تُمَتَّعُونَ إِلَّا قَلِيلٗا ﴿١٦﴾ قُلۡ مَن ذَا ٱلَّذِي يَعۡصِمُكُم مِّنَ ٱللَّهِ إِنۡ أَرَادَ بِكُمۡ سُوٓءًا أَوۡ أَرَادَ بِكُمۡ رَحۡمَةٗۚ وَلَا يَجِدُونَ لَهُم مِّن دُونِ ٱللَّهِ وَلِيّٗا وَلَا نَصِيرٗا ﴿١٧﴾ ۞قَدۡ يَعۡلَمُ ٱللَّهُ ٱلۡمُعَوِّقِينَ مِنكُمۡ وَٱلۡقَآئِلِينَ لِإِخۡوَٰنِهِمۡ هَلُمَّ إِلَيۡنَاۖ وَلَا يَأۡتُونَ ٱلۡبَأۡسَ إِلَّا قَلِيلًا ﴿١٨﴾ أَشِحَّةً عَلَيۡكُمۡۖ فَإِذَا جَآءَ ٱلۡخَوۡفُ رَأَيۡتَهُمۡ يَنظُرُونَ إِلَيۡكَ تَدُورُ أَعۡيُنُهُمۡ كَٱلَّذِي يُغۡشَىٰ عَلَيۡهِ مِنَ ٱلۡمَوۡتِۖ فَإِذَا ذَهَبَ ٱلۡخَوۡفُ سَلَقُوكُم بِأَلۡسِنَةٍ حِدَادٍ أَشِحَّةً عَلَى ٱلۡخَيۡرِۚ أُوْلَـٰٓئِكَ لَمۡ يُؤۡمِنُواْ فَأَحۡبَطَ ٱللَّهُ أَعۡمَٰلَهُمۡۚ وَكَانَ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٗا ﴿١٩﴾", "w": [["ولقد كانوا عاهدوا الله من قبل", "يوم أحد: لئن أشهدنا الله قتالاً لنقاتلنّ ولا نولّي الأدبار."], ["وكان عهد الله مسؤولاً", "صاحبه مسؤول عن الوفاء به."], ["وإذاً لا تمتّعون إلا قليلاً", "وإذا فررتم لا تمتّعون بالحياة إلا قليلاً."], ["من ذا الذي يعصمكم من الله", "من يجيركم منه؟"], ["إن أراد بكم سوءاً", "عذاباً تستاؤون له."], ["المعوّقين منكم", "المثبّطين عن القتال."], ["هلمّ إلينا", "تعالوا إلينا ولا تخرجوا مع رسول الله."], ["أشحّةً عليكم", "بخلاء لا ينفقون معكم في الجهاد ولا على الفقراء."], ["كالذي يُغشى عليه من الموت", "من شدة الخوف كالمحتضر."], ["سلقوكم بألسنة حداد", "آذوكم بألسنة ذربة حادة بكثرة كلامهم وتبجّحهم."], ["أولئك لم يؤمنوا", "الإيمان الصحيح، فلذا هم جبناء بخلاء."]], "m": "ما زال السياق في أحداث الأحزاب: ولقد كان أولئك المنافقون عاهدوا الله من قبل، يوم أحد، لا يولّون الأدبار، وكان عهد الله يُسأل عنه صاحبه. قل لهم: لن ينفعكم الفرار من الموت أو القتل، فالآجال محدّدة، ومن لم يمت بالسيف مات بغيره، وإذا فررتم لا تمتّعون إلا قليلاً ثم تموتون، فالفرار لا يطيل العمر والقتال لا ينقصه. قل: من ذا الذي يجيركم من الله إن أراد بكم سوءاً أو أراد بكم رحمة؟ ولا يجدون لهم من دونه وليّاً ولا نصيراً. قد يعلم الله المثبّطين منكم الذين يهوّنون في الخفاء من شأن المسلمين ويعظّمون العدو، والقائلين لإخوانهم: تعالوا إلينا واتركوا محمداً وأصحابه، ولا يحضرون القتال إلا قليلاً دفعاً للمعرّة، بخلاء عليكم. فإذا جاء الخوف رأيتهم ينظرون إليك تدور أعينهم كالمحتضر، فإذا ذهب الخوف ضربوكم بألسنة حادة يطالبون بالغنيمة ويتبجّحون بالكذب، بخلاء بالخير، أولئك لم يؤمنوا فأبطل الله أعمالهم، وكان ذلك على الله يسيراً.", "h": ["وجوب الوفاء بالعهد، إذ نقض العهد من علامات النفاق.", "ترك الجهاد خوفاً من القتل عمل غير صالح، إذ القتال لا ينقص العمر.", "الشحّ والجبن من صفات المنافقين، وهما شرّ الصفات في الإنسان.", "الثرثرة وكثرة الكلام والتبجّح بالأقوال من صفات أهل الجبن والنفاق.", "الكفر محبط للأعمال."], "k": "«سلقوكم بألسنة حداد»… هل كثر كلامي حيث قلّ فعلي؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (302, 33, 20, 30, 'سورة الأحزاب ٢٠ – ٣٠', '«لقد كان لكم في رسول الله أسوة حسنة»، و«من المؤمنين رجال صدقوا ما عاهدوا الله عليه»، و«يا أيها النبي قل لأزواجك»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 302) = $j$[{"lbl": "الآيات ٢٠ – ٢٥", "q": "يَحۡسَبُونَ ٱلۡأَحۡزَابَ لَمۡ يَذۡهَبُواْۖ وَإِن يَأۡتِ ٱلۡأَحۡزَابُ يَوَدُّواْ لَوۡ أَنَّهُم بَادُونَ فِي ٱلۡأَعۡرَابِ يَسۡـَٔلُونَ عَنۡ أَنۢبَآئِكُمۡۖ وَلَوۡ كَانُواْ فِيكُم مَّا قَٰتَلُوٓاْ إِلَّا قَلِيلٗا ﴿٢٠﴾ لَّقَدۡ كَانَ لَكُمۡ فِي رَسُولِ ٱللَّهِ أُسۡوَةٌ حَسَنَةٞ لِّمَن كَانَ يَرۡجُواْ ٱللَّهَ وَٱلۡيَوۡمَ ٱلۡأٓخِرَ وَذَكَرَ ٱللَّهَ كَثِيرٗا ﴿٢١﴾ وَلَمَّا رَءَا ٱلۡمُؤۡمِنُونَ ٱلۡأَحۡزَابَ قَالُواْ هَٰذَا مَا وَعَدَنَا ٱللَّهُ وَرَسُولُهُۥ وَصَدَقَ ٱللَّهُ وَرَسُولُهُۥۚ وَمَا زَادَهُمۡ إِلَّآ إِيمَٰنٗا وَتَسۡلِيمٗا ﴿٢٢﴾ مِّنَ ٱلۡمُؤۡمِنِينَ رِجَالٞ صَدَقُواْ مَا عَٰهَدُواْ ٱللَّهَ عَلَيۡهِۖ فَمِنۡهُم مَّن قَضَىٰ نَحۡبَهُۥ وَمِنۡهُم مَّن يَنتَظِرُۖ وَمَا بَدَّلُواْ تَبۡدِيلٗا ﴿٢٣﴾ لِّيَجۡزِيَ ٱللَّهُ ٱلصَّـٰدِقِينَ بِصِدۡقِهِمۡ وَيُعَذِّبَ ٱلۡمُنَٰفِقِينَ إِن شَآءَ أَوۡ يَتُوبَ عَلَيۡهِمۡۚ إِنَّ ٱللَّهَ كَانَ غَفُورٗا رَّحِيمٗا ﴿٢٤﴾ وَرَدَّ ٱللَّهُ ٱلَّذِينَ كَفَرُواْ بِغَيۡظِهِمۡ لَمۡ يَنَالُواْ خَيۡرٗاۚ وَكَفَى ٱللَّهُ ٱلۡمُؤۡمِنِينَ ٱلۡقِتَالَۚ وَكَانَ ٱللَّهُ قَوِيًّا عَزِيزٗا ﴿٢٥﴾", "w": [["يحسبون الأحزاب لم يذهبوا", "يظن المنافقون من جبنهم أن الأحزاب لم يرحلوا."], ["يودّوا لو أنهم بادون في الأعراب", "يتمنّون أن لو كانوا في البادية مع الأعراب."], ["يسألون عن أنبائكم", "هل انهزمتم أو انتصرتم؟"], ["ما قاتلوا إلا قليلاً", "لجبنهم وعدم إيمانهم."], ["أسوة حسنة", "قدوة صالحة في القتال والثبات."], ["هذا ما وعدنا الله ورسوله", "من الابتلاء ثم النصر."], ["وما زادهم إلا إيماناً وتسليماً", "تصديقاً بوعد الله وتسليماً لأمره."], ["فمنهم من قضى نحبه", "وفى بنذره فقاتل حتى استُشهد."], ["ومنهم من ينتظر", "ما زال يخوض المعارك ينتظر الشهادة."], ["وما بدّلوا تبديلاً", "في عهدهم، بخلاف المنافقين."], ["وكفى الله المؤمنين القتال", "بالريح والملائكة."]], "m": "يحسب المنافقون الجبناء أن الأحزاب لم يرحلوا مع أنهم رحلوا، وهذا منتهى الجبن، وإن يأت الأحزاب مرة أخرى يتمنّوا أن لو كانوا في البادية مع الأعراب يسألون عن أخباركم، ولو كانوا فيكم ما قاتلوا إلا قليلاً. لقد كان لكم في رسول الله قدوة حسنة لمن كان يرجو الله واليوم الآخر وذكر الله كثيراً، فاقتدوا به في جهاده وصبره وثباته، فقد جاع حتى شدّ على بطنه، وشُجّ وجهه وكُسرت رباعيته يوم أحد، وحفر الخندق بيديه، وثبت أمام العدو. ولما رأى المؤمنون الصادقون الأحزاب قالوا: هذا ما وعدنا الله ورسوله، وصدق الله ورسوله، وما زادهم ذلك إلا إيماناً وتسليماً. من المؤمنين رجال صدقوا ما عاهدوا الله عليه، ممن تأسّفوا على فوات بدر فعاهدوا لئن أشهدهم الله قتالاً ليقاتلنّ حتى يُستشهدوا، فمنهم من وفى بنذره فاستُشهد، ومنهم من ينتظر، وما بدّلوا تبديلاً. ليجزي الله الصادقين بصدقهم، ويعذّب المنافقين إن شاء أو يتوب عليهم، إن الله كان غفوراً رحيماً. وردّ الله الذين كفروا بغيظهم لم ينالوا خيراً، وكفى الله المؤمنين القتال بالريح والملائكة، وكان الله قوياً عزيزاً.", "h": ["تقرير أن الكفر والنفاق لا يفارق صاحبهما الجبن والخور والشح.", "وجوب الائتساء برسول الله ﷺ في كل ما يطيقه العبد المسلم ويقدر عليه.", "ثناء الله تعالى على المؤمنين الصادقين لمواقفهم المشرّفة ووفائهم بعهودهم.", "ذمّ الانهزاميين الناكثين لعهودهم من المنافقين وضعاف الإيمان.", "بيان الحكمة في غزوة الأحزاب: ليجزي الصادقين بصدقهم."], "k": "«لقد كان لكم في رسول الله أسوة حسنة»… في أي موقف صعب اليوم أحتاج أن أسأل: كيف كان سيفعل ﷺ؟"}, {"lbl": "الآيتان ٢٦ – ٢٧", "q": "وَأَنزَلَ ٱلَّذِينَ ظَٰهَرُوهُم مِّنۡ أَهۡلِ ٱلۡكِتَٰبِ مِن صَيَاصِيهِمۡ وَقَذَفَ فِي قُلُوبِهِمُ ٱلرُّعۡبَ فَرِيقٗا تَقۡتُلُونَ وَتَأۡسِرُونَ فَرِيقٗا ﴿٢٦﴾ وَأَوۡرَثَكُمۡ أَرۡضَهُمۡ وَدِيَٰرَهُمۡ وَأَمۡوَٰلَهُمۡ وَأَرۡضٗا لَّمۡ تَطَـُٔوهَاۚ وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٗا ﴿٢٧﴾", "w": [["ظاهروهم", "ناصروا الأحزاب ووقفوا وراءهم."], ["من صياصيهم", "من حصونهم."], ["وقذف في قلوبهم الرعب", "ألقى الخوف في نفوسهم."], ["فريقاً تقتلون", "وهم الرجال المقاتلة."], ["وتأسرون فريقاً", "وهم النساء والأطفال."], ["وأرضاً لم تطؤوها", "وهي خيبر، فُتحت بعد ذلك."]], "m": "هذا شروع في ذكر غزوة بني قريظة بُعيد الخندق في السنة الخامسة: كان بنو قريظة قد نقضوا عهدهم وانضموا إلى الأحزاب، فلما ذهب الأحزاب وعاد الرسول ﷺ إلى المدينة نادى مناديه: «لا يصلّينّ أحدكم العصر إلا في بني قريظة»، بعد أن جاءه جبريل يأمره بالسير إليهم، فحاصروهم قرابة خمس وعشرين ليلة، وقذف الله في قلوبهم الرعب، فنزلوا على حكم سعد بن معاذ، فحكم بقتل المقاتلة وسبي الذراري والنساء وقسم الأموال، فقال ﷺ: «لقد حكمت فيهم بحكم الله»، وبذلك انتهى الوجود اليهودي المعادي بالمدينة. وأنزل الله الذين ظاهروا الأحزاب من أهل الكتاب من حصونهم، وقذف في قلوبهم الرعب، فريقاً تقتلون وتأسرون فريقاً، وأورثكم أرضهم الزراعية وديارهم وأموالهم، وأرضاً لم تطؤوها بعد، وهي خيبر، فُتحت في السنة السادسة، وكان الله على كل شيء قديراً.", "h": ["بيان عاقبة الغدر، فإن قريظة لما غدرت برسول الله انتقم الله منها على يد رسوله والمؤمنين، ولم يبق إلا الذين لا ذنب لهم.", "بيان صدق وعد الله، إذ أورث المسلمين أرضاً لم يكونوا وطئوها، كخيبر والشام والعراق وفارس وبلاد كثيرة.", "تقرير أن قدرة الله لا تُحدّ أبداً."], "k": "«وقذف في قلوبهم الرعب»… الحصون لم تمنعهم حين خانوا؛ فهل أحصّن نفسي بالوفاء؟"}, {"lbl": "الآيات ٢٨ – ٣٠", "q": "يَـٰٓأَيُّهَا ٱلنَّبِيُّ قُل لِّأَزۡوَٰجِكَ إِن كُنتُنَّ تُرِدۡنَ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا وَزِينَتَهَا فَتَعَالَيۡنَ أُمَتِّعۡكُنَّ وَأُسَرِّحۡكُنَّ سَرَاحٗا جَمِيلٗا ﴿٢٨﴾ وَإِن كُنتُنَّ تُرِدۡنَ ٱللَّهَ وَرَسُولَهُۥ وَٱلدَّارَ ٱلۡأٓخِرَةَ فَإِنَّ ٱللَّهَ أَعَدَّ لِلۡمُحۡسِنَٰتِ مِنكُنَّ أَجۡرًا عَظِيمٗا ﴿٢٩﴾ يَٰنِسَآءَ ٱلنَّبِيِّ مَن يَأۡتِ مِنكُنَّ بِفَٰحِشَةٖ مُّبَيِّنَةٖ يُضَٰعَفۡ لَهَا ٱلۡعَذَابُ ضِعۡفَيۡنِۚ وَكَانَ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٗا ﴿٣٠﴾", "w": [["قل لأزواجك", "اللائي تحته يومئذ، وهن تسع طلبن منه التوسعة في النفقة."], ["فتعاليْن", "إلى رسول الله، وكان قد اعتزلهن."], ["أمتّعكنّ", "متعة الطلاق المشروعة على قدر حال المطلّق."], ["وأسرّحكنّ سراحاً جميلاً", "أطلّقكنّ طلاقاً من غير إضرار."], ["تُردن الله ورسوله والدار الآخرة", "تُردن رضا الله ورسوله والجنة."], ["للمحسنات منكن", "في عشرة النبي ﷺ وطاعة الله."], ["بفاحشة مبيّنة", "بنشوز وسوء خلق يتأذّى به رسول الله ﷺ."], ["يُضاعف لها العذاب ضعفين", "مرتين على عذاب غيرها."]], "m": "لما رأت نساء النبي ﷺ نساء الأنصار والمهاجرين قد وُسّع عليهن في النفقة طالبن بالتوسعة أسوة بغيرهن، وكن تسعاً: عائشة، وحفصة، وأم حبيبة، وسودة، وأم سلمة، وزينب بنت جحش، وميمونة، وجويرية، وصفية، فتأثّر ﷺ لعدم القدرة على ما طُلب منه، واعتزلهن شهراً حتى نزلت آية التخيير: يا أيها النبي قل لأزواجك: إن كنتنّ تُردن الحياة الدنيا وزينتها فتعالين أعطكنّ متعة الطلاق وأطلّقكنّ طلاقاً لا إضرار معه، وإن كنتنّ تُردن رضا الله ورسوله والجنة فإن الله أعدّ للمحسنات منكنّ أجراً عظيماً. فبدأ بعائشة فقال: لا تقضي شيئاً حتى تستأمري أبويك، فاختارت الله ورسوله والدار الآخرة، وكذلك اخترن كلهن، فأكرمهن الله فحرّم على رسوله أن يتزوّج عليهن. يا نساء النبي من يأت منكنّ بخصلة قبيحة تؤذي رسول الله يضاعف لها العذاب ضعفين، لأن أذيّة الرسول من أبواب الكفر، ولشرف مقامهن، فذو المنزلة العالية يُستقبح منه القبيح أكثر، وكان ذلك على الله يسيراً.", "h": ["مشروعية تخيير الزوجات، فإن اخترن الطلاق طُلّقن، وإن لم يختَرنه بقين.", "كمال أزواج النبي ﷺ، حيث اخترن الله ورسوله والدار الآخرة على الحياة الدنيا وزينتها.", "مشروعية المتعة بعد الطلاق، وهي أن تُعطى المرأة شيئاً من المال بحسب غنى المطلّق وفقره.", "وجوب الإحسان العام والخاص: الخاص بين الزوجين، والعام في طاعة الله ورسوله.", "بيان أن سيئة العالم الشريف أسوأ من سيئة الجاهل الوضيع."], "k": "«وإن كنتنّ تُردن الله ورسوله والدار الآخرة»… حين يتعارض ما أشتهيه مع ما يرضيه، ماذا أختار؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 302;
insert into public.tdb_cards(topic, i, body) select 302, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٢٠ – ٢٥", "q": "يَحۡسَبُونَ ٱلۡأَحۡزَابَ لَمۡ يَذۡهَبُواْۖ وَإِن يَأۡتِ ٱلۡأَحۡزَابُ يَوَدُّواْ لَوۡ أَنَّهُم بَادُونَ فِي ٱلۡأَعۡرَابِ يَسۡـَٔلُونَ عَنۡ أَنۢبَآئِكُمۡۖ وَلَوۡ كَانُواْ فِيكُم مَّا قَٰتَلُوٓاْ إِلَّا قَلِيلٗا ﴿٢٠﴾ لَّقَدۡ كَانَ لَكُمۡ فِي رَسُولِ ٱللَّهِ أُسۡوَةٌ حَسَنَةٞ لِّمَن كَانَ يَرۡجُواْ ٱللَّهَ وَٱلۡيَوۡمَ ٱلۡأٓخِرَ وَذَكَرَ ٱللَّهَ كَثِيرٗا ﴿٢١﴾ وَلَمَّا رَءَا ٱلۡمُؤۡمِنُونَ ٱلۡأَحۡزَابَ قَالُواْ هَٰذَا مَا وَعَدَنَا ٱللَّهُ وَرَسُولُهُۥ وَصَدَقَ ٱللَّهُ وَرَسُولُهُۥۚ وَمَا زَادَهُمۡ إِلَّآ إِيمَٰنٗا وَتَسۡلِيمٗا ﴿٢٢﴾ مِّنَ ٱلۡمُؤۡمِنِينَ رِجَالٞ صَدَقُواْ مَا عَٰهَدُواْ ٱللَّهَ عَلَيۡهِۖ فَمِنۡهُم مَّن قَضَىٰ نَحۡبَهُۥ وَمِنۡهُم مَّن يَنتَظِرُۖ وَمَا بَدَّلُواْ تَبۡدِيلٗا ﴿٢٣﴾ لِّيَجۡزِيَ ٱللَّهُ ٱلصَّـٰدِقِينَ بِصِدۡقِهِمۡ وَيُعَذِّبَ ٱلۡمُنَٰفِقِينَ إِن شَآءَ أَوۡ يَتُوبَ عَلَيۡهِمۡۚ إِنَّ ٱللَّهَ كَانَ غَفُورٗا رَّحِيمٗا ﴿٢٤﴾ وَرَدَّ ٱللَّهُ ٱلَّذِينَ كَفَرُواْ بِغَيۡظِهِمۡ لَمۡ يَنَالُواْ خَيۡرٗاۚ وَكَفَى ٱللَّهُ ٱلۡمُؤۡمِنِينَ ٱلۡقِتَالَۚ وَكَانَ ٱللَّهُ قَوِيًّا عَزِيزٗا ﴿٢٥﴾", "w": [["يحسبون الأحزاب لم يذهبوا", "يظن المنافقون من جبنهم أن الأحزاب لم يرحلوا."], ["يودّوا لو أنهم بادون في الأعراب", "يتمنّون أن لو كانوا في البادية مع الأعراب."], ["يسألون عن أنبائكم", "هل انهزمتم أو انتصرتم؟"], ["ما قاتلوا إلا قليلاً", "لجبنهم وعدم إيمانهم."], ["أسوة حسنة", "قدوة صالحة في القتال والثبات."], ["هذا ما وعدنا الله ورسوله", "من الابتلاء ثم النصر."], ["وما زادهم إلا إيماناً وتسليماً", "تصديقاً بوعد الله وتسليماً لأمره."], ["فمنهم من قضى نحبه", "وفى بنذره فقاتل حتى استُشهد."], ["ومنهم من ينتظر", "ما زال يخوض المعارك ينتظر الشهادة."], ["وما بدّلوا تبديلاً", "في عهدهم، بخلاف المنافقين."], ["وكفى الله المؤمنين القتال", "بالريح والملائكة."]], "m": "يحسب المنافقون الجبناء أن الأحزاب لم يرحلوا مع أنهم رحلوا، وهذا منتهى الجبن، وإن يأت الأحزاب مرة أخرى يتمنّوا أن لو كانوا في البادية مع الأعراب يسألون عن أخباركم، ولو كانوا فيكم ما قاتلوا إلا قليلاً. لقد كان لكم في رسول الله قدوة حسنة لمن كان يرجو الله واليوم الآخر وذكر الله كثيراً، فاقتدوا به في جهاده وصبره وثباته، فقد جاع حتى شدّ على بطنه، وشُجّ وجهه وكُسرت رباعيته يوم أحد، وحفر الخندق بيديه، وثبت أمام العدو. ولما رأى المؤمنون الصادقون الأحزاب قالوا: هذا ما وعدنا الله ورسوله، وصدق الله ورسوله، وما زادهم ذلك إلا إيماناً وتسليماً. من المؤمنين رجال صدقوا ما عاهدوا الله عليه، ممن تأسّفوا على فوات بدر فعاهدوا لئن أشهدهم الله قتالاً ليقاتلنّ حتى يُستشهدوا، فمنهم من وفى بنذره فاستُشهد، ومنهم من ينتظر، وما بدّلوا تبديلاً. ليجزي الله الصادقين بصدقهم، ويعذّب المنافقين إن شاء أو يتوب عليهم، إن الله كان غفوراً رحيماً. وردّ الله الذين كفروا بغيظهم لم ينالوا خيراً، وكفى الله المؤمنين القتال بالريح والملائكة، وكان الله قوياً عزيزاً.", "h": ["تقرير أن الكفر والنفاق لا يفارق صاحبهما الجبن والخور والشح.", "وجوب الائتساء برسول الله ﷺ في كل ما يطيقه العبد المسلم ويقدر عليه.", "ثناء الله تعالى على المؤمنين الصادقين لمواقفهم المشرّفة ووفائهم بعهودهم.", "ذمّ الانهزاميين الناكثين لعهودهم من المنافقين وضعاف الإيمان.", "بيان الحكمة في غزوة الأحزاب: ليجزي الصادقين بصدقهم."], "k": "«لقد كان لكم في رسول الله أسوة حسنة»… في أي موقف صعب اليوم أحتاج أن أسأل: كيف كان سيفعل ﷺ؟"}, {"lbl": "الآيتان ٢٦ – ٢٧", "q": "وَأَنزَلَ ٱلَّذِينَ ظَٰهَرُوهُم مِّنۡ أَهۡلِ ٱلۡكِتَٰبِ مِن صَيَاصِيهِمۡ وَقَذَفَ فِي قُلُوبِهِمُ ٱلرُّعۡبَ فَرِيقٗا تَقۡتُلُونَ وَتَأۡسِرُونَ فَرِيقٗا ﴿٢٦﴾ وَأَوۡرَثَكُمۡ أَرۡضَهُمۡ وَدِيَٰرَهُمۡ وَأَمۡوَٰلَهُمۡ وَأَرۡضٗا لَّمۡ تَطَـُٔوهَاۚ وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٗا ﴿٢٧﴾", "w": [["ظاهروهم", "ناصروا الأحزاب ووقفوا وراءهم."], ["من صياصيهم", "من حصونهم."], ["وقذف في قلوبهم الرعب", "ألقى الخوف في نفوسهم."], ["فريقاً تقتلون", "وهم الرجال المقاتلة."], ["وتأسرون فريقاً", "وهم النساء والأطفال."], ["وأرضاً لم تطؤوها", "وهي خيبر، فُتحت بعد ذلك."]], "m": "هذا شروع في ذكر غزوة بني قريظة بُعيد الخندق في السنة الخامسة: كان بنو قريظة قد نقضوا عهدهم وانضموا إلى الأحزاب، فلما ذهب الأحزاب وعاد الرسول ﷺ إلى المدينة نادى مناديه: «لا يصلّينّ أحدكم العصر إلا في بني قريظة»، بعد أن جاءه جبريل يأمره بالسير إليهم، فحاصروهم قرابة خمس وعشرين ليلة، وقذف الله في قلوبهم الرعب، فنزلوا على حكم سعد بن معاذ، فحكم بقتل المقاتلة وسبي الذراري والنساء وقسم الأموال، فقال ﷺ: «لقد حكمت فيهم بحكم الله»، وبذلك انتهى الوجود اليهودي المعادي بالمدينة. وأنزل الله الذين ظاهروا الأحزاب من أهل الكتاب من حصونهم، وقذف في قلوبهم الرعب، فريقاً تقتلون وتأسرون فريقاً، وأورثكم أرضهم الزراعية وديارهم وأموالهم، وأرضاً لم تطؤوها بعد، وهي خيبر، فُتحت في السنة السادسة، وكان الله على كل شيء قديراً.", "h": ["بيان عاقبة الغدر، فإن قريظة لما غدرت برسول الله انتقم الله منها على يد رسوله والمؤمنين، ولم يبق إلا الذين لا ذنب لهم.", "بيان صدق وعد الله، إذ أورث المسلمين أرضاً لم يكونوا وطئوها، كخيبر والشام والعراق وفارس وبلاد كثيرة.", "تقرير أن قدرة الله لا تُحدّ أبداً."], "k": "«وقذف في قلوبهم الرعب»… الحصون لم تمنعهم حين خانوا؛ فهل أحصّن نفسي بالوفاء؟"}, {"lbl": "الآيات ٢٨ – ٣٠", "q": "يَـٰٓأَيُّهَا ٱلنَّبِيُّ قُل لِّأَزۡوَٰجِكَ إِن كُنتُنَّ تُرِدۡنَ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا وَزِينَتَهَا فَتَعَالَيۡنَ أُمَتِّعۡكُنَّ وَأُسَرِّحۡكُنَّ سَرَاحٗا جَمِيلٗا ﴿٢٨﴾ وَإِن كُنتُنَّ تُرِدۡنَ ٱللَّهَ وَرَسُولَهُۥ وَٱلدَّارَ ٱلۡأٓخِرَةَ فَإِنَّ ٱللَّهَ أَعَدَّ لِلۡمُحۡسِنَٰتِ مِنكُنَّ أَجۡرًا عَظِيمٗا ﴿٢٩﴾ يَٰنِسَآءَ ٱلنَّبِيِّ مَن يَأۡتِ مِنكُنَّ بِفَٰحِشَةٖ مُّبَيِّنَةٖ يُضَٰعَفۡ لَهَا ٱلۡعَذَابُ ضِعۡفَيۡنِۚ وَكَانَ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٗا ﴿٣٠﴾", "w": [["قل لأزواجك", "اللائي تحته يومئذ، وهن تسع طلبن منه التوسعة في النفقة."], ["فتعاليْن", "إلى رسول الله، وكان قد اعتزلهن."], ["أمتّعكنّ", "متعة الطلاق المشروعة على قدر حال المطلّق."], ["وأسرّحكنّ سراحاً جميلاً", "أطلّقكنّ طلاقاً من غير إضرار."], ["تُردن الله ورسوله والدار الآخرة", "تُردن رضا الله ورسوله والجنة."], ["للمحسنات منكن", "في عشرة النبي ﷺ وطاعة الله."], ["بفاحشة مبيّنة", "بنشوز وسوء خلق يتأذّى به رسول الله ﷺ."], ["يُضاعف لها العذاب ضعفين", "مرتين على عذاب غيرها."]], "m": "لما رأت نساء النبي ﷺ نساء الأنصار والمهاجرين قد وُسّع عليهن في النفقة طالبن بالتوسعة أسوة بغيرهن، وكن تسعاً: عائشة، وحفصة، وأم حبيبة، وسودة، وأم سلمة، وزينب بنت جحش، وميمونة، وجويرية، وصفية، فتأثّر ﷺ لعدم القدرة على ما طُلب منه، واعتزلهن شهراً حتى نزلت آية التخيير: يا أيها النبي قل لأزواجك: إن كنتنّ تُردن الحياة الدنيا وزينتها فتعالين أعطكنّ متعة الطلاق وأطلّقكنّ طلاقاً لا إضرار معه، وإن كنتنّ تُردن رضا الله ورسوله والجنة فإن الله أعدّ للمحسنات منكنّ أجراً عظيماً. فبدأ بعائشة فقال: لا تقضي شيئاً حتى تستأمري أبويك، فاختارت الله ورسوله والدار الآخرة، وكذلك اخترن كلهن، فأكرمهن الله فحرّم على رسوله أن يتزوّج عليهن. يا نساء النبي من يأت منكنّ بخصلة قبيحة تؤذي رسول الله يضاعف لها العذاب ضعفين، لأن أذيّة الرسول من أبواب الكفر، ولشرف مقامهن، فذو المنزلة العالية يُستقبح منه القبيح أكثر، وكان ذلك على الله يسيراً.", "h": ["مشروعية تخيير الزوجات، فإن اخترن الطلاق طُلّقن، وإن لم يختَرنه بقين.", "كمال أزواج النبي ﷺ، حيث اخترن الله ورسوله والدار الآخرة على الحياة الدنيا وزينتها.", "مشروعية المتعة بعد الطلاق، وهي أن تُعطى المرأة شيئاً من المال بحسب غنى المطلّق وفقره.", "وجوب الإحسان العام والخاص: الخاص بين الزوجين، والعام في طاعة الله ورسوله.", "بيان أن سيئة العالم الشريف أسوأ من سيئة الجاهل الوضيع."], "k": "«وإن كنتنّ تُردن الله ورسوله والدار الآخرة»… حين يتعارض ما أشتهيه مع ما يرضيه، ماذا أختار؟"}]$j$::jsonb) with ordinality x(e, i);
select n, title, pub, (select count(*) from public.tdb_cards c where c.topic=t.n) cards from public.tdb_topics t where n>=36 order by n;